// =========================================================
// BRICK 307 — PERSISTENT ITEM EXECUTION CONTEXT
// =========================================================
//
// Reads existing Inventory / Equipment authority.
//
// It does not apply weapon Stats.
//
// =========================================================

function getBattleEquippedWeaponExecutionContext(
  character
) {


  if (
    !character ||
    !Array.isArray(
      character.equipment
    )
  ) {

    return null;
  }


  const equippedWeapon =
    character.equipment.find(
      equipment =>
        equipment &&
        equipment.slot ===
          "weapon"
    ) ||
    null;


  if (
    !equippedWeapon ||
    !equippedWeapon.instanceId ||
    !equippedWeapon.itemId
  ) {

    return null;
  }


  const definition =
    getItemDefinition(
      equippedWeapon.itemId
    );


  if (
    !definition ||
    definition.type !==
      "weapon"
  ) {

    return null;
  }


  const inventoryItem =
    playerData &&
    Array.isArray(
      playerData.inventory
    )

      ? playerData.inventory.find(
          item =>
            item &&
            item.instanceId ===
              equippedWeapon.instanceId
        ) ||
        null

      : null;


  if (
    !inventoryItem
  ) {

    return null;
  }


  return {

    instanceId:
      equippedWeapon.instanceId,

    itemId:
      equippedWeapon.itemId,

    weaponClass:
      definition.weaponClass ||
      null,

    persistentThrowingWeapon:
      definition
        .persistentThrowingWeapon ===
        true,

    persistentWeaponSet:
      definition
        .persistentWeaponSet ===
        true,

    definition:
      definition,

    inventoryItem:
      inventoryItem

  };
}


// =========================================================
// PERSISTENT TOOL AVAILABILITY CONTEXT
// =========================================================
//
// Current source has no carried-tool/loadout authority yet.
//
// Therefore this adapter answers only the truthful question:
//
// "Does the player's authoritative Inventory contain this
// persistent tool instance?"
//
// It does NOT claim the tool is equipped/prepared.
//
// =========================================================

function getBattleInventoryToolContext(
  itemId
) {


  const definition =
    getItemDefinition(
      itemId
    );


  if (
    !definition ||
    definition.type !==
      "tool"
  ) {

    return null;
  }


  const inventoryItem =
    playerData &&
    Array.isArray(
      playerData.inventory
    )

      ? playerData.inventory.find(
          item =>
            item &&
            item.id ===
              itemId &&
            item.instanceId
        ) ||
        null

      : null;


  if (
    !inventoryItem
  ) {

    return null;
  }


  return {

    instanceId:
      inventoryItem.instanceId,

    itemId:
      itemId,

    definition:
      definition,

    inventoryItem:
      inventoryItem

  };
}


