// =========================================================
// NORMALIZE SAVED RUN PROGRESSION
// =========================================================

function normalizeSavedRunProgression(
  savedProgression
) {


  const defaults =
    createDefaultRunProgression();


  if (
    !savedProgression ||
    typeof savedProgression !==
      "object"
  ) {

    return defaults;

  }


  const currentDifficulty =
    getShinobiDifficulty(
      savedProgression.currentDifficulty
    )
      ? savedProgression.currentDifficulty
      : defaults.currentDifficulty;


  const highestDifficultyUnlocked =
    getShinobiDifficulty(
      savedProgression.highestDifficultyUnlocked
    )
      ? savedProgression.highestDifficultyUnlocked
      : defaults.highestDifficultyUnlocked;


  return {

    currentDifficulty:
      currentDifficulty,

    highestDifficultyUnlocked:
      highestDifficultyUnlocked,

    legacyCycle:
      Math.max(
        0,
        Math.floor(
          Number(
            savedProgression.legacyCycle
          ) || 0
        )
      ),

    completedDifficulties:
      Array.isArray(
        savedProgression.completedDifficulties
      )
        ? savedProgression.completedDifficulties.filter(
            difficultyId =>
              !!getShinobiDifficulty(
                difficultyId
              )
          )
        : [],

    runCompleted:
      savedProgression.runCompleted ===
      true

  };

}

// =========================================================
// NORMALIZE DISCIPLINE PROGRESSION
// =========================================================

function normalizeDisciplineProgression(
  savedProgression
) {


  const defaults =
    createDefaultDisciplineProgression();


  const source =
    savedProgression &&
    typeof savedProgression ===
      "object"
      ? savedProgression
      : {};


  const normalized = {};


  Object.keys(
    defaults
  ).forEach(
    disciplineId => {


      const savedRecord =
        source[
          disciplineId
        ] || {};


      const level =
        Math.max(
          1,
          Math.floor(
            Number(
              savedRecord.level
            ) || 1
          )
        );


      const rawStatLevelApplied =
        savedRecord.statLevelApplied;


      const statLevelApplied =
        Number.isFinite(
          Number(
            rawStatLevelApplied
          )
        )
          ? Math.max(
              1,
              Math.min(
                level,
                Math.floor(
                  Number(
                    rawStatLevelApplied
                  )
                )
              )
            )
          : 1;


      normalized[
        disciplineId
      ] = {

        level:
          level,

        exp:
          Math.max(
            0,
            Number(
              savedRecord.exp
            ) || 0
          ),

        statLevelApplied:
          statLevelApplied

      };

    }
  );


  return normalized;

}


// NORMALIZE SAVED CHARACTER PROGRESSION
// =========================================================

function normalizeSavedCharacterProgression(
  savedCharacters
) {


  const defaults =
    createDefaultCharacterProgression();


  const source =
    savedCharacters &&
    typeof savedCharacters ===
      "object"
      ? savedCharacters
      : {};


  const normalized = {};


  Object.keys(
    defaults
  ).forEach(
    characterId => {


      const defaultCharacter =
        defaults[
          characterId
        ];


      const savedCharacter =
        source[
          characterId
        ] || {};


      const savedStats =
        savedCharacter.stats &&
        typeof savedCharacter.stats ===
          "object"
          ? savedCharacter.stats
          : {};


      const normalizedStats = {
        ...defaultCharacter.stats
      };


      Object.keys(
        normalizedStats
      ).forEach(
        stat => {


          if (
            typeof savedStats[
              stat
            ] ===
              "number"
          ) {

            normalizedStats[
              stat
            ] =
              savedStats[
                stat
              ];

          }

        }
      );


      normalized[
        characterId
      ] = {

        stats:
          normalizedStats,

        permanentPLBonus:
          typeof savedCharacter
            .permanentPLBonus ===
            "number"

            ? savedCharacter
                .permanentPLBonus

            : defaultCharacter
                .permanentPLBonus,

        disciplineProgression:
          normalizeDisciplineProgression(
            savedCharacter
              .disciplineProgression
          ),

        weaponSpecializations:
          savedCharacter
            .weaponSpecializations &&
          typeof savedCharacter
            .weaponSpecializations ===
            "object"

            ? cloneProgressionData(
                savedCharacter
                  .weaponSpecializations
              )

            : cloneProgressionData(
                defaultCharacter
                  .weaponSpecializations
              )

      };

    }
  );


  return normalized;

}


