// =========================================================
// GET INHERITANCE LIMITS
// =========================================================

function getInheritanceLimits(
  difficultyId
) {


  const difficulty =
    getShinobiDifficulty(
      difficultyId
    );


  if (!difficulty) {

    return null;

  }


  const limits =
    INHERITANCE_LIMITS[
      difficultyId
    ];


  if (!limits) {

    return null;

  }


  return {

    ...limits

  };

}


// =========================================================
// BRICK 37 — NEXT RUN TARGET
// =========================================================

function getNextRunTarget() {


  const runState =
    getCurrentRunState();


  if (!runState.valid) {


    return {

      valid:
        false,

      reason:
        runState.reason

    };

  }


  const nextDifficulty =
    getNextShinobiDifficulty(
      runState.currentDifficultyId
    );


  // =========================================
  // NORMAL NEW GAME+
  // =========================================

  if (nextDifficulty) {


    return {

      valid:
        true,

      transitionType:
        "difficulty",

      fromDifficultyId:
        runState.currentDifficultyId,

      fromDifficultyName:
        runState.currentDifficultyName,

      targetDifficultyId:
        nextDifficulty.id,

      targetDifficultyName:
        nextDifficulty.name,

      targetLegacyCycle:
        runState.legacyCycle,

      inheritanceLimits:
        getInheritanceLimits(
          nextDifficulty.id
        )

    };

  }


  // =========================================
  // JINCHURIKI → LEGACY
  // =========================================

  if (
    runState.currentDifficultyId ===
      "jinchuriki"
  ) {


    return {

      valid:
        true,

      transitionType:
        "legacy",

      fromDifficultyId:
        "jinchuriki",

      fromDifficultyName:
        "Jinchūriki",

      targetDifficultyId:
        "academy",

      targetDifficultyName:
        "Academy Student",

      targetLegacyCycle:
        runState.legacyCycle + 1,

      inheritanceLimits:
        null

    };

  }


  return {

    valid:
      false,

    reason:
      "No valid next run target exists."

  };

}


// =========================================================
// BRICK 38 — INHERITANCE SELECTION MODEL
// =========================================================

function createEmptyInheritanceSelection() {


  return {

    specialNinja:
      [],

    bloodlines:
      [],

    legendaryWeapons:
      [],

    basicItems:
      []

  };

}


// =========================================================
// NORMALIZE INHERITANCE SELECTION
// =========================================================

function normalizeInheritanceSelection(
  selection
) {


  const source =
    (
      selection &&
      typeof selection ===
        "object"
    )
      ? selection
      : {};


  const normalizeArray =
    value => {


      if (
        !Array.isArray(
          value
        )
      ) {

        return [];

      }


      return [
        ...new Set(
          value.filter(
            entry =>
              (
                typeof entry ===
                  "string" &&
                entry.trim().length >
                  0
              )
          )
        )
      ];

    };


  return {

    specialNinja:
      normalizeArray(
        source.specialNinja
      ),

    bloodlines:
      normalizeArray(
        source.bloodlines
      ),

    legendaryWeapons:
      normalizeArray(
        source.legendaryWeapons
      ),

    basicItems:
      normalizeArray(
        source.basicItems
      )

  };

}


// =========================================================
// BRICK 39 — INHERITANCE SELECTION VALIDATION
// =========================================================

function validateInheritanceSelection(
  targetDifficultyId,
  selection
) {


  const limits =
    getInheritanceLimits(
      targetDifficultyId
    );


  if (!limits) {


    return {

      valid:
        false,

      reason:
        "Inheritance limits not found.",

      errors:
        []

    };

  }


  const normalized =
    normalizeInheritanceSelection(
      selection
    );


  const errors =
    [];


  Object.keys(
    limits
  ).forEach(
    category => {


      const selected =
        normalized[
          category
        ] || [];


      const maximum =
        limits[
          category
        ];


      if (
        selected.length >
          maximum
      ) {


        errors.push(
          `${category}: selected ${selected.length}, maximum ${maximum}.`
        );

      }

    }
  );


  return {

    valid:
      errors.length ===
      0,

    reason:
      errors.length === 0
        ? null
        : "Inheritance selection exceeds allowed limits.",

    errors:
      errors,

    selection:
      normalized,

    limits:
      limits

  };

}


// =========================================================
// BRICK 40 — BUILD NEXT RUN PAYLOAD
// =========================================================
//
// This does NOT modify the save.
//
// It creates the instruction package that the actual
// transition engine will use.
//
// =========================================================

function buildNextRunPayload(
  selection = {}
) {


  const target =
    getNextRunTarget();


  if (!target.valid) {


    return {

      valid:
        false,

      reason:
        target.reason

    };

  }


  // =========================================
  // LEGACY TRANSITION
  // =========================================
  //
  // Legacy does not use normal carryover limits.
  //
  // The completed collection is preserved and the
  // difficulty ladder begins again from Academy.
  //
  // =========================================

  if (
    target.transitionType ===
      "legacy"
  ) {


    return {

      valid:
        true,

      transitionType:
        "legacy",

      fromDifficultyId:
        target.fromDifficultyId,

      targetDifficultyId:
        "academy",

      targetLegacyCycle:
        target.targetLegacyCycle,

      preserveCollection:
        true

    };

  }


  // =========================================
  // NORMAL DIFFICULTY TRANSITION
  // =========================================

  const validation =
    validateInheritanceSelection(
      target.targetDifficultyId,
      selection
    );


  if (!validation.valid) {


    return {

      valid:
        false,

      reason:
        validation.reason,

      errors:
        validation.errors

    };

  }


  return {

    valid:
      true,

    transitionType:
      "difficulty",

    fromDifficultyId:
      target.fromDifficultyId,

    targetDifficultyId:
      target.targetDifficultyId,

    targetLegacyCycle:
      target.targetLegacyCycle,

    inheritance:
      validation.selection,

    inheritanceLimits:
      validation.limits

  };

}


// =========================================================
// BRICK 41 — TRANSITION SNAPSHOT / ROLLBACK
// =========================================================
//
// Before a real NG+ or Legacy transition we can create
// a complete snapshot of playerData.
//
// This gives us a recovery path if a transition fails.
//
// =========================================================

function createRunTransitionSnapshot() {


  return JSON.parse(
    JSON.stringify(
      playerData
    )
  );

}


// =========================================================
// RESTORE RUN TRANSITION SNAPSHOT
// =========================================================

function restoreRunTransitionSnapshot(
  snapshot
) {


  if (
    !snapshot ||
    typeof snapshot !==
      "object"
  ) {


    console.log(
      "Invalid run transition snapshot."
    );


    return false;

  }


  playerData =
    JSON.parse(
      JSON.stringify(
        snapshot
      )
    );


  // =========================================
  // RESTORE RUNTIME CHARACTER DATA
  // =========================================

  syncCharacterProgressionFromSave();


  // =========================================
  // RESTORE RUNTIME EQUIPMENT
  // =========================================

  syncCharacterEquipmentFromSave();


  // =========================================
  // SAVE RESTORED STATE
  // =========================================

  savePlayerData();


  console.log(
    "Run transition snapshot restored."
  );


  return true;

}


// =========================================================
// BRICK 42 — BUILD DIFFICULTY TRANSITION STATE
// =========================================================
//
// Pure helper.
//
// It calculates what the next run progression should
// look like WITHOUT changing playerData.
//
// This makes diagnostics safe.
//
// =========================================================

function buildDifficultyTransitionState(
  progression,
  payload
) {


  if (
    !progression ||
    typeof progression !==
      "object"
  ) {

    return null;

  }


  if (
    !payload ||
    payload.valid !==
      true ||
    payload.transitionType !==
      "difficulty"
  ) {

    return null;

  }


  const fromDifficulty =
    getShinobiDifficulty(
      payload.fromDifficultyId
    );


  const targetDifficulty =
    getShinobiDifficulty(
      payload.targetDifficultyId
    );


  if (
    !fromDifficulty ||
    !targetDifficulty
  ) {

    return null;

  }


  const currentDifficulty =
    getShinobiDifficulty(
      progression.currentDifficulty
    );


  if (
    !currentDifficulty ||
    currentDifficulty.id !==
      fromDifficulty.id
  ) {

    return null;

  }


  if (
    progression.runCompleted !==
      true
  ) {

    return null;

  }


  // =========================================
  // ONLY ALLOW THE IMMEDIATE NEXT DIFFICULTY
  // =========================================

  const expectedNext =
    getNextShinobiDifficulty(
      fromDifficulty.id
    );


  if (
    !expectedNext ||
    expectedNext.id !==
      targetDifficulty.id
  ) {

    return null;

  }


  const completedDifficulties =
    Array.isArray(
      progression.completedDifficulties
    )
      ? [
          ...progression.completedDifficulties
        ]
      : [];


  if (
    !completedDifficulties.includes(
      fromDifficulty.id
    )
  ) {


    completedDifficulties.push(
      fromDifficulty.id
    );

  }


  const currentHighest =
    getShinobiDifficulty(
      progression.highestDifficultyUnlocked
    );


  let highestDifficultyUnlocked =
    targetDifficulty.id;


  if (
    currentHighest &&
    currentHighest.order >
      targetDifficulty.order
  ) {


    highestDifficultyUnlocked =
      currentHighest.id;

  }


  return {

    currentDifficulty:
      targetDifficulty.id,

    highestDifficultyUnlocked:
      highestDifficultyUnlocked,

    legacyCycle:
      Math.max(
        0,
        Math.floor(
          Number(
            progression.legacyCycle
          ) || 0
        )
      ),

    completedDifficulties:
      completedDifficulties,

    runCompleted:
      false

  };

}


// =========================================================
// APPLY NORMAL NEW GAME+ DIFFICULTY TRANSITION
// =========================================================

function applyDifficultyTransition(
  payload
) {


  if (
    !playerData ||
    !playerData.progression
  ) {


    return {

      success:
        false,

      reason:
        "Player progression data not found."

    };

  }


  const nextProgression =
    buildDifficultyTransitionState(
      playerData.progression,
      payload
    );


  if (!nextProgression) {


    return {

      success:
        false,

      reason:
        "Difficulty transition state is invalid."

    };

  }


  const fromDifficulty =
    getShinobiDifficulty(
      payload.fromDifficultyId
    );


  const targetDifficulty =
    getShinobiDifficulty(
      payload.targetDifficultyId
    );


  playerData.progression =
    nextProgression;


  savePlayerData();


  console.log(
    `${fromDifficulty.name} → ${targetDifficulty.name} transition complete.`
  );


  return {

    success:
      true,

    transitionType:
      "difficulty",

    fromDifficultyId:
      fromDifficulty.id,

    fromDifficultyName:
      fromDifficulty.name,

    targetDifficultyId:
      targetDifficulty.id,

    targetDifficultyName:
      targetDifficulty.name,

    legacyCycle:
      nextProgression.legacyCycle,

    inheritance:
      payload.inheritance || {
        ...createEmptyInheritanceSelection()
      }

  };

}


// =========================================================
// BRICK 43 — BUILD LEGACY TRANSITION STATE
// =========================================================
//
// Pure helper.
//
// Jinchuriki completion closes the difficulty loop,
// increases the Legacy Cycle and returns the run ladder
// to Academy Student.
//
// Inventory / character collection data is NOT touched
// here.
//
// =========================================================

function buildLegacyTransitionState(
  progression
) {


  if (
    !progression ||
    typeof progression !==
      "object"
  ) {

    return null;

  }


  if (
    progression.currentDifficulty !==
      "jinchuriki"
  ) {

    return null;

  }


  if (
    progression.runCompleted !==
      true
  ) {

    return null;

  }


  const completed =
    Array.isArray(
      progression.completedDifficulties
    )
      ? progression.completedDifficulties
      : [];


  // =========================================
  // EVERY DIFFICULTY MUST HAVE BEEN COMPLETED
  // =========================================

  const fullCycleComplete =
    SHINOBI_DIFFICULTIES.every(
      difficulty =>
        completed.includes(
          difficulty.id
        )
    );


  if (!fullCycleComplete) {

    return null;

  }


  return {

    currentDifficulty:
      "academy",

    highestDifficultyUnlocked:
      "academy",

    legacyCycle:
      (
        Math.max(
          0,
          Math.floor(
            Number(
              progression.legacyCycle
            ) || 0
          )
        ) +
        1
      ),

    completedDifficulties:
      [],

    runCompleted:
      false

  };

}


// =========================================================
// APPLY LEGACY TRANSITION
// =========================================================

function applyLegacyTransition(
  payload
) {


  if (
    !payload ||
    payload.valid !==
      true ||
    payload.transitionType !==
      "legacy"
  ) {


    return {

      success:
        false,

      reason:
        "Invalid Legacy transition payload."

    };

  }


  const nextProgression =
    buildLegacyTransitionState(
      playerData.progression
    );


  if (!nextProgression) {


    return {

      success:
        false,

      reason:
        "Legacy transition requirements are not satisfied."

    };

  }


  playerData.progression =
    nextProgression;


  // =========================================
  // IMPORTANT — LEGACY COLLECTION PRESERVATION
  // =========================================
  //
  // We deliberately do NOT modify:
  //
  // playerData.inventory
  // playerData.characters
  // Ryō
  // collected equipment
  //
  // Detailed reset/preservation rules can later decide
  // which character training values reset and which
  // permanent Legacy rewards survive.
  //
  // =========================================


  savePlayerData();


  console.log(
    `LEGACY CYCLE ${nextProgression.legacyCycle} BEGUN.`
  );


  console.log(
    "New Academy Student run started."
  );


  return {

    success:
      true,

    transitionType:
      "legacy",

    targetDifficultyId:
      "academy",

    targetDifficultyName:
      "Academy Student",

    legacyCycle:
      nextProgression.legacyCycle,

    preserveCollection:
      true

  };

}


// =========================================================
// BRICK 44 — UNIFIED NEXT RUN TRANSITION
// =========================================================

function executeNextRunTransition(
  selection = {},
  options = {}
) {


  if (
    !playerData ||
    !playerData.progression
  ) {


    return {

      success:
        false,

      reason:
        "Player progression data not found."

    };

  }


  // =========================================
  // COMPLETE CURRENT RUN IF REQUIRED
  // =========================================

  if (
    playerData.progression.runCompleted !==
      true
  ) {


    const eligibility =
      getRunCompletionEligibility();


    if (!eligibility.allowed) {


      return {

        success:
          false,

        reason:
          eligibility.reason

      };

    }


    const completed =
      completeCurrentDifficulty();


    if (!completed) {


      return {

        success:
          false,

        reason:
          "Current difficulty could not be completed."

      };

    }

  }


  // =========================================
  // BUILD TRANSITION PAYLOAD
  // =========================================

  const payload =
    buildNextRunPayload(
      selection
    );


  if (!payload.valid) {


    return {

      success:
        false,

      reason:
        payload.reason,

      errors:
        payload.errors || []

    };

  }


  // =========================================
  // PREMIUM DIFFICULTY GATE
  // =========================================

  if (
    payload.transitionType ===
      "difficulty" &&
    isPremiumDifficulty(
      payload.targetDifficultyId
    ) &&
    options.hasPremiumAccess !==
      true
  ) {


    const targetDifficulty =
      getShinobiDifficulty(
        payload.targetDifficultyId
      );


    return {

      success:
        false,

      runCompleted:
        true,

      transitionPending:
        true,

      reason:
        "Premium access required.",

      targetDifficultyId:
        targetDifficulty.id,

      targetDifficultyName:
        targetDifficulty.name

    };

  }


  // =========================================
  // LEGACY
  // =========================================

  if (
    payload.transitionType ===
      "legacy"
  ) {


    return applyLegacyTransition(
      payload
    );

  }


  // =========================================
  // NORMAL NEW GAME+
  // =========================================

  return applyDifficultyTransition(
    payload
  );

}


