// =========================================================


function openKonohaPracticalFromVillage() {


  const overlay =
    document.getElementById(
      "screen-overlay"
    );


  if (overlay) {

    overlay.style.display =
      "none";

  }


  const result =
    showKonohaActivityUIScreen(
      "practical"
    );


  if (
    !result ||
    result.success !==
      true
  ) {


    if (overlay) {

      overlay.style.display =
        "flex";

    }


    return result;

  }


  return result;

}


