// =========================================================
// BRICK 115 — ACTIVITY RESULT HYDRATION
// =========================================================
//
// Converts structured Activity rewards
// into the universal Result format.
//
// Routes:
// - EXP → result.rewards.exp
// - Ryō → result.rewards.ryo
// - Items → result.rewards.items
// - Discipline → result.rewards.progression
//
// =========================================================


function hydrateActivityResult(
  result,
  activity
) {


  if (
    !result ||
    !result.rewards ||
    !activity
  ) {


    console.log(
      "Invalid activity hydration request."
    );


    return false;


  }



  if (
    !Array.isArray(
      activity.rewards
    )
  ) {


    return result;


  }



  activity.rewards.forEach(
    reward => {


      if (
        !reward ||
        !reward.type
      ) {


        return;


      }



      switch (
        reward.type
      ) {


        case "experience":


          result.rewards.exp +=
            Number(
              reward.amount
            ) || 0;


          break;



        case "currency":


          if (
            reward.id ===
              "ryo"
          ) {


            result.rewards.ryo +=
              Number(
                reward.amount
              ) || 0;


          }


          break;



        case "discipline":


          if (
            !Array.isArray(
              result.rewards.progression
            )
          ) {


            result.rewards.progression =
              [];


          }



          result.rewards.progression.push(
            {
              ...reward
            }
          );


          break;



        case "item":


          if (
            !Array.isArray(
              result.rewards.items
            )
          ) {


            result.rewards.items =
              [];


          }



          result.rewards.items.push(
            {
              ...reward
            }
          );


          break;


      }


    }
  );



  console.log(
    "Activity Result Hydrated:",
    result
  );



  return result;


}

// =========================================================
// BRICK 135 — DATA-DRIVEN ACTIVITY EXECUTOR
// =========================================================
//
// Executes activity definitions that do not live directly
// inside ACTIVITY_DATABASE.
//
// Used by:
// - Training variants
// - Future events
// - Dungeons
// - Encounters
//
// Uses the same Result / Reward / Progression / Chronicle
// authorities as registered activities.
//
// =========================================================


function executeActivityDefinition(
  activityId,
  characterId,
  activityDefinition
) {


  if (
    !activityId ||
    !activityDefinition
  ) {


    console.log(
      "Invalid data-driven activity definition."
    );


    return false;


  }



  const character =
    getPlayerCharacter(
      characterId
    );



  if (
    !character
  ) {


    console.log(
      "Data-driven activity character not found:",
      characterId
    );


    return false;


  }



  const result =
    createActivityResult(
      activityId,
      characterId
    );



  if (
    !result
  ) {


    return false;


  }



  if (
    !hydrateActivityResult(
      result,
      activityDefinition
    )
  ) {


    return false;


  }



  if (
    !applyActivityRewards(
      result
    )
  ) {


    return false;


  }



  if (
    !processActivityProgression(
      result
    )
  ) {


    return false;


  }



  // =========================================
  // BRICK 557 — FINALISE HISTORICAL COMPLETION
  // =========================================
  //
  // Reaching this point means the Activity lifecycle committed
  // and completed. Intended outcome success remains independent.
  //
  // =========================================

  result.completed =
    true;


  if (
    !result.outcome
  ) {


    result.outcome =
      result.success === true
        ? "success"
        : "failure";


  }


  if (
    !recordActivityCompletion(
      result
    )
  ) {


    return false;


  }



  console.log(
    "DATA-DRIVEN ACTIVITY COMPLETED:",
    result
  );



  return result;


}


// =========================================================
// BRICK 125 — REGISTERED ACTIVITY COMPLETION AUTHORITY
// =========================================================
//
// Controls the complete registered Activity lifecycle.
//
// Activity
// ↓
// Validation
// ↓
// Result
// ↓
// Hydration
// ↓
// Rewards
// ↓
// Progression
// ↓
// Completion Record
//
// An Activity is only recorded as complete
// after all required execution stages succeed.
//
// =========================================================


function startRegisteredActivity(
  action,
  characterId
) {


  // =========================================
  // VALIDATE REQUEST
  // =========================================


  if (
    !validateActivityRequest(
      action,
      characterId
    )
  ) {


    console.log(
      "Activity request rejected:",
      action,
      characterId
    );


    return false;


  }



  // =========================================
  // VALIDATE REQUIREMENTS
  // =========================================


  if (
    !validateActivityRequirements(
      action
    )
  ) {


    console.log(
      "Activity requirements rejected:",
      action
    );


    return false;


  }



  // =========================================
  // RESOLVE ACTIVITY
  // =========================================


  const activity =
    resolveActivityAction(
      action
    );



  if (
    !activity
  ) {


    console.log(
      "Unknown activity:",
      action
    );


    return false;


  }



  console.log(
    "REGISTERED ACTIVITY START:",
    activity
  );



  // =========================================
  // CREATE RESULT
  // =========================================


  const result =
    createActivityResult(
      action,
      characterId
    );



  if (
    !result
  ) {


    console.log(
      "Activity result creation failed."
    );


    return false;


  }



  // =========================================
  // HYDRATE RESULT
  // =========================================


  const hydrated =
    hydrateActivityResult(
      result,
      activity
    );



  if (
    !hydrated
  ) {


    console.log(
      "Activity result hydration failed."
    );


    return false;


  }



  // =========================================
  // APPLY REWARDS
  // =========================================


  const rewardsApplied =
    applyActivityRewards(
      result
    );



  if (
    !rewardsApplied
  ) {


    console.log(
      "Activity reward application failed."
    );


    return false;


  }



  // =========================================
  // PROCESS PROGRESSION
  // =========================================


  const progressionApplied =
    processActivityProgression(
      result
    );



  if (
    !progressionApplied
  ) {


    console.log(
      "Activity progression execution failed."
    );


    return false;


  }



  // =========================================
  // BRICK 557 — FINALISE HISTORICAL COMPLETION
  // =========================================
  //
  // Reaching this point means the Activity lifecycle committed
  // and completed. Intended outcome success remains independent.
  //
  // =========================================

  result.completed =
    true;


  if (
    !result.outcome
  ) {


    result.outcome =
      result.success === true
        ? "success"
        : "failure";


  }


  // =========================================
  // RECORD COMPLETION
  // =========================================


  const completionRecorded =
    recordActivityCompletion(
      result
    );



  if (
    !completionRecorded
  ) {


    console.log(
      "Activity completion recording failed."
    );


    return false;


  }



  console.log(
    "ACTIVITY COMPLETED:",
    result
  );



  return result;


}

// =========================================================
// BRICK 119 — ACTIVITY RESULT FOUNDATION
// BRICK 557 — COMPLETION / OUTCOME SEPARATION
// =========================================================
//
// Core Chronicle Engine Result System.
//
// Creates one normalized result structure
// for every Activity Engine outcome.
//
// Activity
// ↓
// Result
// ↓
// Rewards
// ↓
// Progression
//
// =========================================================


function createActivityResult(
  activityId,
  characterId
) {


  if (
    !activityId
  ) {


    console.log(
      "Cannot create Activity Result without an activity ID."
    );


    return false;


  }



  return {


    activity:
      activityId,


    character:
      characterId || null,


    completed:
      false,


    success:
      true,


    outcome:
      null,


    rewards: {


      exp:
        0,


      ryo:
        0,


      items:
        [],


      progression:
        []


    }


  };


}


// =========================================================
// BRICK 121 — RANDOM COMMON ITEM RESOLVER
// =========================================================
//
// Resolves abstract "random_common" Activity rewards
// into real Item Database definitions.
//
// Uses the existing Item Database as authority.
//
// =========================================================


// =========================================================
// GET COMMON ITEM DEFINITIONS
// =========================================================

function getCommonItemDefinitions() {


  return Object.values(
    itemDatabase
  ).filter(
    item =>
      item &&
      item.rarity ===
        "Common"
  );


}



// =========================================================
// GET RANDOM COMMON ITEM
// =========================================================

function getRandomCommonItem() {


  const commonItems =
    getCommonItemDefinitions();



  if (
    commonItems.length ===
      0
  ) {


    console.log(
      "No Common items available."
    );


    return null;


  }



  const randomIndex =
    Math.floor(
      Math.random() *
      commonItems.length
    );



  return commonItems[
    randomIndex
  ];


}

// =========================================================
// BRICK 118 — ACTIVITY REWARD PROCESSOR
// =========================================================
//
// Applies hydrated Activity Result rewards.
//
// Handles:
// - EXP
// - Ryō
// - Direct item rewards
// - Random Common item rewards
//
// =========================================================


function applyActivityRewards(
  result
) {


  if (
    !result ||
    !result.rewards
  ) {


    console.log(
      "Invalid activity reward result."
    );


    return false;


  }



  // =========================================
  // EXP
  // =========================================


  if (
    typeof result.rewards.exp ===
      "number"
  ) {


    playerData.exp +=
      result.rewards.exp;


  }



  // =========================================
  // RYO
  // =========================================


  if (
    typeof result.rewards.ryo ===
      "number"
  ) {


    playerData.ryo +=
      result.rewards.ryo;


  }



  // =========================================
  // ITEMS
  // =========================================


  if (
    Array.isArray(
      result.rewards.items
    )
  ) {


    result.rewards.items.forEach(
      itemReward => {


        if (
          !itemReward
        ) {


          return;


        }



        // =========================================
        // RANDOM COMMON ITEM
        // =========================================


        if (
          itemReward.id ===
            "random_common"
        ) {


          const amount =
            Math.max(
              1,
              Math.floor(
                Number(
                  itemReward.amount
                ) || 1
              )
            );



          for (
            let i = 0;
            i < amount;
            i++
          ) {


            const randomItem =
              getRandomCommonItem();



            if (
              !randomItem
            ) {


              continue;


            }



            addItemToInventory({

              id:
                randomItem.id,

              name:
                randomItem.name

            });



            console.log(
              "Random Common reward:",
              randomItem.name
            );


          }



          return;


        }



        // =========================================
        // DIRECT ITEM
        // =========================================


        const definition =
          getItemDefinition(
            itemReward.id
          );



        if (
          !definition
        ) {


          console.log(
            "Unknown activity item reward:",
            itemReward.id
          );


          return;


        }



        const amount =
          Math.max(
            1,
            Math.floor(
              Number(
                itemReward.amount
              ) || 1
            )
          );



        for (
          let i = 0;
          i < amount;
          i++
        ) {


          addItemToInventory({

            id:
              definition.id,

            name:
              definition.name

          });


        }


      }
    );


  }



  console.log(
    "Activity rewards applied:",
    result.rewards
  );



  return true;


}

// =========================================================
// TASK 6.4 — ACTIVITY COMPLETION LIFECYCLE
// =========================================================
//
// Records completed activities.
//
// Creates foundation for:
// - Activity history
// - Achievements
// - Chronicle events
// - Future progression
//
// =========================================================


// =========================================================
// ACTIVITY HISTORY STORAGE
// =========================================================


let activityHistory = [];



// =========================================================
// RESTORE ACTIVITY HISTORY
// =========================================================

function restoreActivityHistory() {


  if (
    !playerData
  ) {


    return false;


  }



  if (
    !Array.isArray(
      playerData.activityHistory
    )
  ) {


    playerData.activityHistory = [];


  }



  activityHistory =
    playerData.activityHistory;



  console.log(
    "Activity history restored."
  );



  return true;


}



// =========================================================
// SYNC ACTIVITY HISTORY
// =========================================================

function syncActivityHistory() {


  if (
    !playerData
  ) {


    return false;


  }



  playerData.activityHistory =
    activityHistory;



  return true;


}

// =========================================================
// BRICK 126 — CHRONICLE ACTIVITY COMPLETION RECORD
// BRICK 557 — HISTORICAL ELIGIBILITY REBASE
// BRICK 642 — ACTIVE KONOHA HISTORY SCOPE ADDRESSABILITY
// =========================================================
//
// Stores genuinely completed Activity Results as persistent
// Chronicle-compatible history records.
//
// Historical eligibility is based on committed completion,
// NOT on whether the intended outcome succeeded.
//
// Records:
// - Activity
// - Character
// - Completed
// - Intended outcome success/failure
// - Outcome
// - EXP
// - Ryō
// - Item rewards
// - Progression rewards
// - Timestamp
//
// =========================================================


function createActivityCompletionRecord(
  result
) {


  if (
    !result ||
    !result.activity ||
    result.completed !==
      true ||
    typeof result.success !==
      "boolean"
  ) {


    return null;
  }


  const rewards =
    result.rewards ||
    {};


  return {


    historyScope:
      getCurrentChronicleOccurrenceHistoryScope("activity"),


    activity:
      result.activity,


    character:
      result.character ||
      null,


    completed:
      true,


    success:
      result.success,


    outcome:
      result.outcome ||
      (
        result.success === true
          ? "success"
          : "failure"
      ),


    rewards: {


      exp:
        Number(
          rewards.exp
        ) || 0,


      ryo:
        Number(
          rewards.ryo
        ) || 0,


      items:
        Array.isArray(
          rewards.items
        )
          ? rewards.items.map(
              item => ({

                id:
                  item.id,

                amount:
                  Number(
                    item.amount
                  ) || 1

              })
            )
          : [],


      progression:
        Array.isArray(
          rewards.progression
        )
          ? rewards.progression.map(
              reward => ({

                type:
                  reward.type,

                id:
                  reward.id,

                amount:
                  Number(
                    reward.amount
                  ) || 0

              })
            )
          : []


    },


    timestamp:
      Number(
        result.timestamp
      ) || Date.now()


  };
}


function recordActivityCompletion(
  result
) {


  const record =
    createActivityCompletionRecord(
      result
    );


  if (
    !record
  ) {


    console.log(
      "Invalid or incomplete activity history record."
    );


    return false;
  }


  activityHistory.push(
    record
  );


  syncActivityHistory();


  savePlayerData();


  console.log(
    "Chronicle activity recorded:",
    record.activity,
    record.outcome
  );


  return true;


}


// =========================================================
// BRICK 558 — POST-554 CE DRIFT REGRESSION DIAGNOSTIC
// =========================================================
//
// Proves:
// - viewing a Mission is availability only;
// - Mission view does not change rewards/inventory/history;
// - Mission UI still opens;
// - completion requires an explicit stage + character;
// - completed failed outcomes are representable as history;
// - uncompleted failures are not recordable history.
//
// Diagnostic is non-destructive: it does not persist a test
// history record or execute Mission completion.
//
// =========================================================


function runPost554CeDriftDiagnostics() {


  const originalSelectedLocationNode =
    selectedLocationNode;


  const originalOpenOverlay =
    openOverlay;


  const expBefore =
    Number(
      playerData.exp
    ) || 0;


  const ryoBefore =
    Number(
      playerData.ryo
    ) || 0;


  const inventoryBefore =
    JSON.stringify(
      Array.isArray(
        playerData.inventory
      )
        ? playerData.inventory
        : []
    );


  const historyCountBefore =
    getActivityHistory()
      .length;


  let openedOverlay =
    null;


  let availability =
    null;


  let completionWithoutCharacter =
    null;


  let failedCompletedRecord =
    null;


  let uncompletedFailureRecord =
    null;


  try {


    openOverlay =
      function diagnosticOpenOverlay(
        type
      ) {


        openedOverlay =
          type;


        return true;
      };


    selectedLocationNode = {

      id:
        "diagnostic_mission_location",

      type:
        "mission",

      name:
        "Diagnostic Mission"

    };


    // Uses the real map-navigation path. The only substituted
    // dependency is presentation rendering itself.
    handleNodeNavigation();


    availability =
      processPlayerActivity({

        type:
          PLAYER_ACTIVITY_TYPES.MISSION,

        stage:
          "available",

        location:
          "diagnostic_mission_location"

      });


    completionWithoutCharacter =
      processPlayerActivity({

        type:
          PLAYER_ACTIVITY_TYPES.MISSION,

        stage:
          "completion"

      });


    const failedCompletedResult =
      createActivityResult(
        "diagnostic_failed_completed_activity",
        null
      );


    failedCompletedResult.completed =
      true;


    failedCompletedResult.success =
      false;


    failedCompletedResult.outcome =
      "failure";


    failedCompletedRecord =
      createActivityCompletionRecord(
        failedCompletedResult
      );


    const uncompletedFailureResult =
      createActivityResult(
        "diagnostic_uncompleted_failure",
        null
      );


    uncompletedFailureResult.success =
      false;


    uncompletedFailureResult.outcome =
      "failure";


    uncompletedFailureRecord =
      createActivityCompletionRecord(
        uncompletedFailureResult
      );


  }
  finally {


    openOverlay =
      originalOpenOverlay;


    selectedLocationNode =
      originalSelectedLocationNode;


  }


  const result = {


    missionAvailabilityAccepted:
      !!(
        availability &&
        availability.success ===
          true &&
        availability.type ===
          "mission_available"
      ),


    missionOverlayExposed:
      openedOverlay ===
        "missions",


    missionViewDidNotChangeExp:
      (
        Number(
          playerData.exp
        ) || 0
      ) ===
        expBefore,


    missionViewDidNotChangeRyo:
      (
        Number(
          playerData.ryo
        ) || 0
      ) ===
        ryoBefore,


    missionViewDidNotChangeInventory:
      JSON.stringify(
        Array.isArray(
          playerData.inventory
        )
          ? playerData.inventory
          : []
      ) ===
        inventoryBefore,


    missionViewDidNotAppendHistory:
      getActivityHistory()
        .length ===
        historyCountBefore,


    completionWithoutCharacterRejected:
      completionWithoutCharacter ===
        false,


    failedCompletedOutcomeRecordable:
      !!(
        failedCompletedRecord &&
        failedCompletedRecord.completed ===
          true &&
        failedCompletedRecord.success ===
          false &&
        failedCompletedRecord.outcome ===
          "failure"
      ),


    uncompletedFailureNotRecordable:
      uncompletedFailureRecord ===
        null


  };


  result.pass =
    Object.values(
      result
    ).every(
      value =>
        value === true
    );


  console.table(
    result
  );


  return result;
}

// =========================================================
// BRICK 110 — APPLY SAVED ACTIVITY HISTORY
// =========================================================
//
// Restores persisted Activity History
// into the runtime Activity Engine.
//
// =========================================================


restoreActivityHistory();

// =========================================================
// BRICK 111 — ACTIVITY HISTORY QUERY
// =========================================================
//
// Provides safe read access to Activity History.
//
// Used by:
// - Activity analytics
// - Chronicle systems
// - Future achievements
//
// =========================================================


// =========================================================
// GET ACTIVITY HISTORY
// =========================================================

function getActivityHistory() {


  if (
    !Array.isArray(
      activityHistory
    )
  ) {


    return [];


  }



  return activityHistory;


}

// =========================================================
// BRICK 160 — BATTLE CHRONICLE ANALYTICS
// =========================================================


function getBattleAnalytics() {


  const battles =
    getActivityHistory()
      .filter(
        entry =>
          entry &&
          entry.type ===
            "battle"
      );


  const analytics = {


    totalBattles:
      battles.length,


    victories:
      0,


    totalExpEarned:
      0,


    totalRyoEarned:
      0,


    totalItemsEarned:
      0,


    enemyCounts:
      {},


    characterCounts:
      {},


    mvpCounts:
      {}


  };


  battles.forEach(
    battle => {


      if (
        battle.success
      ) {


        analytics.victories++;


      }


      analytics.totalExpEarned +=
        Number(
          battle.rewards &&
          battle.rewards.exp
        ) || 0;


      analytics.totalRyoEarned +=
        Number(
          battle.rewards &&
          battle.rewards.ryo
        ) || 0;


      if (
        battle.rewards &&
        Array.isArray(
          battle.rewards.items
        )
      ) {


        battle.rewards.items.forEach(
          item => {


            analytics.totalItemsEarned +=
              Number(
                item.amount
              ) || 1;


          }
        );


      }


      if (
        battle.enemyId
      ) {


        analytics.enemyCounts[
          battle.enemyId
        ] =
          (
            analytics.enemyCounts[
              battle.enemyId
            ] ||
            0
          ) + 1;


      }


      if (
        battle.character
      ) {


        analytics.characterCounts[
          battle.character
        ] =
          (
            analytics.characterCounts[
              battle.character
            ] ||
            0
          ) + 1;


      }


      if (
        battle.mvp &&
        battle.mvp.id
      ) {


        analytics.mvpCounts[
          battle.mvp.id
        ] =
          (
            analytics.mvpCounts[
              battle.mvp.id
            ] ||
            0
          ) + 1;


      }


    }
  );


  console.log(
    "Battle Chronicle analytics:",
    analytics
  );


  return analytics;


}

// =========================================================
// BRICK 161 — ENCOUNTER ANALYTICS
// =========================================================


function getEncounterAnalytics() {


  const battles =
    getActivityHistory()
      .filter(
        entry =>
          entry &&
          entry.type ===
            "battle" &&
          entry.encounterId
      );


  const analytics = {


    totalEncounterBattles:
      battles.length,


    encounterCounts:
      {},


    mostPlayedEncounter:
      null


  };


  battles.forEach(
    battle => {


      analytics.encounterCounts[
        battle.encounterId
      ] =
        (
          analytics.encounterCounts[
            battle.encounterId
          ] ||
          0
        ) + 1;


    }
  );


  Object.keys(
    analytics.encounterCounts
  ).forEach(
    encounterId => {


      if (
        !analytics.mostPlayedEncounter ||
        analytics.encounterCounts[
          encounterId
        ] >
        analytics.encounterCounts[
          analytics.mostPlayedEncounter
        ]
      ) {


        analytics.mostPlayedEncounter =
          encounterId;


      }


    }
  );


  console.log(
    "Encounter analytics:",
    analytics
  );


  return analytics;


}

// =========================================================
// BRICK 163 — BATTLE CHRONICLE HISTORY QUERY
// =========================================================
//
// Canonical read authority for recorded Battles.
//
// =========================================================


function getBattleHistory() {


  return getActivityHistory()
    .filter(
      entry =>
        entry &&
        entry.type ===
          "battle"
    );


}



// =========================================================
// BRICK 164 — ENCOUNTER BATTLE HISTORY QUERY
// =========================================================


function getEncounterBattleHistory(
  encounterId
) {


  if (
    !encounterId
  ) {


    return [];


  }


  return getBattleHistory()
    .filter(
      battle =>
        battle.encounterId ===
          encounterId
    );


}



// =========================================================
// BRICK 165 — ENEMY BATTLE HISTORY QUERY
// =========================================================


function getEnemyBattleHistory(
  enemyId
) {


  if (
    !enemyId
  ) {


    return [];


  }


  return getBattleHistory()
    .filter(
      battle =>
        battle.enemyId ===
          enemyId
    );


}



// =========================================================
// BRICK 166 — CHARACTER BATTLE HISTORY QUERY
// =========================================================


function getCharacterBattleHistory(
  characterId
) {


  if (
    !characterId
  ) {


    return [];


  }


  return getBattleHistory()
    .filter(
      battle =>
        battle.character ===
          characterId
    );


}



// =========================================================
// BRICK 167 — ENCOUNTER COMPLETION STATE
// =========================================================
//
// Provides reusable gameplay knowledge:
//
// "Has this Encounter ever been defeated?"
//
// =========================================================


function hasCompletedEncounter(
  encounterId
) {


  return getEncounterBattleHistory(
    encounterId
  ).some(
    battle =>
      battle.success ===
        true
  );


}



// =========================================================
// BRICK 168 — ENCOUNTER VICTORY COUNT
// =========================================================


function getEncounterVictoryCount(
  encounterId
) {


  return getEncounterBattleHistory(
    encounterId
  ).filter(
    battle =>
      battle.success ===
        true
  ).length;


}



// =========================================================
// BRICK 169 — ENEMY DEFEAT COUNT
// =========================================================
//
// Foundation for:
//
// - Rogue Shinobi Defeated
// - Enemy achievements
// - Unlock requirements
// - Chronicle milestones
//
// =========================================================


function getEnemyDefeatCount(
  enemyId
) {


  return getEnemyBattleHistory(
    enemyId
  ).filter(
    battle =>
      battle.success ===
        true
  ).length;


}



// =========================================================
// BRICK 170 — BATTLE CHRONICLE SUMMARY BRIDGE
// =========================================================
//
// Produces one gameplay-facing summary from
// Battle Chronicle records.
//
// Filters are optional.
//
// =========================================================


function getBattleChronicleSummary(
  filters = {}
) {


  let battles =
    getBattleHistory();


  if (
    filters.encounterId
  ) {


    battles =
      battles.filter(
        battle =>
          battle.encounterId ===
            filters.encounterId
      );


  }


  if (
    filters.enemyId
  ) {


    battles =
      battles.filter(
        battle =>
          battle.enemyId ===
            filters.enemyId
      );


  }


  if (
    filters.characterId
  ) {


    battles =
      battles.filter(
        battle =>
          battle.character ===
            filters.characterId
      );


  }


  const summary = {


    totalBattles:
      battles.length,


    victories:
      0,


    totalExp:
      0,


    totalRyo:
      0,


    totalItems:
      0,


    latestBattle:
      null


  };


  battles.forEach(
    battle => {


      if (
        battle.success ===
          true
      ) {


        summary.victories++;


      }


      if (
        battle.rewards
      ) {


        summary.totalExp +=
          Number(
            battle.rewards.exp
          ) || 0;


        summary.totalRyo +=
          Number(
            battle.rewards.ryo
          ) || 0;


        if (
          Array.isArray(
            battle.rewards.items
          )
        ) {


          battle.rewards.items.forEach(
            item => {


              summary.totalItems +=
                Number(
                  item.amount
                ) || 1;


            }
          );


        }


      }


    }
  );


  if (
    battles.length > 0
  ) {


    summary.latestBattle =
      battles[
        battles.length - 1
      ];


  }


  return summary;


}



// =========================================================
// BRICK 171 — BATTLE CHRONICLE QUERY HEALTH
// =========================================================
//
// Non-destructive diagnostics.
//
// =========================================================


function validateBattleChronicleQueries() {


  const battleHistory =
    getBattleHistory();


  const checks = {


    battleHistory:
      Array.isArray(
        battleHistory
      ),


    encounterHistory:
      Array.isArray(
        getEncounterBattleHistory(
          "scout_patrol"
        )
      ),


    enemyHistory:
      Array.isArray(
        getEnemyBattleHistory(
          "scout"
        )
      ),


    characterHistory:
      Array.isArray(
        getCharacterBattleHistory(
          "naruto"
        )
      ),


    encounterCompletion:
      typeof hasCompletedEncounter(
        "scout_patrol"
      ) ===
        "boolean",


    encounterCount:
      Number.isFinite(
        getEncounterVictoryCount(
          "scout_patrol"
        )
      ),


    enemyCount:
      Number.isFinite(
        getEnemyDefeatCount(
          "scout"
        )
      ),


    summary:
      !!getBattleChronicleSummary()


  };


  checks.healthy =
    Object.values(
      checks
    ).every(
      value =>
        value === true
    );


  console.log(
    "Battle Chronicle Query health:",
    checks
  );


  return checks;


}

// =========================================================
// BRICK 173 — CHRONICLE REQUIREMENT TYPES
// =========================================================
//
// Canonical requirement vocabulary.
//
// Future systems should use these requirement types
// rather than inventing independent gate logic.
//
// =========================================================


const CHRONICLE_REQUIREMENT_TYPES = {

  ACTIVITY_COMPLETED:
    "activity_completed",

  ACTIVITY_COUNT:
    "activity_count",

  ENCOUNTER_COMPLETED:
    "encounter_completed",

  ENCOUNTER_VICTORIES:
    "encounter_victories",

  ENEMY_DEFEATS:
    "enemy_defeats",

  CHARACTER_BATTLES:
    "character_battles",

  PLAYER_EXP:
    "player_exp",

  PLAYER_RYO:
    "player_ryo"

};



// =========================================================
// BRICK 174 — ACTIVITY COMPLETION QUERY
// =========================================================
//
// Determines whether an Activity has ever been
// successfully completed.
//
// =========================================================


function hasCompletedActivity(
  activityId
) {


  if (
    !activityId
  ) {


    return false;


  }


  return getActivityHistory()
    .some(
      entry =>
        entry &&
        entry.activity ===
          activityId &&
        entry.success ===
          true
    );


}



// =========================================================
// BRICK 175 — ACTIVITY SUCCESS COUNT
// =========================================================


function getActivitySuccessCount(
  activityId
) {


  if (
    !activityId
  ) {


    return 0;


  }


  return getActivityHistory()
    .filter(
      entry =>
        entry &&
        entry.activity ===
          activityId &&
        entry.success ===
          true
    )
    .length;


}



// =========================================================
// BRICK 176 — CHARACTER BATTLE COUNT
// =========================================================


function getCharacterBattleCount(
  characterId
) {


  if (
    !characterId
  ) {


    return 0;


  }


  return getCharacterBattleHistory(
    characterId
  ).length;


}



// =========================================================
// BRICK 177 — SINGLE REQUIREMENT EVALUATOR
// =========================================================
//
// Converts one requirement definition into a
// reusable Chronicle gate result.
//
// =========================================================


function evaluateChronicleRequirement(
  requirement
) {


  if (
    !requirement ||
    !requirement.type
  ) {


    return {

      valid:
        false,

      met:
        false,

      reason:
        "Invalid Chronicle requirement."

    };


  }


  const target =
    Math.max(
      0,
      Number(
        requirement.amount
      ) || 0
    );


  let current =
    0;


  let met =
    false;


  switch (
    requirement.type
  ) {


    case CHRONICLE_REQUIREMENT_TYPES.ACTIVITY_COMPLETED:


      current =
        hasCompletedActivity(
          requirement.id
        )
          ? 1
          : 0;


      met =
        current >= 1;


      break;



    case CHRONICLE_REQUIREMENT_TYPES.ACTIVITY_COUNT:


      current =
        getActivitySuccessCount(
          requirement.id
        );


      met =
        current >=
          Math.max(
            1,
            target
          );


      break;



    case CHRONICLE_REQUIREMENT_TYPES.ENCOUNTER_COMPLETED:


      current =
        hasCompletedEncounter(
          requirement.id
        )
          ? 1
          : 0;


      met =
        current >= 1;


      break;



    case CHRONICLE_REQUIREMENT_TYPES.ENCOUNTER_VICTORIES:


      current =
        getEncounterVictoryCount(
          requirement.id
        );


      met =
        current >=
          Math.max(
            1,
            target
          );


      break;



    case CHRONICLE_REQUIREMENT_TYPES.ENEMY_DEFEATS:


      current =
        getEnemyDefeatCount(
          requirement.id
        );


      met =
        current >=
          Math.max(
            1,
            target
          );


      break;



    case CHRONICLE_REQUIREMENT_TYPES.CHARACTER_BATTLES:


      current =
        getCharacterBattleCount(
          requirement.id
        );


      met =
        current >=
          Math.max(
            1,
            target
          );


      break;



    case CHRONICLE_REQUIREMENT_TYPES.PLAYER_EXP:


      current =
        Number(
          playerData &&
          playerData.exp
        ) || 0;


      met =
        current >=
          target;


      break;



    case CHRONICLE_REQUIREMENT_TYPES.PLAYER_RYO:


      current =
        Number(
          playerData &&
          playerData.ryo
        ) || 0;


      met =
        current >=
          target;


      break;



    default:


      return {

        valid:
          false,

        met:
          false,

        type:
          requirement.type,

        reason:
          "Unknown Chronicle requirement type."

      };


  }


  return {

    valid:
      true,

    met:
      met,

    type:
      requirement.type,

    id:
      requirement.id ||
      null,

    current:
      current,

    required:
      (
        requirement.type ===
          CHRONICLE_REQUIREMENT_TYPES.ACTIVITY_COMPLETED ||
        requirement.type ===
          CHRONICLE_REQUIREMENT_TYPES.ENCOUNTER_COMPLETED
      )
        ? 1
        : target

  };


}



// =========================================================
// BRICK 178 — REQUIREMENT SET EVALUATOR
// =========================================================
//
// Evaluates multiple requirements.
//
// Default behaviour:
// ALL requirements must be met.
//
// =========================================================


function evaluateChronicleRequirements(
  requirements
) {


  if (
    !Array.isArray(
      requirements
    )
  ) {


    return {

      valid:
        false,

      met:
        false,

      results:
        []

    };


  }


  if (
    requirements.length ===
      0
  ) {


    return {

      valid:
        true,

      met:
        true,

      results:
        []

    };


  }


  const results =
    requirements.map(
      requirement =>
        evaluateChronicleRequirement(
          requirement
        )
    );


  const valid =
    results.every(
      result =>
        result.valid ===
          true
    );


  const met =
    valid &&
    results.every(
      result =>
        result.met ===
          true
    );


  return {

    valid:
      valid,

    met:
      met,

    results:
      results

  };


}



// =========================================================
// BRICK 179 — CHRONICLE UNLOCK CHECK
// =========================================================
//
// Gameplay-facing gate.
//
// Example:
//
// isChronicleUnlocked([
//   {
//     type: "enemy_defeats",
//     id: "scout",
//     amount: 5
//   }
// ])
//
// =========================================================


function isChronicleUnlocked(
  requirements
) {


  const evaluation =
    evaluateChronicleRequirements(
      requirements
    );


  return (
    evaluation.valid ===
      true &&
    evaluation.met ===
      true
  );


}



// =========================================================
// BRICK 180 — UNMET REQUIREMENT QUERY
// =========================================================
//
// Gives future UI / Konoha screens the exact
// reasons something remains locked.
//
// =========================================================


function getUnmetChronicleRequirements(
  requirements
) {


  const evaluation =
    evaluateChronicleRequirements(
      requirements
    );


  if (
    !evaluation.valid
  ) {


    return evaluation.results;


  }


  return evaluation.results
    .filter(
      result =>
        result.met !==
          true
    );


}



// =========================================================
// BRICK 181 — REQUIREMENT PROGRESS SUMMARY
// =========================================================
//
// UI-safe summary.
//
// This eventually powers things such as:
//
// Scout Defeats: 1 / 5
// Mission Victories: 3 / 10
//
// =========================================================


function getChronicleRequirementProgress(
  requirement
) {


  const result =
    evaluateChronicleRequirement(
      requirement
    );


  if (
    !result.valid
  ) {


    return result;


  }


  return {

    type:
      result.type,

    id:
      result.id,

    current:
      result.current,

    required:
      result.required,

    remaining:
      Math.max(
        0,
        result.required -
          result.current
      ),

    met:
      result.met

  };


}



// =========================================================
// BRICK 182 — CHRONICLE REQUIREMENT HEALTH CHECK
// =========================================================
//
// Non-destructive validation.
//
// =========================================================


function validateChronicleRequirementSystem() {


  const knownActivity =
    evaluateChronicleRequirement({

      type:
        CHRONICLE_REQUIREMENT_TYPES.ACTIVITY_COMPLETED,

      id:
        "light_training"

    });


  const knownEncounter =
    evaluateChronicleRequirement({

      type:
        CHRONICLE_REQUIREMENT_TYPES.ENCOUNTER_COMPLETED,

      id:
        "scout_patrol"

    });


  const knownEnemy =
    evaluateChronicleRequirement({

      type:
        CHRONICLE_REQUIREMENT_TYPES.ENEMY_DEFEATS,

      id:
        "scout",

      amount:
        1

    });


  const checks = {


    requirementTypes:
      !!(
        CHRONICLE_REQUIREMENT_TYPES &&
        CHRONICLE_REQUIREMENT_TYPES.ENEMY_DEFEATS
      ),


    activityQuery:
      typeof hasCompletedActivity ===
        "function",


    activityCount:
      typeof getActivitySuccessCount ===
        "function",


    characterBattleCount:
      typeof getCharacterBattleCount ===
        "function",


    singleEvaluator:
      knownActivity.valid ===
        true,


    encounterEvaluator:
      knownEncounter.valid ===
        true,


    enemyEvaluator:
      knownEnemy.valid ===
        true,


    setEvaluator:
      evaluateChronicleRequirements(
        []
      ).met ===
        true,


    unlockBridge:
      typeof isChronicleUnlocked ===
        "function",


    unmetQuery:
      Array.isArray(
        getUnmetChronicleRequirements(
          []
        )
      ),


    progressQuery:
      typeof getChronicleRequirementProgress ===
        "function"


  };


  checks.healthy =
    Object.values(
      checks
    ).every(
      value =>
        value === true
    );


  console.log(
    "Chronicle Requirement health:",
    checks
  );


  return checks;


}

