// =========================================================
// BRICK 127 — CHRONICLE ACTIVITY ANALYTICS
// =========================================================
//
// Converts Activity History into Chronicle-ready statistics.
//
// Handles:
// - Activity counts
// - Character activity counts
// - Successful / failed activities
// - EXP earned
// - Ryō earned
// - Item rewards
// - Progression rewards
//
// =========================================================


function getActivityAnalytics() {


  const history =
    getActivityHistory();



  const analytics = {


    totalActivities:
      history.length,


    successfulActivities:
      0,


    failedActivities:
      0,


    totalExpEarned:
      0,


    totalRyoEarned:
      0,


    totalItemRewards:
      0,


    totalProgressionRewards:
      0,


    activityCounts:
      {},


    characterCounts:
      {},


    mostUsedActivity:
      null,


    mostActiveCharacter:
      null


  };



  history.forEach(
    entry => {


      if (
        entry.success
      ) {


        analytics.successfulActivities++;


      }
      else {


        analytics.failedActivities++;


      }



      if (
        entry.activity
      ) {


        analytics.activityCounts[
          entry.activity
        ] =
          (
            analytics.activityCounts[
              entry.activity
            ] ||
            0
          ) + 1;


      }



      if (
        entry.character
      ) {


        analytics.characterCounts[
          entry.character
        ] =
          (
            analytics.characterCounts[
              entry.character
            ] ||
            0
          ) + 1;


      }



      const rewards =
        entry.rewards;



      if (
        rewards &&
        typeof rewards ===
          "object"
      ) {


        analytics.totalExpEarned +=
          Number(
            rewards.exp
          ) || 0;



        analytics.totalRyoEarned +=
          Number(
            rewards.ryo
          ) || 0;



        if (
          Array.isArray(
            rewards.items
          )
        ) {


          rewards.items.forEach(
            item => {


              analytics.totalItemRewards +=
                Number(
                  item.amount
                ) || 1;


            }
          );


        }



        if (
          Array.isArray(
            rewards.progression
          )
        ) {


          analytics.totalProgressionRewards +=
            rewards.progression.length;


        }


      }


    }
  );



  Object.keys(
    analytics.activityCounts
  ).forEach(
    activity => {


      if (
        !analytics.mostUsedActivity ||
        analytics.activityCounts[
          activity
        ] >
        analytics.activityCounts[
          analytics.mostUsedActivity
        ]
      ) {


        analytics.mostUsedActivity =
          activity;


      }


    }
  );



  Object.keys(
    analytics.characterCounts
  ).forEach(
    character => {


      if (
        !analytics.mostActiveCharacter ||
        analytics.characterCounts[
          character
        ] >
        analytics.characterCounts[
          analytics.mostActiveCharacter
        ]
      ) {


        analytics.mostActiveCharacter =
          character;


      }


    }
  );



  console.log(
    "Chronicle activity analytics:",
    analytics
  );



  return analytics;


}


// =========================================================
// BRICK 134 — ACTIVITY PROGRESSION BRIDGE
// =========================================================
//
// Routes Activity Result progression
// into existing progression authorities.
//
// Supports:
// - Registered Activity progression
// - Data-driven progression source overrides
// - Activities with no discipline progression
// - Progression failure detection
//
// =========================================================


function processActivityProgression(
  result
) {


  if (
    !result ||
    !result.rewards
  ) {


    console.log(
      "Invalid Activity Result progression request."
    );


    return false;


  }



  const progression =
    result.rewards.progression;



  if (
    !Array.isArray(
      progression
    )
  ) {


    console.log(
      "Invalid Activity Result progression data."
    );


    return false;


  }



  if (
    progression.length ===
      0
  ) {


    console.log(
      "Activity completed with no discipline progression:",
      result.activity
    );


    return true;


  }



  let progressionSucceeded =
    true;



  progression.forEach(
    reward => {


      if (
        !reward ||
        reward.type !==
          "discipline"
      ) {


        return;


      }



      const progressionSource =
        reward.source ||
        result.activity;



      const applied =
        addDisciplineExp(
          result.character,
          reward.id,
          reward.amount,
          progressionSource
        );



      if (
        !applied
      ) {


        progressionSucceeded =
          false;


      }


    }
  );



  if (
    !progressionSucceeded
  ) {


    console.log(
      "Activity progression failed:",
      result.activity
    );


    return false;


  }



  console.log(
    "Activity progression processed:",
    progression
  );



  return true;


}


// =========================================================
// TASK 6.7 — ACTIVITY VALIDATION LAYER
// =========================================================
//
// Validates activity requests before execution.
//
// Handles:
// - Activity existence
// - Character availability
// - Future requirement checks
//
// =========================================================



// =========================================================
// VALIDATE ACTIVITY REQUEST
// =========================================================

function validateActivityRequest(
  activityId,
  characterId
) {


  if (
    !activityId
  ) {


    console.log(
      "Activity validation failed: Missing activity ID."
    );


    return false;


  }



  const activity =
    getActivityData(
      activityId
    );



  if (
    !activity
  ) {


    console.log(
      "Activity validation failed: Unknown activity",
      activityId
    );


    return false;


  }



  if (
    characterId
  ) {


    const character =
      getPlayerCharacter(
        characterId
      );



    if (
      !character
    ) {


      console.log(
        "Activity validation failed: Character not found",
        characterId
      );


      return false;


    }


  }



  console.log(
    "Activity validation passed:",
    activityId
  );



  return true;


}


// =========================================================
// TASK 6.9 — ACTIVITY REQUIREMENT FRAMEWORK
// =========================================================
//
// Adds requirement checks before activity execution.
//
// Handles:
// - Rank requirements
// - Difficulty requirements
// - Future progression gates
//
// =========================================================



// =========================================================
// GET ACTIVITY REQUIREMENTS
// =========================================================

function getActivityRequirements(
  activityId
) {


  const activity =
    getActivityData(
      activityId
    );


  if (
    !activity
  ) {


    return null;


  }



  return (
    activity.requirements
    ||
    {}
  );


}



// =========================================================
// CHECK ACTIVITY REQUIREMENTS
// =========================================================

function checkActivityRequirements(
  activityId
) {


  const requirements =
    getActivityRequirements(
      activityId
    );



  if (
    !requirements
  ) {


    return false;


  }



  console.log(
    "Activity requirements checked:",
    requirements
  );



  return true;


}

// =========================================================
// TASK 6.10 — ACTIVITY REQUIREMENT EXECUTION GATE
// =========================================================
//
// Connects requirement checks into activity execution.
//
// Flow:
//
// Activity Request
//       ↓
// Validation
//       ↓
// Requirements
//       ↓
// Execution
//
// =========================================================



// =========================================================
// VALIDATE ACTIVITY REQUIREMENTS
// =========================================================

function validateActivityRequirements(
  activityId
) {


  const requirements =
    checkActivityRequirements(
      activityId
    );



  if (
    !requirements
  ) {


    console.log(
      "Activity requirement validation failed:",
      activityId
    );


    return false;


  }



  console.log(
    "Activity requirement validation passed:",
    activityId
  );



  return true;


}


// =========================================================
// BRICK 95 — LOCATION ACTIVITY CONNECTION
// =========================================================
//
// Connects World Engine locations
// to Activity Engine definitions.
//
// Handles:
// - Location activity mappings
// - Action routing
// - Activity launch requests
//
// =========================================================


const LOCATION_ACTIVITY_CONNECTIONS = {


  training_grounds: {


    practical:
      "practical"


  },


  konoha: {


    missions:
      "mission",

    exams:
      "exam",

    practical:
      "practical"


  },


  rogue_hideout: {


    battle:
      "battle"


  }


};





// =========================================
// LOCATION ACTIVITY LOOKUP
// =========================================

function getLocationActivity(
  locationId,
  action
) {


  if (
    !LOCATION_ACTIVITY_CONNECTIONS[locationId]
  ) {


    return null;


  }



  return (

    LOCATION_ACTIVITY_CONNECTIONS[locationId][action]

    ||

    null

  );


}



// =========================================================
// BRICK 123 — LOCATION ACTIVITY REQUEST
// =========================================================
//
// Launches mapped location activities
// through the Activity Engine.
//
// Preserves:
// - Location identity
// - Activity identity
// - Character identity
//
// =========================================================


function launchLocationAction(
  locationId,
  action,
  characterId
) {


  const activity =
    getLocationActivity(
      locationId,
      action
    );



  if (
    !activity
  ) {


    console.log(
      "No activity connected:",
      locationId,
      action
    );


    return false;


  }



  return startRegisteredActivity(
    activity,
    characterId
  );


}




// =========================================================
// BRICK 96 — CONTENT REGISTRY FOUNDATION
// =========================================================
//
// Core Chronicle Engine Content Layer
//
// Handles:
// - Registered content types
// - Content lookup
// - Shared content access
//
// =========================================================


const CONTENT_REGISTRY = {


  locations:
    LOCATION_DATABASE,


  activities:
    ACTIVITY_DATABASE,


  characters:
    {},


  enemies:
    {},


  missions:
    {},


  equipment:
    {}


};





function getContentRegistry(
  type
) {


  return (
    CONTENT_REGISTRY[type]
    ||
    null
  );


}

// =========================================
// CONTENT REGISTRATION
// =========================================


function registerLocation(
  location
) {


  if (
    !location ||
    !location.id
  ) {


    return false;


  }



  LOCATION_DATABASE[
    location.id
  ] = location;



  return true;


}
// =========================================
// ACTIVITY EXISTENCE VALIDATION
// =========================================


function validateActivity(
  activityId
) {


  const activity =
    getActivityData(
      activityId
    );



  if (!activity) {


    return false;


  }



  return true;


}

// =========================================================
// BRICK 122 — LOCATION ACTIVITY VALIDATION
// =========================================================
//
// Validates location actions against
// their mapped Activity Engine identity.
//
// Location Action
// ↓
// Activity Mapping
// ↓
// Activity Validation
//
// =========================================================


function validateLocationActivity(
  locationId,
  action
) {


  const location =
    getLocationData(
      locationId
    );



  if (
    !location
  ) {


    return false;


  }



  if (
    !Array.isArray(
      location.actions
    ) ||
    !location.actions.includes(
      action
    )
  ) {


    return false;


  }



  const activityId =
    getLocationActivity(
      locationId,
      action
    );



  if (
    !activityId
  ) {


    return false;


  }



  return validateActivity(
    activityId
  );


}

