function showKonohaExamUIScreen(
  characterId = null
) {


  const opened =
    openKonohaActivityUIScreen(
      "exams",
      characterId
    );


  if (
    !opened ||
    opened.success !==
      true
  ) {


    return opened;


  }


  const rendered =
    renderKonohaExamVisualScreen();


  return {


    success:
      rendered === true,


    serviceId:
      "exams",


    characterId:
      getKonohaActivityUISessionState()
        .characterId,


    rendered:
      rendered === true


  };


}

// =========================================================
// BRICK 322 — PRACTICAL INTERACTION + ATTEMPT STATE
// =========================================================
//
// Single Practical runtime UI authority.
//
// Owns:
// - selected Practical discipline
// - requested batch size
// - most recent genuine training batch
// - batch result metadata
// - temporary result visibility
//
// DOES NOT own:
// - Discipline EXP calculation
// - Discipline level-ups
// - stat growth
// - PL calculation
// - persistence
// - training resolution
//
// Existing progression authorities retain those
// responsibilities.
//
// =========================================================


const KONOHA_PRACTICAL_UI_STATE = {

  disciplineId:
    "tai",

  batchSize:
    1,

  lastBatch:
    [],

  lastBatchMeta:
    null,

  resultVisible:
    false

};


// =========================================================
// PRACTICAL STATE ACCESS
// =========================================================


function getKonohaPracticalAttemptState() {


  return KONOHA_PRACTICAL_UI_STATE;

}


// =========================================================
// PRACTICAL SELECTED DISCIPLINE ACCESS
// =========================================================


function getKonohaPracticalSelectedDisciplineId() {


  const validDisciplines = [
    "tai",
    "buki",
    "stamina"
  ];


  if (
    !validDisciplines.includes(
      KONOHA_PRACTICAL_UI_STATE
        .disciplineId
    )
  ) {


    KONOHA_PRACTICAL_UI_STATE
      .disciplineId =
        "tai";

  }


  return KONOHA_PRACTICAL_UI_STATE
    .disciplineId;

}


// =========================================================
// PRACTICAL BATCH SIZE ACCESS
// =========================================================


function getKonohaPracticalBatchSize() {


  const requested =
    Number(
      KONOHA_PRACTICAL_UI_STATE
        .batchSize
    );


  return [
    1,
    5,
    10
  ].includes(
    requested
  )

    ? requested

    : 1;

}


// =========================================================
// PRACTICAL RESULT PRESENTATION RESET
// =========================================================


function clearKonohaPracticalResultPresentation(
  rerender = true
) {


  KONOHA_PRACTICAL_UI_STATE
    .resultVisible =
      false;


  KONOHA_PRACTICAL_UI_STATE
    .lastBatch =
      [];


  KONOHA_PRACTICAL_UI_STATE
    .lastBatchMeta =
      null;


  if (
    rerender === true &&
    typeof renderKonohaPracticalVisualScreen ===
      "function"
  ) {


    renderKonohaPracticalVisualScreen();

  }


  return true;

}



// =========================================================
// BRICK 324 — PRACTICAL INTERACTION STATE LIFECYCLE
// =========================================================
//
// Owns Practical UI interaction changes:
//
// - discipline selection
// - batch selection
// - character selection
// - stale result cleanup
//
// Training execution remains owned by BRICK 323.
// Progression remains owned by the existing Training Engine.
//
// =========================================================


// =========================================================
// PRACTICAL DISCIPLINE SELECTION
// =========================================================


function selectKonohaPracticalDiscipline(
  disciplineId
) {


  const validDisciplines = [
    "tai",
    "buki",
    "stamina"
  ];


  if (
    !validDisciplines.includes(
      disciplineId
    )
  ) {


    console.log(
      "Invalid Practical discipline:",
      disciplineId
    );


    return false;

  }


  /*
     A result belongs to the discipline that produced it.

     Changing discipline therefore immediately retires any
     previous Practical result before the new discipline is
     rendered.
  */

  clearKonohaPracticalResultPresentation(
    false
  );


  KONOHA_PRACTICAL_UI_STATE
    .disciplineId =
      disciplineId;


  renderKonohaPracticalVisualScreen();


  console.log(
    "PRACTICAL DISCIPLINE SELECTED:",
    disciplineId
  );


  return true;

}


// =========================================================
// PRACTICAL BATCH SELECTION
// =========================================================


function setKonohaPracticalBatchSize(
  batchSize
) {


  const requested =
    Number(
      batchSize
    );


  const normalized =
    [
      1,
      5,
      10
    ].includes(
      requested
    )

      ? requested

      : 1;


  /*
     Batch selection changes the next requested action.

     Any previous result is retired so old feedback cannot
     be mistaken for the newly selected batch.
  */

  clearKonohaPracticalResultPresentation(
    false
  );


  KONOHA_PRACTICAL_UI_STATE
    .batchSize =
      normalized;


  renderKonohaPracticalVisualScreen();


  console.log(
    "PRACTICAL BATCH SIZE SELECTED:",
    normalized
  );


  return true;

}


// =========================================================
// PRACTICAL CHARACTER SELECTION
// =========================================================


function changeKonohaPracticalCharacter(
  direction
) {


  /*
     A result belongs to the shinobi that produced it.

     Kill the old result before changing character.
  */

  clearKonohaPracticalResultPresentation(
    false
  );


  const character =
    cycleKonohaSelectedCharacter(
      direction
    );


  if (!character) {


    return false;

  }


  renderKonohaPracticalVisualScreen();


  console.log(
    "PRACTICAL SHINOBI SELECTED:",
    character.id
  );


  return true;

}


// =========================================================
// BRICK 325 — PRACTICAL EXECUTION + RESULT AUTHORITY
// =========================================================
//
// Connects Practical to the existing unified Training Engine.
//
// Owns:
// - genuine ×1 / ×5 / ×10 execution
// - before / after PL snapshots
// - batch result storage
// - significant Practical notifications
//
// DOES NOT own:
// - EXP calculation
// - Discipline level-ups
// - stat growth
// - PL calculation
// - persistence
//
// performDisciplineTraining() remains gameplay authority.
//
// =========================================================


function buildKonohaPracticalSpecialNotifications(
  characterId
) {


  const meta =
    KONOHA_PRACTICAL_UI_STATE
      .lastBatchMeta;


  const results =
    Array.isArray(
      KONOHA_PRACTICAL_UI_STATE
        .lastBatch
    )

      ? KONOHA_PRACTICAL_UI_STATE
          .lastBatch

      : [];


  const notifications =
    [];


  if (
    !meta ||
    meta.characterId !==
      characterId
  ) {


    return notifications;

  }


  const successfulResults =
    results.filter(
      result =>
        result &&
        result.success ===
          true
    );


  if (
    successfulResults.length ===
      0
  ) {


    return notifications;

  }


  const firstResult =
    successfulResults[0];


  const finalResult =
    successfulResults[
      successfulResults.length - 1
    ];


  const previousLevel =
    Number(
      firstResult.previousLevel
    ) || 0;


  const newLevel =
    Number(
      finalResult.newLevel
    ) || previousLevel;


  if (
    newLevel >
      previousLevel
  ) {


    notifications.push({

      id:
        `practical-mastery-${characterId}-${meta.disciplineId}-${newLevel}-${Date.now()}`,

      characterId:
        characterId,

      type:
        "mastery",

      title:
        "MASTERY INCREASED",

      detail:
        `${String(
          finalResult.disciplineName ||
          meta.disciplineId
        ).toUpperCase()} ${previousLevel} → ${newLevel}`,

      timestamp:
        Date.now()

    });

  }


  if (
    meta.beforePL &&
    meta.afterPL
  ) {


    const plBefore =
      Number(
        meta.beforePL.displayedPL
      ) || 0;


    const plAfter =
      Number(
        meta.afterPL.displayedPL
      ) || plBefore;


    if (
      plAfter >
        plBefore
    ) {


      notifications.push({

        id:
          `practical-power-${characterId}-${plAfter}-${Date.now()}`,

        characterId:
          characterId,

        type:
          "power",

        title:
          "POWER LEVEL INCREASED",

        detail:
          `POWER LEVEL ${plBefore} → ${plAfter}`,

        timestamp:
          Date.now()

      });

    }

  }


  return notifications;

}


// =========================================================
// RECORD PRACTICAL SPECIAL NOTIFICATIONS
// =========================================================


function recordKonohaPracticalSpecialNotifications(
  characterId
) {


  const notifications =
    buildKonohaPracticalSpecialNotifications(
      characterId
    );


  if (
    notifications.length ===
      0
  ) {


    return [];

  }


  const existingHistory =
    Array.isArray(
      KONOHA_PRACTICAL_UI_STATE
        .specialNotificationHistory
    )

      ? KONOHA_PRACTICAL_UI_STATE
          .specialNotificationHistory

      : [];


  KONOHA_PRACTICAL_UI_STATE
    .specialNotificationHistory = [

      ...notifications,
      ...existingHistory

    ];


  const characterHistory =
    KONOHA_PRACTICAL_UI_STATE
      .specialNotificationHistory
      .filter(
        notification =>
          notification &&
          notification.characterId ===
            characterId
      )
      .slice(
        0,
        10
      );


  const otherCharacterHistory =
    KONOHA_PRACTICAL_UI_STATE
      .specialNotificationHistory
      .filter(
        notification =>
          notification &&
          notification.characterId !==
            characterId
      );


  KONOHA_PRACTICAL_UI_STATE
    .specialNotificationHistory = [

      ...characterHistory,
      ...otherCharacterHistory

    ];


  return notifications;

}


// =========================================================
// PRACTICAL SPECIAL NOTIFICATION RENDERER
// =========================================================


function renderKonohaPracticalSpecialNotifications(
  characterId
) {


  const history =
    (
      Array.isArray(
        KONOHA_PRACTICAL_UI_STATE
          .specialNotificationHistory
      )

        ? KONOHA_PRACTICAL_UI_STATE
            .specialNotificationHistory

        : []
    )
      .filter(
        notification =>
          notification &&
          notification.characterId ===
            characterId
      )
      .slice(
        0,
        10
      );


  if (
    history.length ===
      0
  ) {


    return "";

  }


  return history
    .map(
      notification => `

        <div
          class="
            practical-special-notification
            practical-special-notification-${notification.type}
          "
        >

          <div
            class="
              practical-special-notification-title
            "
          >
            ${notification.title}
          </div>

          <div
            class="
              practical-special-notification-detail
            "
          >
            ${notification.detail}
          </div>

        </div>

      `
    )
    .join("");

}


// =========================================================
// PRACTICAL ORDINARY RESULT SUMMARY
// =========================================================


function renderKonohaPracticalResultSummary() {


  if (
    KONOHA_PRACTICAL_UI_STATE
      .resultVisible !==
        true
  ) {


    return "";

  }


  const results =
    Array.isArray(
      KONOHA_PRACTICAL_UI_STATE
        .lastBatch
    )

      ? KONOHA_PRACTICAL_UI_STATE
          .lastBatch

      : [];


  const successfulResults =
    results.filter(
      result =>
        result &&
        result.success ===
          true
    );


  if (
    successfulResults.length ===
      0
  ) {


    const failedResult =
      results.find(
        result =>
          result &&
          result.success !==
            true
      );


    return failedResult &&
      failedResult.reason

      ? `TRAINING UNAVAILABLE — ${failedResult.reason}`

      : "TRAINING UNAVAILABLE";

  }


  const totalExp =
    successfulResults.reduce(
      (
        total,
        result
      ) =>
        total +
        (
          Number(
            result.expGained
          ) || 0
        ),
      0
    );


  const disciplineName =
    String(
      successfulResults[
        successfulResults.length - 1
      ].disciplineName ||
      getKonohaPracticalSelectedDisciplineId()
    ).toUpperCase();


  return `+${totalExp} ${disciplineName} EXP`;

}


// =========================================================
// PRACTICAL TRAINING EXECUTION
// =========================================================


function executeKonohaPracticalTraining() {


  const session =
    getKonohaActivityUISessionState();


  if (
    !session ||
    !session.characterId
  ) {


    console.log(
      "Practical training failed: no selected character."
    );


    return {
      success:
        false,

      reason:
        "No selected character."
    };

  }


  const characterId =
    session.characterId;


  const disciplineId =
    getKonohaPracticalSelectedDisciplineId();


  const batchSize =
    getKonohaPracticalBatchSize();


  const character =
    getPlayerCharacter(
      characterId
    );


  if (!character) {


    return {
      success:
        false,

      reason:
        "Selected character could not be loaded."
    };

  }


  clearKonohaPracticalResultPresentation(
    false
  );


  const beforePL =
    getCharacterPLProgress(
      character
    );


  const results =
    [];


  let successfulAttempts =
    0;


  let failedAttempts =
    0;


  for (
    let attemptIndex = 0;
    attemptIndex < batchSize;
    attemptIndex += 1
  ) {


    const result =
      performDisciplineTraining(
        characterId,
        disciplineId,
        "practical"
      );


    results.push(
      result
    );


    if (
      result &&
      result.success ===
        true
    ) {


      successfulAttempts +=
        1;

    } else {


      failedAttempts +=
        1;


      break;

    }

  }


  const afterPL =
    getCharacterPLProgress(
      character
    );


  KONOHA_PRACTICAL_UI_STATE
    .lastBatch =
      results;


  KONOHA_PRACTICAL_UI_STATE
    .lastBatchMeta = {

      characterId:
        characterId,

      disciplineId:
        disciplineId,

      requestedBatchSize:
        batchSize,

      completedAttempts:
        results.length,

      successfulAttempts:
        successfulAttempts,

      failedAttempts:
        failedAttempts,

      beforePL: {

        rawPL:
          beforePL.rawPL,

        displayedPL:
          beforePL.displayedPL,

        nextPL:
          beforePL.nextPL,

        progressPercent:
          beforePL.progressPercent

      },

      afterPL: {

        rawPL:
          afterPL.rawPL,

        displayedPL:
          afterPL.displayedPL,

        nextPL:
          afterPL.nextPL,

        progressPercent:
          afterPL.progressPercent

      }

    };


  KONOHA_PRACTICAL_UI_STATE
    .resultVisible =
      results.length >
        0;


  recordKonohaPracticalSpecialNotifications(
    characterId
  );


  renderKonohaPracticalVisualScreen();


  console.log(
    "PRACTICAL TRAINING BATCH COMPLETE:",
    KONOHA_PRACTICAL_UI_STATE
      .lastBatchMeta
  );


  return {

    success:
      successfulAttempts >
        0,

    characterId:
      characterId,

    disciplineId:
      disciplineId,

    requestedAttempts:
      batchSize,

    completedAttempts:
      results.length,

    successfulAttempts:
      successfulAttempts,

    failedAttempts:
      failedAttempts,

    results:
      results

  };

}


// =========================================================
// BRICK 326 — PRACTICAL LIVE TRAINING VISUAL SCREEN
// =========================================================
//
// Final live Practical renderer.
//
// Owns:
// - live character presentation
// - live PL presentation
// - live Discipline presentation
// - batch controls
// - ordinary training result
// - Special Notifications
// - BEGIN TRAINING interaction
//
// Gameplay progression remains external.
//
// =========================================================


function renderKonohaPracticalVisualScreen() {


  ensureKonohaPracticalUIStyles();


  const root =
    ensureKonohaActivityUIRoot();


  const session =
    getKonohaActivityUISessionState();


  const data =
    getKonohaPracticalUIScreenData(
      session.characterId
    );


  if (!data) {


    console.log(
      "Practical visual render failed."
    );


    return false;

  }


  const selectedDisciplineId =
    getKonohaPracticalSelectedDisciplineId();


  const batchSize =
    getKonohaPracticalBatchSize();


  const character =
    data.character;


  const plProgress =
    character &&
    character.plProgress &&
    typeof character.plProgress ===
      "object"

      ? character.plProgress

      : {

          currentPL:
            Number(
              character &&
              character.currentPL
            ) || 0,

          progressPercent:
            0

        };


  const plProgressPercent =
    Math.max(
      0,
      Math.min(
        100,
        Number(
          plProgress.progressPercent
        ) || 0
      )
    );


  const resultSummary =
    renderKonohaPracticalResultSummary();


  const specialNotifications =
    renderKonohaPracticalSpecialNotifications(
      data.selectedCharacterId
    );


  root.dataset.serviceId =
    "practical";


  root.style.display =
    "block";


  root.innerHTML = `

    <div
      class="
        konoha-practical-screen
      "
    >


      <img
        src="${
          getUIAssetPath(
            "practical"
          )
        }"
        alt="
          Practical Training
        "
        class="
          practical-background
        "
      >


      <!-- =====================================
           BACK TO KONOHA
           ===================================== -->

      <button
        type="
          button
        "
        class="
          practical-konoha-return
        "
        onclick="
          returnToKonohaFromActivityUI()
        "
        aria-label="
          Back to Konoha
        "
        title="
          Back to Konoha
        "
      >
        ← BACK TO KONOHA
      </button>


      <!-- =====================================
           CHARACTER
           ===================================== -->

      <section
        class="
          practical-character-panel
        "
      >


        <div
          class="
            practical-character-image-wrap
          "
        >


          ${
            character &&
            character.image

              ? `
                  <img
                    class="
                      practical-character-image
                    "
                    src="
                      ${character.image}
                    "
                    alt="
                      ${character.name}
                    "
                  >
                `

              : ""
          }


          <div
            class="
              practical-character-selector
            "
          >


            <button
              type="
                button
              "
              class="
                practical-character-arrow
              "
              onclick="
                changeKonohaPracticalCharacter(-1)
              "
              aria-label="
                Previous shinobi
              "
            >
              ‹
            </button>


            <button
              type="
                button
              "
              class="
                practical-character-arrow
              "
              onclick="
                changeKonohaPracticalCharacter(1)
              "
              aria-label="
                Next shinobi
              "
            >
              ›
            </button>


          </div>

        </div>


        <div
          class="
            practical-character-pl
          "
        >
          ${plProgress.currentPL}
        </div>


        <div
          class="
            practical-character-pl-progress
          "
        >

          <div
            class="
              practical-character-pl-progress-fill
            "
            style="
              width:
                ${plProgressPercent}%;
            "
          >
          </div>

        </div>


        <div
          class="
            practical-special-feed
          "
          aria-live="
            polite
          "
        >

          ${specialNotifications}

        </div>


      </section>


      <!-- =====================================
           DISCIPLINES
           ===================================== -->

      <section
        class="
          practical-discipline-stack
        "
      >


        ${data.disciplines
          .map(
            discipline => `

              <button
                type="
                  button
                "
                class="
                  practical-discipline-select
                  ${
                    discipline.id ===
                      selectedDisciplineId

                      ? "selected"

                      : ""
                  }
                "
                data-discipline-id="
                  ${discipline.id}
                "
                onclick="
                  selectKonohaPracticalDiscipline(
                    '${discipline.id}'
                  )
                "
                aria-pressed="
                  ${
                    discipline.id ===
                      selectedDisciplineId
                  }
                "
              >


                <div
                  class="
                    practical-mastery
                  "
                >
                  ${discipline.level}
                </div>


                <div
                  class="
                    practical-discipline-exp
                  "
                >
                  ${discipline.exp}
                  /
                  ${discipline.expRequired}
                  EXP
                </div>


                <div
                  class="
                    practical-progress-track
                  "
                >

                  <div
                    class="
                      practical-progress-fill
                    "
                    style="
                      width:
                        ${discipline.progressPercent}%;
                    "
                  >
                  </div>

                </div>


              </button>

            `
          )
          .join("")}


      </section>


      <!-- =====================================
           ORDINARY TRAINING RESULT
           ===================================== -->

      <div
        class="
          practical-result-stage
          ${
            resultSummary
              ? "visible"
              : "empty"
          }
        "
        aria-live="
          polite
        "
      >

        ${resultSummary}

      </div>


      <!-- =====================================
           BATCH CONTROLS
           ===================================== -->

      <div
        class="
          practical-batch-controls
        "
      >


        ${[
          1,
          5,
          10
        ]
          .map(
            amount => `

              <button
                type="
                  button
                "
                class="
                  practical-batch-button
                  ${
                    batchSize ===
                      amount

                      ? "selected"

                      : ""
                  }
                "
                onclick="
                  setKonohaPracticalBatchSize(
                    ${amount}
                  )
                "
                aria-pressed="
                  ${
                    batchSize ===
                      amount
                  }
                "
              >
                ×${amount}
              </button>

            `
          )
          .join("")}


      </div>


      <!-- =====================================
           BEGIN TRAINING
           ===================================== -->

      <button
        type="
          button
        "
        class="
          practical-begin-button
        "
        onclick="
          executeKonohaPracticalTraining()
        "
        title="
          Begin Practical Training
        "
      >
        BEGIN TRAINING
      </button>


    </div>

  `;


  console.log(
    "PRACTICAL TRAINING UI RENDERED:",
    {

      character:
        data.selectedCharacterId,

      discipline:
        selectedDisciplineId,

      batchSize:
        batchSize,

      canExecute:
        data.canExecute

    }
  );


  return true;

}



// =========================================================
// BRICK 327 — PRACTICAL SCREEN ENTRY LIFECYCLE
// =========================================================
//
// Opening Practical starts a fresh presentation session.
//
// Persistent character progression remains untouched.
//
// Cleared on entry:
// - old ordinary result
// - old batch result metadata
//
// Preserved:
// - selected discipline
// - selected batch size
// - persistent Special Notification history
//
// =========================================================


function showKonohaPracticalUIScreen(
  characterId = null
) {


  const opened =
    openKonohaActivityUIScreen(
      "practical",
      characterId
    );


  if (
    !opened ||
    opened.success !==
      true
  ) {


    return opened;

  }


  clearKonohaPracticalResultPresentation(
    false
  );


  const rendered =
    renderKonohaPracticalVisualScreen();


  return {

    success:
      rendered === true,

    serviceId:
      "practical",

    characterId:
      getKonohaActivityUISessionState()
        .characterId,

    rendered:
      rendered === true

  };

}


// =========================================================
// BRICK 329 — PRACTICAL UI MODULE HEALTH CONTRACT
// =========================================================
//
// Validates the permanent Practical UI authorities.
//
// Does NOT execute training.
// Does NOT alter progression.
// Does NOT alter saved player data.
//
// =========================================================


function validateKonohaPracticalUISystem() {


  const data =
    getKonohaPracticalUIScreenData(
      "naruto"
    );


  const style =
    ensureKonohaPracticalUIStyles();


  const checks = {


    styleAuthority:
      !!(
        style &&
        style.id ===
          "konoha-practical-ui-styles"
      ),


    practicalData:
      !!(
        data &&
        data.screen ===
          "practical"
      ),


    attemptState:
      !!(
        KONOHA_PRACTICAL_UI_STATE &&
        typeof KONOHA_PRACTICAL_UI_STATE ===
          "object"
      ),


    disciplineSelection:
      typeof selectKonohaPracticalDiscipline ===
        "function",


    batchSelection:
      typeof setKonohaPracticalBatchSize ===
        "function",


    batchAccess:
      typeof getKonohaPracticalBatchSize ===
        "function",


    characterSelection:
      typeof changeKonohaPracticalCharacter ===
        "function",


    resultReset:
      typeof clearKonohaPracticalResultPresentation ===
        "function",


    executionAuthority:
      typeof executeKonohaPracticalTraining ===
        "function",


    screenComposer:
      typeof renderKonohaPracticalVisualScreen ===
        "function",


    screenLauncher:
      typeof showKonohaPracticalUIScreen ===
        "function",


    returnBridge:
      typeof returnToKonohaFromActivityUI ===
        "function"


  };


  checks.healthy =
    Object.values(
      checks
    ).every(
      value =>
        value === true
    );


  console.log(
    "KONOHA PRACTICAL UI MODULE HEALTH:",
    checks
  );


  return checks;

}


