// =========================================================
// BRICK 303 — EXAM RENDERED VISUAL HEALTH CONTRACT
// =========================================================
//
// Validates the Exam screen AFTER it has been rendered.
//
// Owns checks for:
// - required live DOM
// - discipline presentation count
// - live progression presentation
// - progress-track containment
// - batch controls
// - BEGIN EXAM
// - Konoha return
//
// Does NOT validate:
// - gameplay resolution
// - progression mathematics
// - Chronicle history
// - access architecture
//
// Those remain owned by their dedicated systems.
//
// =========================================================

function validateKonohaExamVisualSystem() {


  const root =
    getKonohaActivityUIRoot();


  const examScreen =
    root &&
    root.querySelector(
      ".konoha-exam-screen"
    );


  const characterPanel =
    root &&
    root.querySelector(
      ".exam-character-panel"
    );


  const characterImage =
    root &&
    root.querySelector(
      ".exam-character-image"
    );


  const disciplineCards =
    root
      ? Array.from(
          root.querySelectorAll(
            ".exam-discipline-card"
          )
        )
      : [];


  const progressTracks =
    root
      ? Array.from(
          root.querySelectorAll(
            ".exam-progress-track"
          )
        )
      : [];


  const masteryValues =
    root
      ? root.querySelectorAll(
          ".exam-mastery-value"
        ).length
      : 0;


  const expLabels =
    root
      ? root.querySelectorAll(
          ".exam-discipline-exp-label"
        ).length
      : 0;


  const expValues =
    root
      ? root.querySelectorAll(
          ".exam-discipline-exp-value"
        ).length
      : 0;


  const tracksContained =
    progressTracks.every(
      (
        track,
        index
      ) => {


        const card =
          disciplineCards[
            index
          ];


        if (!card) {

          return false;

        }


        const trackRect =
          track.getBoundingClientRect();


        const cardRect =
          card.getBoundingClientRect();


        return (
          trackRect.left >=
            cardRect.left &&
          trackRect.right <=
            cardRect.right &&
          trackRect.top >=
            cardRect.top &&
          trackRect.bottom <=
            cardRect.bottom
        );


      }
    );


  const batchControls =
    !!(
      root &&
      root.querySelector(
        ".exam-batch-controls"
      )
    );


  const beginButton =
    !!(
      root &&
      root.querySelector(
        ".exam-begin-button"
      )
    );


  const konohaReturn =
    !!(
      root &&
      root.querySelector(
        ".exam-konoha-return"
      )
    );


  /*
     Retired Exam presentation is intentionally outside
     the active visual-health contract.
  */


  const health = {


    screenPresent:
      !!root,


    examScreen:
      !!examScreen,


    characterPanel:
      !!characterPanel,


    characterImage:
      !!characterImage,


    disciplineCards:
      disciplineCards.length ===
        3,


    masteryValues:
      masteryValues ===
        3,


    expLabels:
      expLabels ===
        3,


    expValues:
      expValues ===
        3,


    progressBars:
      progressTracks.length ===
        3,


    progressBarsContained:
      tracksContained,


    batchControls:
      batchControls,


    beginButton:
      beginButton,


        konohaReturn:
      konohaReturn,




    navigationFunctions:
      (
        typeof openKonohaExamFromVillage ===
          "function" &&
        typeof returnToKonohaFromActivityUI ===
          "function" &&
        typeof renderVillageOverlay ===
          "function"
      )


  };


  health.healthy =
    Object.values(
      health
    ).every(
      value =>
        value === true
    );


  console.log(
    "FINAL KONOHA EXAM VISUAL HEALTH:",
    health
  );


  return health;


}


