// #########################################################
// BRICK 141 — CANONICAL TRAINING ENGINE
// #########################################################
//
// Chronicle Engine Training Module
//
// Canonical authority for:
//
// TRAINING_DATABASE
// ↓
// getTrainingActivityData()
// ↓
// normalizeTrainingActivityDefinition()
// ↓
// getTrainingActivityReadiness()
// ↓
// startTraining()
// ↓
// executeActivityDefinition()
//
// Legacy helper bridges above this point may READ from
// this module but must not redefine its data authority.
//
// #########################################################

// =========================================================
// TRAINING ACTIVITY DATABASE
// =========================================================
//
// DATA-DRIVEN TRAINING DEFINITIONS
//
// The Chronicle Engine should not hard-code activities.
// Activities become database entries that define:
//
// - rewards
// - requirements
// - progression rules
// - future events
//
// The same architecture can later power:
// Missions
// Exams
// Dungeons
// Events
// Encounters
//
// =========================================================


const TRAINING_DATABASE = {


  light_training: {


    id:
      "light_training",


    name:
      "Light Training",


    description:
      "Low-risk training encounter for early progression.",


    reward: {


      exp:
        120


    },


    requirement: {


      minimumPL:
        400


    },


    progression: {


      discipline:
        "stamina",


      amount:
        10


    }


  },



  advanced_training: {


    id:
      "advanced_training",


    name:
      "Advanced Training",


    description:
      "Stronger opponents with increased progression rewards.",


    reward: {


      exp:
        320


    },


    requirement: {


      minimumPL:
        900


    },


    progression: {


      discipline:
        "tai",


      amount:
        25


    }


  },



  elite_training: {


    id:
      "elite_training",


    name:
      "Elite Training",


    description:
      "High-level combat training with rare progression rewards.",


    reward: {


      exp:
        650


    },


    requirement: {


      minimumPL:
        1800


    },


    progression: {


      discipline:
        "nin",


      amount:
        50


    }


  }


};



// =========================================================
// GET TRAINING ACTIVITY DATA
// =========================================================


function getTrainingActivityData(
  activityId
) {


  return (
    TRAINING_DATABASE[
      activityId
    ] ||
    null
  );


}

// =========================================================
// BRICK 136 — TRAINING ACTIVITY NORMALIZATION
// =========================================================
//
// Converts TRAINING_DATABASE entries into
// canonical Activity Engine definitions.
//
// Training Data
// ↓
// Structured Rewards
// ↓
// Activity Engine
//
// =========================================================


function normalizeTrainingActivityDefinition(
  activityData
) {


  if (
    !activityData
  ) {


    return null;


  }



  const rewards =
    [];



  // =========================================
  // PLAYER EXP
  // =========================================


  const expReward =
    Number(
      activityData.reward &&
      activityData.reward.exp
    ) || 0;



  if (
    expReward > 0
  ) {


    rewards.push({

      type:
        "experience",

      id:
        "exp",

      amount:
        expReward

    });


  }



  // =========================================
  // DISCIPLINE PROGRESSION
  // =========================================


  if (
    activityData.progression &&
    activityData.progression.discipline
  ) {


    const disciplineId =
      activityData.progression.discipline;



    const discipline =
      getShinobiDiscipline(
        disciplineId
      );



    if (
      discipline
    ) {


      rewards.push({

        type:
          "discipline",

        id:
          disciplineId,

        amount:
          Number(
            activityData.progression.amount
          ) || 0,

        source:
          discipline.trainingSource

      });


    }


  }



  return {


    id:
      activityData.id ||
      null,


    name:
      activityData.name ||
      "Unknown Training Activity",


    rewards:
      rewards,


    requirements:
      activityData.requirement ||
      {}


  };


}

// =========================================================
// BRICK 192 — TRAINING ACTIVITY READINESS + CONTENT ACCESS
// =========================================================
//
// Training Database
// ↓
// Chronicle Access
// ↓
// PL Recommendation
//
// Old minimumPL values remain advisory.
// Chronicle requirements are authoritative.
//
// =========================================================


function getTrainingActivityReadiness(
  activityId,
  characterId
) {


  const rawActivity =
    getTrainingActivityData(
      activityId
    );


  const character =
    getPlayerCharacter(
      characterId
    );


  if (
    !rawActivity ||
    !character
  ) {


    return {

      available:
        false,

      activityId:
        activityId || null,

      characterId:
        characterId || null,

      reason:
        "invalid_training_request"

    };


  }


  const definition =
    normalizeTrainingActivityDefinition(
      rawActivity
    );


  if (
    !definition
  ) {


    return {

      available:
        false,

      activityId:
        activityId,

      characterId:
        characterId,

      reason:
        "normalization_failed"

    };


  }


  const access =
    getTrainingAccessStatus(
      activityId
    );


  if (
    !access.accessible
  ) {


    return {

      available:
        false,

      activityId:
        activityId,

      characterId:
        characterId,

      reason:
        "chronicle_requirements_not_met",

      access:
        access

    };


  }


  const currentPL =
    calculateCurrentPL(
      character
    );


  const recommendedPL =
    Number(
      definition.requirements &&
      definition.requirements.minimumPL
    ) || 0;


  return {

    available:
      true,

    activityId:
      activityId,

    characterId:
      characterId,

    currentPL:
      currentPL,

    recommendedPL:
      recommendedPL,

    meetsRecommendation:
      (
        recommendedPL <= 0 ||
        currentPL >=
          recommendedPL
      ),

    requirementsEnforced:
      true,

    access:
      access

  };


}


// =========================================================
// BRICK 138 — TRAINING ACTIVITY EXECUTION BRIDGE
// =========================================================


function startTraining(
  activityId,
  characterId
) {


  console.log(
    "TRAINING ACTION START:",
    activityId,
    characterId
  );



  // =========================================
  // CHARACTER
  // =========================================


  const character =
    getPlayerCharacter(
      characterId
    );



  if (
    !character
  ) {


    console.log(
      "Training character not found:",
      characterId
    );


    return false;


  }



  // =========================================
  // TRAINING DATA
  // =========================================


  const rawActivity =
    getTrainingActivityData(
      activityId
    );



  if (
    !rawActivity
  ) {


    console.log(
      "Training activity not found:",
      activityId
    );


    return false;


  }



  const activityDefinition =
    normalizeTrainingActivityDefinition(
      rawActivity
    );



  if (
    !activityDefinition
  ) {


    console.log(
      "Training activity normalization failed:",
      activityId
    );


    return false;


  }



  // =========================================
  // READINESS
  // =========================================


  const readiness =
    getTrainingActivityReadiness(
      activityId,
      characterId
    );



  if (
    !readiness.available
  ) {


    console.log(
      "Training activity unavailable:",
      readiness
    );


    return false;


  }



  if (
    !readiness.meetsRecommendation
  ) {


    console.log(
      "Training PL recommendation not met:",
      {
        currentPL:
          readiness.currentPL,

        recommendedPL:
          readiness.recommendedPL,

        enforced:
          false
      }
    );


  }



  // =========================================
  // EXECUTE
  // =========================================


  const result =
    executeActivityDefinition(
      activityId,
      characterId,
      activityDefinition
    );



  if (
    !result
  ) {


    console.log(
      "Training activity execution failed."
    );


    return false;


  }



  console.log(
    "TRAINING ACTIVITY COMPLETE:",
    result
  );



  return result;


}

// =========================================================
// BRICK 146 — DATA-DRIVEN BATTLE / LOOT OVERLAY
// =========================================================
//
// Renders Encounter cards directly from
// ENCOUNTER_DATABASE + enemyDatabase.
//
// Removes hard-coded reward presentation.
//
// =========================================================


function getEncounterRewardSummary(
  encounter
) {


  if (
    !encounter ||
    !encounter.rewards
  ) {


    return "Rewards unavailable";


  }



  const ryo =
    encounter.rewards.ryo;



  if (
    !ryo
  ) {


    return "Ryō: —";


  }



  return (
    `Ryō: ${ryo.min} – ${ryo.max}`
  );


}





function getEncounterDropSummary(
  encounter
) {


  if (
    !encounter ||
    !encounter.rewards
  ) {


    return "No known drops";


  }



  const rareDrops =
    encounter.rewards.rareDrops;



  if (
    Array.isArray(
      rareDrops
    ) &&
    rareDrops.length > 0
  ) {


    const bestRareDrop =
      rareDrops[0];



    return (
      `${bestRareDrop.name}: ${bestRareDrop.chance}%`
    );


  }



  const commonDrops =
    encounter.rewards.commonDrops;



  if (
    Array.isArray(
      commonDrops
    ) &&
    commonDrops.length > 0
  ) {


    const bestCommonDrop =
      commonDrops[0];



    return (
      `${bestCommonDrop.name}: ${bestCommonDrop.chance}%`
    );


  }



  return "No item drops";


}





function renderBattleOverlay(
  container
) {


  console.log(
    "Battle overlay opened"
  );



  const location =
    selectedLocationNode;



  const encounterCards =
    Object.keys(
      ENCOUNTER_DATABASE
    )
      .map(
        encounterId =>
          getEncounterDefinition(
            encounterId
          )
      )
      .filter(
        encounter =>
          !!encounter
      )
      .map(
        encounter => {


          return createActivityCard(

            encounter.name,

            encounter.description,

            getEncounterRewardSummary(
              encounter
            ),

            getEncounterDropSummary(
              encounter
            ),

            `startEncounterActivity('${encounter.id}')`

          );


        }
      )
      .join("");



  container.innerHTML = `

    <div style="
      display:flex;
      flex-direction:column;
      flex:1;
    ">

      <h2 style="
        color:#D6A93A;
        font-size:16px;
        margin-bottom:5px;
      ">
        ${
          location
            ? location.name.toUpperCase()
            : "COMBAT AREA"
        }
      </h2>

      <p style="
        color:#94A3B8;
        font-size:10px;
        margin-bottom:16px;
      ">
        Choose your opponent.
      </p>

      <div style="
        display:grid;
        grid-template-columns:
          repeat(
            3,
            minmax(0,1fr)
          );
        gap:12px;
      ">

        ${encounterCards}

      </div>

    </div>
  `;


}


