// =========================================================
// BRICK 868 — VICTORY CLAIM WITHOUT NAVIGATION
// =========================================================
function claimVictoryRewardsFromOverlay() {
  if (currentOverlayType !== "victory") {
    return {success:false,reason:"victory_overlay_not_active"};
  }

  const alreadyClaimed=!!(currentBattle.rewards&&currentBattle.rewards.claimed===true);
  const claimed=alreadyClaimed?true:claimCurrentBattleRewards();
  if (claimed!==true) return {success:false,reason:"victory_reward_claim_failed"};

  // Re-render the same completed result. No navigation and no second claim.
  saveTestState();
  openOverlay("victory");
  return {success:true,claimed:true,navigated:false};
}


// =========================================================
// VICTORY CONTINUE
// =========================================================

function continueAfterVictory() {


  // =========================================
  // CLAIM ≠ CONTINUE
  // =========================================
  // A completed Battle may remain on its Victory presentation after the
  // reward entitlement has been durably claimed. Navigation is a later
  // lifecycle transition and must never silently perform the claim.
  // =========================================

  if (
    !currentBattle.rewards ||
    currentBattle.rewards.generated !== true ||
    currentBattle.rewards.claimed !== true
  ) {
    console.log("Victory rewards must be claimed before CONTINUE.");
    return {success:false,reason:"victory_rewards_unclaimed"};
  }


  // =========================================
  // END ACTIVE BATTLE
  // =========================================

  currentBattle.active =
    false;


  // =========================================
  // BRICK 83 — GAMEPLAY LIFECYCLE CHECK
  // =========================================
  //
  // This is harmless for every existing normal encounter.
  //
  // Only a gameplay source explicitly carrying:
  //
  // progressionTrigger: "run_completion"
  //
  // can complete the current difficulty.
  //
  // =========================================

  const lifecycleResult =
    processGameplayRunCompletion({

      enemy:
        currentBattle.enemy ||
        selectedEnemy ||
        null,

      location:
        selectedLocationNode ||
        null

    });


  // =========================================
  // COMPLETION FLOW HAS TAKEN CONTROL
  // =========================================

  if (
    lifecycleResult &&
    lifecycleResult.handled ===
      true &&
    lifecycleResult.flowOpened ===
      true
  ) {


    console.log(
      "Gameplay lifecycle opened completion flow."
    );


    return;

  }


  // =========================================
  // COMPLETION WAS DETECTED BUT FLOW FAILED
  // =========================================
  //
  // Do NOT silently send the player away from a completed
  // run if its completion UI could not open.
  //
  // Preserve the completed save and expose the problem.
  //
  // =========================================

  if (
    lifecycleResult &&
    lifecycleResult.handled ===
      true &&
    lifecycleResult.completed ===
      true &&
    lifecycleResult.flowOpened !==
      true
  ) {


    console.error(
      "Run completed, but completion flow did not open:",
      lifecycleResult
    );


    return;

  }


  // =========================================
  // BRICK 739 — RESUME AUTHORED CALLER AFTER ORDINARY REWARD FLOW
  // =========================================
  const callerResume = resumeBattleCallerAfterCompletion("victory");
  if (callerResume && callerResume.success === true) {
    return;
  }


  // =========================================
  // SAVE DEVELOPMENT STATE
  // =========================================

  saveTestState();


  // =========================================
  // ORDINARY VICTORY
  // RETURN TO ENCOUNTER SCREEN
  // =========================================

  openOverlay(
    "battle"
  );

}

// BRICK 394 — BATTLE RUNTIME SOURCE-PACKAGE LEDGER
// BRICK 395 — EXACT PROJECTION IDENTITY / IDEMPOTENCE
// BRICK 396 — EXPLICIT PACKAGE OVERLAP SEMANTICS
// BRICK 397 — EMBODIED EXPRESSION GUARD
// BRICK 398 — SOURCE-SCOPED PACKAGE REMOVAL
// BRICK 399 — TEMPORARY CAPACITY RUNTIME STORE
// BRICK 400 — ATTACHED SUMMON RUNTIME STATE
// BRICK 401 — RUNTIME SAVE / RESTORE EXTENSION
// =========================================================

function createBattleRuntimeState() {
  return {
    battleId: currentBattle.battleId || null,
    actionSequence: 0,
    remainingPL: { player:{}, enemy:{} },
    temporaryCapacity: { player:{}, enemy:{} },
    battlePouch: { preparedItemIds:[] },
    effectiveStateProjections: [],
    attachedSummons: { player:{}, enemy:{} },
    summonActionState: { actorParticipantId:null, summonId:null, mode:"closed" },
    actionOpportunityState: { counters:{player:{},enemy:{}}, startedTokens:{} },
    battleContext: { facts:{}, tags:[], sourceRefs:[] },
    transientStates: [],
    conditions: [],
    evidence: [],
    // BRICK 858 — observer-relative historical access is a separate runtime surface.
    historicalReferences: [],
    historicalTraces: []
  };
}

function ensureBattleRuntimeState() {
  if (!currentBattle.runtime || currentBattle.runtime.battleId !== currentBattle.battleId) {
    currentBattle.runtime = createBattleRuntimeState();
  }
  const runtime = currentBattle.runtime;
  if (!runtime.remainingPL || typeof runtime.remainingPL !== "object") runtime.remainingPL={player:{},enemy:{}};
  if (!runtime.remainingPL.player || typeof runtime.remainingPL.player !== "object") runtime.remainingPL.player={};
  if (!runtime.remainingPL.enemy || typeof runtime.remainingPL.enemy !== "object") runtime.remainingPL.enemy={};
  if (!runtime.temporaryCapacity || typeof runtime.temporaryCapacity !== "object") runtime.temporaryCapacity={player:{},enemy:{}};
  if (!runtime.temporaryCapacity.player || typeof runtime.temporaryCapacity.player !== "object") runtime.temporaryCapacity.player={};
  if (!runtime.temporaryCapacity.enemy || typeof runtime.temporaryCapacity.enemy !== "object") runtime.temporaryCapacity.enemy={};
  if (!runtime.battlePouch || typeof runtime.battlePouch !== "object") runtime.battlePouch={preparedItemIds:[]};
  if (!Array.isArray(runtime.battlePouch.preparedItemIds)) runtime.battlePouch.preparedItemIds=[];
  if (!Array.isArray(runtime.effectiveStateProjections)) runtime.effectiveStateProjections=[];
  if (!runtime.attachedSummons || typeof runtime.attachedSummons !== "object") runtime.attachedSummons={player:{},enemy:{}};
  if (!runtime.attachedSummons.player || typeof runtime.attachedSummons.player !== "object") runtime.attachedSummons.player={};
  if (!runtime.attachedSummons.enemy || typeof runtime.attachedSummons.enemy !== "object") runtime.attachedSummons.enemy={};
  if (!runtime.summonActionState || typeof runtime.summonActionState !== "object") runtime.summonActionState={actorParticipantId:null,summonId:null,mode:"closed"};
  if (!runtime.actionOpportunityState || typeof runtime.actionOpportunityState !== "object") runtime.actionOpportunityState={counters:{player:{},enemy:{}},startedTokens:{}};
  if (!runtime.actionOpportunityState.counters || typeof runtime.actionOpportunityState.counters !== "object") runtime.actionOpportunityState.counters={player:{},enemy:{}};
  if (!runtime.actionOpportunityState.counters.player) runtime.actionOpportunityState.counters.player={};
  if (!runtime.actionOpportunityState.counters.enemy) runtime.actionOpportunityState.counters.enemy={};
  if (!runtime.actionOpportunityState.startedTokens || typeof runtime.actionOpportunityState.startedTokens !== "object") runtime.actionOpportunityState.startedTokens={};
  if (!runtime.battleContext || typeof runtime.battleContext !== "object") runtime.battleContext={facts:{},tags:[],sourceRefs:[]};
  if (!runtime.battleContext.facts || typeof runtime.battleContext.facts !== "object") runtime.battleContext.facts={};
  if (!Array.isArray(runtime.battleContext.tags)) runtime.battleContext.tags=[];
  if (!Array.isArray(runtime.battleContext.sourceRefs)) runtime.battleContext.sourceRefs=[];
  if (!Array.isArray(runtime.transientStates)) runtime.transientStates=[];
  if (!Array.isArray(runtime.conditions)) runtime.conditions=[];
  if (!Array.isArray(runtime.evidence)) runtime.evidence=[];
  if (!Array.isArray(runtime.historicalReferences)) runtime.historicalReferences=[];
  if (!Array.isArray(runtime.historicalTraces)) runtime.historicalTraces=[];
  return runtime;
}

function initializeBattleSourcePackageRuntime() {
  const runtime = ensureBattleRuntimeState();
  runtime.effectiveStateProjections = [];
  runtime.temporaryCapacity = { player:{}, enemy:{} };
  runtime.attachedSummons = { player:{}, enemy:{} };
  runtime.summonActionState = { actorParticipantId:null, summonId:null, mode:"closed" };
  runtime.actionOpportunityState = { counters:{player:{},enemy:{}}, startedTokens:{} };
  runtime.battleContext = { facts:{}, tags:[], sourceRefs:[] };
  runtime.historicalReferences = [];
  runtime.historicalTraces = [];
  return runtime;
}

// =========================================================
// BRICK 497 — DEDICATED-VARIANT RUNTIME PACKAGE INITIALIZATION
// BRICK 508 — COERCIVE BUFFER DEPLETION USES COMMON CAPACITY ORDER
// BRICK 509 — COERCIVE BUFFER SOURCE REMOVAL / EXPIRY
// BRICK 566 — STAGED-REPRESENTATION RUNTIME MIGRATION
// =========================================================
function removeSuppressedBattleEffectiveStateProjectionsForCharacter(actor,reason="representation_stage_suppression") {
  if (!actor) return [];
  const suppressedIds=getCharacterSuppressedEmbodiedExpressionIds(actor);
  if (suppressedIds.length===0) return [];
  const active=getBattleParticipantEffectiveStateProjections("player",actor.id);
  const removed=[];
  active.filter(projection=>projection&&suppressedIds.includes(projection.exactPackageId)).forEach(projection=>{
    removed.push(...removeBattleEffectiveStateProjection(projection.projectionKey,"player",actor.id,reason));
  });
  return removed;
}

function ensureDedicatedRepresentationLifecycleState(actor) {
  if (!actor) return null;
  const registryId=getCharacterRegistryId(actor);
  removeSuppressedBattleEffectiveStateProjectionsForCharacter(actor);
  if (registryId==="baryon_mode") {
    const existing=findBattleTransientState({stateKey:"baryon_mode_lifecycle",targetSide:"player",targetParticipantId:actor.id});
    if (existing) return existing;
    const record=getCharacterRegistryEntry("baryon_mode");
    const maximum=Math.max(0,Math.floor(Number(record&&record.lifecycleActionOpportunities)||5));
    return addBattleTransientState({
      stateKey:"baryon_mode_lifecycle",
      sourceSide:"player",sourceParticipantId:actor.id,
      targetSide:"player",targetParticipantId:actor.id,
      ownerRef:{type:"character_registry",id:"baryon_mode"},
      data:{
        maximumActionOpportunities:maximum,
        remainingBaryonActionOpportunities:maximum,
        lifecycleTermination:"representation_end",
        battlePLCost:false,injuryCost:false,selfDamage:false,
        lifespanErosionStateKey:"baryon_lifespan_erosion"
      }
    });
  }
  if (registryId==="naruto_v2") {
    const existing=findBattleTransientState({stateKey:"naruto_v2_instability",targetSide:"player",targetParticipantId:actor.id});
    if (existing) return existing;
    return addBattleTransientState({
      stateKey:"naruto_v2_instability",
      sourceSide:"player",sourceParticipantId:actor.id,
      targetSide:"player",targetParticipantId:actor.id,
      ownerRef:{type:"character_registry",id:"naruto_v2"},
      data:{instabilityState:"stable",categorical:true,writesHiddenStats:false}
    });
  }
  return null;
}

function initializeBattleKisoganStartsActiveFromDeployment() {
  if (!currentBattle.active||!currentBattle.deployment) return [];
  const results=[];
  ["player","enemy"].forEach(side=>{
    const slots=currentBattle.deployment[side]&&Array.isArray(currentBattle.deployment[side].slots)?currentBattle.deployment[side].slots:[];
    slots.forEach(slot=>{
      if (!slot||!slot.participantId) return;
      const actor=getBattleParticipantByIdentity(side,slot.participantId);
      if (!actor) return;
      const state=initializeAuthoredKisoganStartsActive(actor,side);
      if (state) results.push({side,participantId:actor.id,stateId:state.stateId});
    });
  });
  return results;
}

function initializeBattleDedicatedVariantRuntimePackages() {
  if (!currentBattle.active||!currentBattle.deployment||!currentBattle.deployment.player) return [];
  const results=[];
  (currentBattle.deployment.player.slots||[]).forEach(slot=>{
    if (!slot||!slot.participantId) return;
    const actor=getPlayerCharacter(slot.participantId);
    if (!actor) return;
    if (getCharacterRegistryId(actor)==="coercive_cloak") {
      results.push(activateBattleEffectiveStatePackage({side:"player",participantId:actor.id,sourceId:"coercive_cloak",exactPackageId:"coercive_chakra_buffer",expressionStateId:"one_tail_coercive"}));
    }
    const lifecycleState=ensureDedicatedRepresentationLifecycleState(actor);
    if (lifecycleState) results.push({success:true,representationLifecycle:true,state:lifecycleState});
  });
  return results;
}

function cloneBattleRuntimeValue(value) {
  try { return JSON.parse(JSON.stringify(value)); }
  catch (error) { console.log("Battle runtime clone failed:", error); return null; }
}

function createBattleRuntimeRecordId(prefix) {
  const runtime = ensureBattleRuntimeState();
  return `${prefix}_${currentBattle.battleId || "battle"}_${runtime.actionSequence}_${Date.now()}_${Math.floor(Math.random()*100000)}`;
}

function getBattleRuntimeSaveState() {
  const runtime = ensureBattleRuntimeState();
  return cloneBattleRuntimeValue({
    battleId:currentBattle.battleId || null,
    actionSequence:Number(runtime.actionSequence)||0,
    remainingPL:runtime.remainingPL,
    temporaryCapacity:runtime.temporaryCapacity,
    battlePouch:runtime.battlePouch,
    effectiveStateProjections:runtime.effectiveStateProjections,
    attachedSummons:runtime.attachedSummons,
    summonActionState:runtime.summonActionState,
    actionOpportunityState:runtime.actionOpportunityState,
    battleContext:runtime.battleContext,
    transientStates:runtime.transientStates,
    conditions:runtime.conditions,
    evidence:runtime.evidence,
    historicalReferences:runtime.historicalReferences,
    historicalTraces:runtime.historicalTraces
  });
}

function restoreBattleRuntimeState(rawRuntime) {
  if (!rawRuntime || typeof rawRuntime !== "object") {
    currentBattle.runtime = createBattleRuntimeState();
    initializeBattleRemainingPLFromDeployment({ preserveExistingEnemyPower:true });
    initializeBattlePouchFromPreparedSelection();
    initializeBattleAttachedSummonRuntimeFromDeployment();
    return currentBattle.runtime;
  }
  currentBattle.runtime = {
    battleId:currentBattle.battleId || null,
    actionSequence:Number(rawRuntime.actionSequence)||0,
    remainingPL:rawRuntime.remainingPL && typeof rawRuntime.remainingPL === "object" ? rawRuntime.remainingPL : {player:{},enemy:{}},
    temporaryCapacity:rawRuntime.temporaryCapacity && typeof rawRuntime.temporaryCapacity === "object" ? rawRuntime.temporaryCapacity : {player:{},enemy:{}},
    battlePouch:rawRuntime.battlePouch && typeof rawRuntime.battlePouch === "object" ? rawRuntime.battlePouch : {preparedItemIds:normalizeBattlePouchSelection(playerData.battlePouch).itemIds},
    effectiveStateProjections:Array.isArray(rawRuntime.effectiveStateProjections) ? rawRuntime.effectiveStateProjections : [],
    attachedSummons:rawRuntime.attachedSummons && typeof rawRuntime.attachedSummons === "object" ? rawRuntime.attachedSummons : {player:{},enemy:{}},
    summonActionState:rawRuntime.summonActionState && typeof rawRuntime.summonActionState === "object" ? rawRuntime.summonActionState : {actorParticipantId:null,summonId:null,mode:"closed"},
    actionOpportunityState:rawRuntime.actionOpportunityState && typeof rawRuntime.actionOpportunityState === "object" ? rawRuntime.actionOpportunityState : {counters:{player:{},enemy:{}},startedTokens:{}},
    battleContext:rawRuntime.battleContext && typeof rawRuntime.battleContext === "object" ? rawRuntime.battleContext : {facts:{},tags:[],sourceRefs:[]},
    transientStates:Array.isArray(rawRuntime.transientStates) ? rawRuntime.transientStates : [],
    conditions:Array.isArray(rawRuntime.conditions) ? rawRuntime.conditions : [],
    evidence:Array.isArray(rawRuntime.evidence) ? rawRuntime.evidence : [],
    historicalReferences:Array.isArray(rawRuntime.historicalReferences) ? rawRuntime.historicalReferences : [],
    historicalTraces:Array.isArray(rawRuntime.historicalTraces) ? rawRuntime.historicalTraces : []
  };
  const runtime=ensureBattleRuntimeState();
  const hasAnyRemainingPL=Object.keys(runtime.remainingPL.player).length>0 || Object.keys(runtime.remainingPL.enemy).length>0;
  if (!hasAnyRemainingPL) initializeBattleRemainingPLFromDeployment({ preserveExistingEnemyPower:true });
  else syncBattleEnemyPowerCompatibilityProjection();
  return runtime;
}

function getBattleEffectiveStateProjection(projectionKey, side, participantId) {
  return ensureBattleRuntimeState().effectiveStateProjections.find(projection =>
    projection && projection.projectionKey === projectionKey && projection.targetRef &&
    projection.targetRef.side === side && projection.targetRef.participantId === participantId
  ) || null;
}

function getBattleParticipantEffectiveStateProjections(side, participantId) {
  return ensureBattleRuntimeState().effectiveStateProjections.filter(projection =>
    projection && projection.targetRef && projection.targetRef.side === side && projection.targetRef.participantId === participantId
  );
}

function removeBattleEffectiveStateProjection(projectionKey, side, participantId, reason="source_removed") {
  const runtime=ensureBattleRuntimeState();
  const removed=[];
  runtime.effectiveStateProjections=runtime.effectiveStateProjections.filter(projection => {
    const match=projection && projection.projectionKey===projectionKey && projection.targetRef &&
      projection.targetRef.side===side && projection.targetRef.participantId===participantId;
    if (match) removed.push(projection);
    return !match;
  });
  removed.forEach(projection => {
    removeBattleTemporaryCapacityByProjection(projection.projectionKey, side, participantId);
    recordBattleEvidence({ eventType:"effective_state_projection_removed", actorRef:createBattleParticipantRef(side,participantId),
      sourceRefs:[{type:"source",id:projection.sourceId}], data:{projectionKey:projection.projectionKey, exactPackageId:projection.exactPackageId, reason} });
  });
  return removed;
}

function removeBattleEffectiveStatePackagesBySource(side, participantId, sourceId, reason="source_removed") {
  const projections=getBattleParticipantEffectiveStateProjections(side,participantId).filter(p=>p.sourceId===sourceId);
  const removed=[];
  projections.forEach(p=>removed.push(...removeBattleEffectiveStateProjection(p.projectionKey,side,participantId,reason)));
  return removed;
}

function activateBattleEffectiveStatePackage(definition) {
  if (!definition || !definition.side || !definition.participantId || !definition.sourceId || !definition.exactPackageId) {
    return {success:false,reason:"projection_identity_incomplete"};
  }
  const participant=getBattleParticipantByIdentity(definition.side,definition.participantId);
  if (!participant) return {success:false,reason:"participant_missing"};
  if (definition.side === "player") {
    const entitySource=getEntityDefinition(definition.sourceId);
    const characterSource=getCharacterRegistryEntry(definition.sourceId);
    if (characterSource && getCharacterRegistryId(participant)!==definition.sourceId) {
      return {success:false,reason:"character_source_owner_mismatch"};
    }
    // =====================================================
    // BRICK 510 — EMBODIED PACKAGE NO-DOUBLE-COUNT GUARD
    // =====================================================
    if (characterEmbodiesExactPackage(participant,definition.exactPackageId)) {
      return {success:false,reason:"exact_package_already_embodied"};
    }
    if (characterRegistryExpressionIsExcluded(participant,definition.exactPackageId)) {
      return {success:false,reason:"exact_expression_excluded_for_representation"};
    }
    if (characterRegistryExpressionIsSuppressedByEmbodiment(participant,definition.exactPackageId)) {
      return {success:false,reason:"exact_package_suppressed_by_representation"};
    }
    if (entitySource && !isBattleEntitySourceAvailableForCharacter(participant,definition.sourceId)) {
      return {success:false,reason:"authoritative_source_not_available"};
    }
  }
  const catalog=getEffectiveStatePackageDefinition(definition.sourceId,definition.exactPackageId);
  if (!catalog) return {success:false,reason:"package_not_authored"};
  if (catalog.classification !== "effective_state") return {success:false,reason:"package_is_not_effective_state"};
  const expressionStateId=definition.expressionStateId || catalog.defaultExpressionStateId || "default";
  const projectionKey=createEffectiveStateProjectionKey(definition.sourceId,definition.exactPackageId,expressionStateId);
  const existing=getBattleEffectiveStateProjection(projectionKey,definition.side,definition.participantId);
  if (existing) return {success:true,idempotent:true,projection:existing};

  const overlapMode=definition.overlapMode || catalog.overlapMode || "coexists";
  const overlapPackageKeys=Array.isArray(definition.overlapPackageKeys) ? definition.overlapPackageKeys : [];
  const active=getBattleParticipantEffectiveStateProjections(definition.side,definition.participantId);
  if (overlapMode === "mutually_exclusive" && active.some(p=>overlapPackageKeys.includes(p.packageKey))) {
    return {success:false,reason:"mutually_exclusive_package_active"};
  }
  if (["replaces","suppresses"].includes(overlapMode)) {
    active.filter(p=>overlapPackageKeys.includes(p.packageKey)).forEach(p=>
      removeBattleEffectiveStateProjection(p.projectionKey,definition.side,definition.participantId,overlapMode)
    );
  }

  const projection={
    projectionId:createBattleRuntimeRecordId("projection"), projectionKey,
    packageKey:catalog.packageKey, sourceId:definition.sourceId, exactPackageId:definition.exactPackageId,
    expressionStateId, classification:"effective_state", overlapMode,
    statModifiers:cloneCanonicalSevenStats(catalog.statModifiers),
    targetRef:createBattleParticipantRef(definition.side,definition.participantId),
    activationOwner:definition.activationOwner || catalog.activationOwnership || null,
    expirationOwner:definition.expirationOwner || catalog.expirationOwnership || null,
    activationActionId:definition.activationActionId || null,
    durationActionOpportunities:Number.isFinite(Number(definition.durationActionOpportunities))
      ? Math.max(0,Math.floor(Number(definition.durationActionOpportunities)))
      : (Number.isFinite(Number(catalog.durationActionOpportunities)) ? Math.max(0,Math.floor(Number(catalog.durationActionOpportunities))) : null),
    remainingActionOpportunities:Number.isFinite(Number(definition.durationActionOpportunities))
      ? Math.max(0,Math.floor(Number(definition.durationActionOpportunities)))
      : (Number.isFinite(Number(catalog.durationActionOpportunities)) ? Math.max(0,Math.floor(Number(catalog.durationActionOpportunities))) : null),
    createdAt:Date.now()
  };
  ensureBattleRuntimeState().effectiveStateProjections.push(projection);
  const overlay=Number(catalog.temporaryCapacityOverlay)||0;
  if (overlay>0) addBattleTemporaryCapacityOverlay(definition.side,definition.participantId,overlay,projection.projectionKey);
  recordBattleEvidence({eventType:"effective_state_projection_applied",actionId:projection.activationActionId,
    actorRef:createBattleParticipantRef(definition.side,definition.participantId),sourceRefs:[{type:"source",id:definition.sourceId}],
    data:{projectionKey,exactPackageId:definition.exactPackageId,expressionStateId,overlapMode,statModifiers:projection.statModifiers}});
  return {success:true,idempotent:false,projection};
}

function getBattleEffectiveStateStatModifiersForCharacter(character) {
  const totals={nin:0,tai:0,buki:0,fuin:0,kin:0,gen:0,stamina:0};
  if (!character || !currentBattle || !currentBattle.active || !currentBattle.runtime) return totals;
  getBattleParticipantEffectiveStateProjections("player",character.id).forEach(projection => {
    Object.entries(projection.statModifiers || {}).forEach(([stat,amount]) => {
      if (totals[stat] !== undefined) totals[stat] += Number(amount)||0;
    });
  });
  return totals;
}

function isBattleEntitySourceAvailableForCharacter(character, sourceId) {
  const entity=getEntityDefinition(sourceId);
  if (!character || !entity) return false;
  if (entity.entityType === "hosted_entity_partition") {
    return evaluateHostedEntityAccess(character.id,sourceId,{requireCooperative:false}).available===true;
  }
  if (isAttachableSummonEntity(entity)) {
    return getAttachedSummonIdForCharacter(character.id)===sourceId;
  }
  return false;
}

function activateBattleEntityEnhancement(characterId, sourceId, exactPackageId, expressionStateId=null) {
  const character=getPlayerCharacter(characterId);
  if (!character || !currentBattle.active) return {success:false,reason:"battle_or_character_missing"};
  const entity=getEntityDefinition(sourceId);
  if (!entity || !isBattleEntitySourceAvailableForCharacter(character,sourceId)) return {success:false,reason:"source_not_available"};
  if (entity.entityType==="hosted_entity_partition") {
    const access=evaluateHostedEntityAccess(character.id,sourceId,{expressionId:exactPackageId});
    if (!access.available) return {success:false,reason:access.reason,access};
  }
  return activateBattleEffectiveStatePackage({side:"player",participantId:character.id,sourceId,exactPackageId,expressionStateId});
}

// =========================================================
// BRICK 422 — HOSTED-SOURCE EXPRESSION ACCESS GUARD
// BRICK 423 — HOSTED-SOURCE REMOVAL CLEANUP
// BRICK 622 — ATTACHED-SOURCE DEFAULT ENHANCEMENT PROJECTION
// BRICK 623 — ATTACHED-SOURCE IDEMPOTENCE DIAGNOSTIC
// =========================================================

function setHostedEntityBattlePresence(characterId, entityId, present) {
  const character=getPlayerCharacter(characterId);
  const binding=getHostedEntityBinding(characterId,entityId);
  if (!character || !binding) return {success:false,reason:"hosted_binding_missing"};
  binding.presenceState=present===true?"present":"absent";
  if (present!==true && currentBattle.active) removeBattleEffectiveStatePackagesBySource("player",character.id,entityId,"hosted_source_not_present");
  return {success:true,entityId,presenceState:binding.presenceState};
}

const DEFAULT_ATTACHED_SUMMON_ENHANCEMENT_PACKAGES = {
  mk_enma:["adamantine_presence"],
  koto_crow:["shared_genjutsu_focus"],
  iron_maiden:["immovable_frame"],
  ibuse:["salamanders_endurance"],
  mirage_clam:["illusion_lattice"],
  wr_kamatari:["sicklewind_guidance"],
  triple_rashomon:["gatekeeper_formulae"],
  nine_tails:["vast_chakra_reserve"],
  menma_nine_tails:["yin_chakra_reservoir"],
  gamakichi:["toad_chakra_guidance"]
};

function getDefaultAttachedSummonEnhancementPackageIds(entityId) {
  const ids=DEFAULT_ATTACHED_SUMMON_ENHANCEMENT_PACKAGES[entityId];
  return Array.isArray(ids)?[...ids]:[];
}

function applyDefaultBattleAttachedSummonEnhancements(characterId,entityId,options={}) {
  const character=getPlayerCharacter(characterId);
  const entity=getEntityDefinition(entityId);
  if (!character||!entity||!isAttachableSummonEntity(entity)) return [];
  if (getAttachedSummonIdForCharacter(character.id)!==entityId) return [];
  return getDefaultAttachedSummonEnhancementPackageIds(entityId).map(exactPackageId=>{
    const result=activateBattleEffectiveStatePackage({
      side:"player",participantId:character.id,sourceId:entityId,exactPackageId,
      expressionStateId:"attached_enhancement",activationOwner:"attached_summon_source",
      activationActionId:options.activationActionId||null
    });
    return {exactPackageId,...result};
  });
}

function attachEntitySummonToCharacter(characterId, entityId) {
  const character=getPlayerCharacter(characterId);
  const entity=getEntityDefinition(entityId);
  if (!character || !isAttachableSummonEntity(entity)) return false;
  if (!playerData.entities || !Array.isArray(playerData.entities.ownedEntityIds) || !playerData.entities.ownedEntityIds.includes(entityId)) return false;
  const registryId=getCharacterRegistryId(character);
  const previous=playerData.entities.attachedSummonByCharacterRegistryId[registryId] || null;
  if (previous && currentBattle.active) removeBattleEffectiveStatePackagesBySource("player",character.id,previous,"summon_replaced");
  playerData.entities.attachedSummonByCharacterRegistryId[registryId]=entityId;
  if (currentBattle.active) initializeBattleAttachedSummonForParticipant("player",character.id);
  savePlayerData();
  return true;
}

function detachEntitySummonFromCharacter(characterId) {
  const character=getPlayerCharacter(characterId);
  if (!character || !playerData.entities) return false;
  const registryId=getCharacterRegistryId(character);
  const previous=playerData.entities.attachedSummonByCharacterRegistryId[registryId] || null;
  if (!previous) return false;
  delete playerData.entities.attachedSummonByCharacterRegistryId[registryId];
  if (currentBattle.active) {
    removeBattleEffectiveStatePackagesBySource("player",character.id,previous,"summon_detached");
    delete ensureBattleRuntimeState().attachedSummons.player[character.id];
  }
  savePlayerData();
  return true;
}

function initializeBattleAttachedSummonForParticipant(side, participantId) {
  if (side !== "player") return null;
  const character=getPlayerCharacter(participantId);
  const summonId=character ? getAttachedSummonIdForCharacter(character.id) : null;
  const runtime=ensureBattleRuntimeState();
  if (!summonId || !getEntityDefinition(summonId)) { delete runtime.attachedSummons.player[participantId]; return null; }
  runtime.attachedSummons.player[participantId]={participantId,summonId,state:"attached",manifestedSkillId:null};
  const enhancementResults=applyDefaultBattleAttachedSummonEnhancements(character.id,summonId);
  runtime.attachedSummons.player[participantId].enhancementPackageIds=enhancementResults.filter(result=>result&&result.success===true).map(result=>result.exactPackageId);
  return runtime.attachedSummons.player[participantId];
}

function initializeBattleAttachedSummonRuntimeFromDeployment() {
  const runtime=ensureBattleRuntimeState();
  runtime.attachedSummons={player:{},enemy:{}};
  const slots=currentBattle.deployment && currentBattle.deployment.player && Array.isArray(currentBattle.deployment.player.slots)
    ? currentBattle.deployment.player.slots : [];
  slots.forEach(slot=>{if(slot&&slot.participantId) initializeBattleAttachedSummonForParticipant("player",slot.participantId);});
  return runtime.attachedSummons;
}

function getBattleAttachedSummon(side, participantId) {
  const runtime=ensureBattleRuntimeState();
  return runtime.attachedSummons[side] ? (runtime.attachedSummons[side][participantId] || null) : null;
}

function manifestBattleAttachedSummon(side, participantId, summonSkillId) {
  const record=getBattleAttachedSummon(side,participantId);
  if (!record || record.state !== "attached") return null;
  record.state="manifested"; record.manifestedSkillId=summonSkillId || null;
  return record;
}

function returnBattleAttachedSummon(side, participantId) {
  const record=getBattleAttachedSummon(side,participantId);
  if (!record) return null;
  record.state="attached"; record.manifestedSkillId=null;
  return record;
}



function runAttachedSummonEnhancementProjectionDiagnostics() {
  const expected={
    mk_enma:"adamantine_presence",koto_crow:"shared_genjutsu_focus",iron_maiden:"immovable_frame",
    ibuse:"salamanders_endurance",mirage_clam:"illusion_lattice",wr_kamatari:"sicklewind_guidance",
    triple_rashomon:"gatekeeper_formulae",nine_tails:"vast_chakra_reserve",menma_nine_tails:"yin_chakra_reservoir",gamakichi:"toad_chakra_guidance"
  };
  const result={
    exactDefaultMap:Object.entries(expected).every(([entityId,packageId])=>getDefaultAttachedSummonEnhancementPackageIds(entityId).includes(packageId)),
    bakuResolverNotStat:getDefaultAttachedSummonEnhancementPackageIds("de_baku").length===0,
    enmaCounselNotBlindDefault:!getDefaultAttachedSummonEnhancementPackageIds("mk_enma").includes("staffmasters_counsel"),
    specialRepresentationsExcluded:["breakout_kurama","kurama_complete","menma_kurama"].every(id=>getDefaultAttachedSummonEnhancementPackageIds(id).length===0),
    initializerProjects:initializeBattleAttachedSummonForParticipant.toString().includes("applyDefaultBattleAttachedSummonEnhancements"),
    detachRemovesSource:detachEntitySummonFromCharacter.toString().includes("removeBattleEffectiveStatePackagesBySource"),
    replacementRemovesSource:attachEntitySummonToCharacter.toString().includes("summon_replaced")
  };
  result.pass=Object.values(result).every(value=>value===true);
  console.table(result);
  return result;
}

// =========================================================
// BRICK 467 — AUTHORED BATTLE CONTEXT AUTHORITY
// =========================================================
function setBattleContextFact(key,value,sourceRef=null) {
  if (!key) return false;
  const context=ensureBattleRuntimeState().battleContext;
  context.facts[key]=value;
  if (sourceRef&&sourceRef.type&&sourceRef.id) context.sourceRefs.push({type:sourceRef.type,id:sourceRef.id});
  return true;
}

function getBattleContextFact(key) {
  const context=ensureBattleRuntimeState().battleContext;
  return key&&Object.prototype.hasOwnProperty.call(context.facts,key)?context.facts[key]:null;
}

function setBattleContextTags(tags,sourceRef=null) {
  const context=ensureBattleRuntimeState().battleContext;
  context.tags=Array.isArray(tags)?[...new Set(tags.filter(Boolean))]:[];
  if (sourceRef&&sourceRef.type&&sourceRef.id) context.sourceRefs.push({type:sourceRef.type,id:sourceRef.id});
  return [...context.tags];
}

function battleContextHasTag(tag) {
  return !!tag&&ensureBattleRuntimeState().battleContext.tags.includes(tag);
}

// BRICK 321 — REMAINING BATTLE PL HELPERS
// BRICK 605 — PER-ENEMY-PARTICIPANT REMAINING PL
// =========================================================

function getBattleRemainingPLSideStore(
  side
) {


  const runtime =
    ensureBattleRuntimeState();


  if (
    side !== "player" &&
    side !== "enemy"
  ) {

    return null;
  }


  return runtime.remainingPL[
    side
  ];
}


function getBattleParticipantByIdentity(
  side,
  participantId
) {
  if (!side||!participantId) return null;
  if (side==="player") return getPlayerCharacter(participantId);
  if (side==="enemy") return getBattleEnemyParticipantById(participantId);
  return null;
}

function getBattleRemainingPLRecord(
  side,
  participantId
) {


  const store =
    getBattleRemainingPLSideStore(
      side
    );


  if (
    !store ||
    !participantId
  ) {

    return null;
  }


  return store[
    participantId
  ] || null;
}


function setBattleRemainingPLRecord(
  side,
  participantId,
  maximum,
  current = maximum
) {


  const store =
    getBattleRemainingPLSideStore(
      side
    );


  if (
    !store ||
    !participantId
  ) {

    return null;
  }


  const maxPL =
    Math.max(
      1,
      Math.round(
        Number(
          maximum
        ) || 1
      )
    );


  const currentPL =
    Math.max(
      0,
      Math.min(
        maxPL,
        Math.round(
          Number(
            current
          ) || 0
        )
      )
    );


  store[
    participantId
  ] = {

    participantId:
      participantId,

    maximum:
      maxPL,

    current:
      currentPL

  };


  if (
    side === "enemy"
  ) {

    syncBattleEnemyPowerCompatibilityProjection();
  }


  return store[
    participantId
  ];
}


function getBattleRemainingPL(
  side,
  participantId
) {


  const record =
    getBattleRemainingPLRecord(
      side,
      participantId
    );


  return record
    ? Number(
        record.current
      ) || 0
    : 0;
}


function getBattleMaximumPL(
  side,
  participantId
) {


  const record =
    getBattleRemainingPLRecord(
      side,
      participantId
    );


  return record
    ? Number(
        record.maximum
      ) || 0
    : 0;
}


function setBattleRemainingPL(
  side,
  participantId,
  nextValue
) {


  const record =
    getBattleRemainingPLRecord(
      side,
      participantId
    );


  if (
    !record
  ) {

    return null;
  }


  record.current =
    Math.max(
      0,
      Math.min(
        record.maximum,
        Math.round(
          Number(
            nextValue
          ) || 0
        )
      )
    );


  if (
    side === "enemy"
  ) {

    syncBattleEnemyPowerCompatibilityProjection();
  }


  return record;
}


function syncBattleEnemyPowerCompatibilityProjection() {
  const activeEnemy=currentBattle.enemy||getBattleDeploymentParticipant("enemy",1);
  if (!activeEnemy) {
    currentBattle.enemyPower=0;
    currentBattle.enemyMaxPower=0;
    return false;
  }
  const record=getBattleRemainingPLRecord("enemy",activeEnemy.id);
  if (!record) return false;
  currentBattle.enemy=activeEnemy;
  currentBattle.enemyPower=record.current;
  currentBattle.enemyMaxPower=record.maximum;
  return true;
}

function initializeBattleRemainingPLFromDeployment(
  options = {}
) {
  if (!currentBattle.deployment) return false;
  const runtime=ensureBattleRuntimeState();
  runtime.remainingPL.player={};
  runtime.remainingPL.enemy={};

  const playerSlots=currentBattle.deployment.player&&Array.isArray(currentBattle.deployment.player.slots)
    ? currentBattle.deployment.player.slots:[];
  playerSlots.forEach(slot=>{
    if (!slot||!slot.participantId) return;
    const participant=getPlayerCharacter(slot.participantId);
    if (!participant) return;
    const maximum=calculateBattlePower(participant,"standard");
    setBattleRemainingPLRecord("player",participant.id,maximum,maximum);
  });

  const preservedEnemyId=currentBattle.enemy&&currentBattle.enemy.id?currentBattle.enemy.id:null;
  const preservedCurrent=options.preserveExistingEnemyPower===true?Math.max(0,Number(currentBattle.enemyPower)||0):null;
  const preservedMaximum=options.preserveExistingEnemyPower===true?Math.max(0,Number(currentBattle.enemyMaxPower)||0):null;
  const enemySlots=currentBattle.deployment.enemy&&Array.isArray(currentBattle.deployment.enemy.slots)
    ? currentBattle.deployment.enemy.slots:[];

  enemySlots.forEach(slot=>{
    if (!slot||!slot.participantId) return;
    const participant=getBattleEnemyParticipantById(slot.participantId);
    if (!participant) return;
    const mayPreserve=participant.id===preservedEnemyId&&options.preserveExistingEnemyPower===true;
    const calculated=calculateBattlePower(participant,"standard");
    const maximum=mayPreserve&&preservedMaximum>0?preservedMaximum:calculated;
    const current=mayPreserve&&preservedCurrent!==null?Math.min(maximum,preservedCurrent):maximum;
    setBattleRemainingPLRecord("enemy",participant.id,maximum,current);
  });

  syncBattleActiveEnemyFromDeployment();
  syncBattleEnemyPowerCompatibilityProjection();
  return runtime.remainingPL;
}

// =========================================================
// BRICK 402 — TEMPORARY BATTLE-CAPACITY OVERLAYS
// BRICK 403 — DAMAGE-BEARING CAPACITY ORDERING
// BRICK 404 — SOURCE-OWNED OVERLAY REMOVAL
// =========================================================

function getBattleTemporaryCapacityLayers(side, participantId) {
  const runtime=ensureBattleRuntimeState();
  if (!runtime.temporaryCapacity[side]) return [];
  if (!Array.isArray(runtime.temporaryCapacity[side][participantId])) runtime.temporaryCapacity[side][participantId]=[];
  return runtime.temporaryCapacity[side][participantId];
}

function addBattleTemporaryCapacityOverlay(side, participantId, amount, sourceProjectionKey) {
  const safe=Math.max(0,Math.round(Number(amount)||0));
  if (safe<=0) return null;
  const layers=getBattleTemporaryCapacityLayers(side,participantId);
  const overlayId=createBattleRuntimeRecordId("capacity");
  const layer={overlayId,sourceProjectionKey:sourceProjectionKey||null,maximum:safe,current:safe,createdAt:Date.now()};
  layers.push(layer);
  return layer;
}

function removeBattleTemporaryCapacityByProjection(sourceProjectionKey, side, participantId) {
  const layers=getBattleTemporaryCapacityLayers(side,participantId);
  const removed=[];
  const kept=[];
  layers.forEach(layer => (layer && layer.sourceProjectionKey===sourceProjectionKey ? removed : kept).push(layer));
  ensureBattleRuntimeState().temporaryCapacity[side][participantId]=kept;
  return removed;
}

function getBattleTemporaryCapacity(side, participantId) {
  return getBattleTemporaryCapacityLayers(side,participantId).reduce((sum,layer)=>sum+Math.max(0,Number(layer.current)||0),0);
}

function getBattleDamageBearingCapacity(side, participantId) {
  return getBattleTemporaryCapacity(side,participantId)+getBattleRemainingPL(side,participantId);
}

function absorbBattleDamageBearingCapacity(side, participantId, finalPLDamage) {
  const incoming=Math.max(0,Math.round(Number(finalPLDamage)||0));
  const underlyingBefore=getBattleRemainingPL(side,participantId);
  const tempBefore=getBattleTemporaryCapacity(side,participantId);
  let remaining=incoming;
  let temporaryAbsorbed=0;
  const layers=getBattleTemporaryCapacityLayers(side,participantId);
  for (const layer of layers) {
    if (remaining<=0) break;
    const available=Math.max(0,Number(layer.current)||0);
    const used=Math.min(available,remaining);
    layer.current=available-used;
    remaining-=used;
    temporaryAbsorbed+=used;
  }
  ensureBattleRuntimeState().temporaryCapacity[side][participantId]=layers.filter(layer=>Number(layer.current)>0);
  const underlyingAbsorbed=Math.min(underlyingBefore,remaining);
  const underlyingAfter=underlyingBefore-underlyingAbsorbed;
  setBattleRemainingPL(side,participantId,underlyingAfter);
  remaining-=underlyingAbsorbed;
  const absorbedPL=temporaryAbsorbed+underlyingAbsorbed;
  return {
    incomingFinalPLDamage:incoming, absorbedPL, residualAttackPL:Math.max(0,incoming-absorbedPL),
    temporaryCapacityBefore:tempBefore, temporaryCapacityAbsorbed:temporaryAbsorbed,
    temporaryCapacityAfter:getBattleTemporaryCapacity(side,participantId),
    underlyingBattlePLBefore:underlyingBefore, underlyingBattlePLAbsorbed:underlyingAbsorbed,
    underlyingBattlePLAfter:underlyingAfter,
    totalCapacityBefore:tempBefore+underlyingBefore,
    totalCapacityAfter:getBattleTemporaryCapacity(side,participantId)+underlyingAfter
  };
}

function calculateExcessDamageResidual(finalPLDamage, absorbedPL) {
  return Math.max(0,Math.round(Number(finalPLDamage)||0)-Math.max(0,Math.round(Number(absorbedPL)||0)));
}



// =========================================================
// BRICK 303 — SOURCE/TARGET TRANSIENT INTERACTION STATE
// =========================================================
//
// Example:
//
// Izuno
//   → Rogue Scout
//   → feinted_opening
//
// The state belongs to the relationship between those
// participants during this Battle.
//
// It is NOT a target Stat modifier.
//
// =========================================================

function createBattleParticipantRef(
  side,
  participantId
) {


  if (
    !side ||
    !participantId
  ) {

    return null;
  }


  return {

    side:
      side,

    participantId:
      participantId

  };
}


function addBattleTransientState(
  definition
) {


  const runtime =
    ensureBattleRuntimeState();


  if (
    !definition ||
    !definition.stateKey
  ) {


    console.log(
      "Battle transient state requires stateKey."
    );


    return null;
  }


  const sourceRef =
    createBattleParticipantRef(
      definition.sourceSide,
      definition.sourceParticipantId
    );


  const targetRef =
    createBattleParticipantRef(
      definition.targetSide,
      definition.targetParticipantId
    );


  /*
     Source-scoped is the safe default.

     Authored state may explicitly supply other authorised
     consumers when another participant should be allowed
     to consume the interaction.
  */
  let authorisedConsumers =
    Array.isArray(
      definition.authorisedConsumers
    )

      ? definition.authorisedConsumers
          .filter(
            ref =>
              ref &&
              ref.side &&
              ref.participantId
          )
          .map(
            ref => ({

              side:
                ref.side,

              participantId:
                ref.participantId

            })
          )

      : [];


  if (
    authorisedConsumers.length ===
      0 &&
    sourceRef
  ) {


    authorisedConsumers = [
      {
        ...sourceRef
      }
    ];
  }


  const state = {

    stateId:
      createBattleRuntimeRecordId(
        "state"
      ),


    stateKey:
      definition.stateKey,


    sourceRef:
      sourceRef,


    targetRef:
      targetRef,


    ownerRef:
      definition.ownerRef
        ? cloneBattleRuntimeValue(
            definition.ownerRef
          )
        : null,


    authorisedConsumers:
      authorisedConsumers,


    data:
      definition.data
        ? cloneBattleRuntimeValue(
            definition.data
          )
        : {},


    createdActionSequence:
      runtime.actionSequence,


    createdAt:
      Date.now()

  };


  runtime.transientStates.push(
    state
  );


  return state;
}


function findBattleTransientState(
  criteria
) {


  const runtime =
    ensureBattleRuntimeState();


  if (
    !criteria
  ) {

    return null;
  }


  return (
    runtime.transientStates.find(
      state => {


        if (
          criteria.stateId &&
          state.stateId !==
            criteria.stateId
        ) {

          return false;
        }


        if (
          criteria.stateKey &&
          state.stateKey !==
            criteria.stateKey
        ) {

          return false;
        }


        if (
          criteria.sourceSide &&
          (
            !state.sourceRef ||
            state.sourceRef.side !==
              criteria.sourceSide
          )
        ) {

          return false;
        }


        if (
          criteria.sourceParticipantId &&
          (
            !state.sourceRef ||
            state.sourceRef
              .participantId !==
              criteria.sourceParticipantId
          )
        ) {

          return false;
        }


        if (
          criteria.targetSide &&
          (
            !state.targetRef ||
            state.targetRef.side !==
              criteria.targetSide
          )
        ) {

          return false;
        }


        if (
          criteria.targetParticipantId &&
          (
            !state.targetRef ||
            state.targetRef
              .participantId !==
              criteria.targetParticipantId
          )
        ) {

          return false;
        }


        return true;
      }
    ) ||
    null
  );
}


function canBattleParticipantConsumeTransientState(
  state,
  side,
  participantId
) {


  if (
    !state ||
    !side ||
    !participantId
  ) {

    return false;
  }


  const consumers =
    Array.isArray(
      state.authorisedConsumers
    )

      ? state.authorisedConsumers

      : [];


  return consumers.some(
    consumer =>
      consumer.side ===
        side &&
      consumer.participantId ===
        participantId
  );
}


function consumeBattleTransientState(
  stateId,
  consumerSide,
  consumerParticipantId
) {


  const runtime =
    ensureBattleRuntimeState();


  const index =
    runtime.transientStates
      .findIndex(
        state =>
          state.stateId ===
            stateId
      );


  if (
    index < 0
  ) {

    return null;
  }


  const state =
    runtime.transientStates[
      index
    ];


  if (
    !canBattleParticipantConsumeTransientState(
      state,
      consumerSide,
      consumerParticipantId
    )
  ) {


    return null;
  }


  runtime.transientStates.splice(
    index,
    1
  );


  return state;
}


function removeBattleTransientState(
  stateId
) {


  const runtime =
    ensureBattleRuntimeState();


  const index =
    runtime.transientStates
      .findIndex(
        state =>
          state.stateId ===
            stateId
      );


  if (
    index < 0
  ) {

    return false;
  }


  runtime.transientStates.splice(
    index,
    1
  );


  return true;
}

// =========================================================
// =========================================================
// BRICK 465 — CHARGED TRANSIENT-STATE CONSUMPTION
// BRICK 466 — TRANSIENT ACTION-OPPORTUNITY DURATION
// BRICK 690 — SOURCE-ACTION-OPPORTUNITY EXPIRY
// =========================================================
function getBattleTransientStatesForParticipant(side,participantId) {
  return ensureBattleRuntimeState().transientStates.filter(state=>state&&state.targetRef&&state.targetRef.side===side&&state.targetRef.participantId===participantId);
}

function consumeBattleTransientStateCharge(stateId,side,participantId,amount=1) {
  const state=findBattleTransientState({stateId});
  if (!state||!canBattleParticipantConsumeTransientState(state,side,participantId)) return {success:false,reason:"state_not_consumable"};
  const current=Math.max(0,Math.floor(Number(state.data&&state.data.remainingCharges)||0));
  const used=Math.max(1,Math.floor(Number(amount)||1));
  if (current<=0) return {success:false,reason:"no_state_charges"};
  state.data.remainingCharges=Math.max(0,current-used);
  if (state.data.remainingCharges<=0) removeBattleTransientState(stateId);
  return {success:true,stateId,remainingCharges:state.data.remainingCharges};
}

function advanceBattleTransientStateActionOpportunity(side,participantId,actionId,reason) {
  const runtime=ensureBattleRuntimeState();
  const states=[...getBattleTransientStatesForParticipant(side,participantId)];
  const expired=[];
  states.forEach(state=>{
    if (!state.data||!Number.isFinite(Number(state.data.remainingActionOpportunities))) return;
    if (state.data.activationActionId&&state.data.activationActionId===actionId) return;
    if (Number(state.createdActionSequence)===Number(runtime.actionSequence)) return;
    state.data.remainingActionOpportunities=Math.max(0,Number(state.data.remainingActionOpportunities)-1);
    recordBattleEvidence({eventType:"transient_state_duration_advanced",actionId:actionId||null,actorRef:createBattleParticipantRef(side,participantId),stateRefs:[state.stateId],data:{stateKey:state.stateKey,remainingActionOpportunities:state.data.remainingActionOpportunities,reason:reason||null}});
    if (state.data.remainingActionOpportunities<=0) { removeBattleTransientState(state.stateId); expired.push(state.stateId); }
  });

  // Source-owned setup can expire on the source's future action opportunity even
  // when the state is scoped to an enemy target (e.g. Transformation Feint).
  const sourceStates=[...runtime.transientStates].filter(state=>
    state&&state.sourceRef&&state.sourceRef.side===side&&state.sourceRef.participantId===participantId&&
    state.data&&Number.isFinite(Number(state.data.remainingSourceActionOpportunities))
  );
  sourceStates.forEach(state=>{
    if (Number(state.createdActionSequence)===Number(runtime.actionSequence)) return;
    state.data.remainingSourceActionOpportunities=Math.max(0,Number(state.data.remainingSourceActionOpportunities)-1);
    recordBattleEvidence({eventType:"transient_state_source_duration_advanced",actionId:actionId||null,actorRef:createBattleParticipantRef(side,participantId),stateRefs:[state.stateId],data:{stateKey:state.stateKey,remainingSourceActionOpportunities:state.data.remainingSourceActionOpportunities,reason:reason||null}});
    if (state.data.remainingSourceActionOpportunities<=0) {
      removeBattleTransientState(state.stateId);
      if (!expired.includes(state.stateId)) expired.push(state.stateId);
    }
  });
  return expired;
}

function upsertBattleParticipantCounterState(side,participantId,stateKey,delta=1,ownerRef=null) {
  let state=findBattleTransientState({stateKey,targetSide:side,targetParticipantId:participantId});
  if (!state) state=addBattleTransientState({stateKey,sourceSide:side,sourceParticipantId:participantId,targetSide:side,targetParticipantId:participantId,ownerRef,data:{value:0}});
  if (!state) return null;
  state.data.value=Math.max(0,(Number(state.data.value)||0)+(Number(delta)||0));
  return state;
}

function getBattleParticipantCounterValue(side,participantId,stateKey) {
  const state=findBattleTransientState({stateKey,targetSide:side,targetParticipantId:participantId});
  return state&&state.data?Math.max(0,Number(state.data.value)||0):0;
}

// BRICK 303 — TEMPORARY BATTLE CONDITIONS
// BRICK 331 — CONDITION SEMANTICS
// BRICK 332 — NEXT ACTION OPPORTUNITY LIFECYCLE
// BRICK 343 — AUTHORED CONDITION-CURE COMPATIBILITY
// BRICK 567 — CONDITION ESTABLISHMENT / REFRESH / REMOVAL PROVENANCE
// =========================================================
//
// Conditions may restrict action classes and/or explicit
// action semantic traits.
//
// They do NOT rewrite Character Stats.
//
// sealed_chakra_flow therefore blocks chakra expression,
// not every positive runtime state.
//
// =========================================================

// =========================================================
// BRICK 444 — GENERIC ALPHA CONDITION CATALOG
// BRICK 446 — AUTHORED CONDITION TICK METADATA
// =========================================================
const GENERIC_ALPHA_BATTLE_CONDITION_CATALOG = {
  poisoned:{
    conditionKey:"poisoned",
    conditionType:"poison",
    tickDamage:2,
    maximumTicks:3,
    tickPhase:"end_of_action_opportunity",
    bypassStamina:true,
    reapplication:"refresh",
    stackMode:"single_stream",
    compatibleCureItemIds:["standard_antidote"]
  },
  burning:{
    conditionKey:"burning",
    conditionType:"burning",
    tickDamage:2,
    maximumTicks:2,
    tickPhase:"start_of_action_opportunity",
    bypassStamina:true,
    reapplication:"refresh",
    stackMode:"single_stream",
    compatibleCureItemIds:["burn_treatment"]
  }
};

function getGenericAlphaBattleConditionDefinition(conditionKey) {
  return GENERIC_ALPHA_BATTLE_CONDITION_CATALOG[conditionKey]||null;
}

function normalizeBattleConditionSourceRefs(sourceRefs=[]) {
  return Array.isArray(sourceRefs)
    ? sourceRefs.filter(ref=>ref&&typeof ref==="object").map(ref=>cloneBattleRuntimeValue(ref)).filter(Boolean)
    : [];
}

function createBattleConditionEstablishment(definition,runtime) {
  const sourceRef=createBattleParticipantRef(definition.sourceSide,definition.sourceParticipantId);
  const ownerRef=definition.ownerRef?cloneBattleRuntimeValue(definition.ownerRef):null;
  const sourceRefs=normalizeBattleConditionSourceRefs(definition.sourceRefs);
  if (sourceRef&&!sourceRefs.some(ref=>ref&&ref.type==="participant"&&ref.side===sourceRef.side&&ref.participantId===sourceRef.participantId)) {
    sourceRefs.push({type:"participant",side:sourceRef.side,participantId:sourceRef.participantId,role:"establishing_actor"});
  }
  if (ownerRef&&ownerRef.id&&!sourceRefs.some(ref=>ref&&ref.type===ownerRef.type&&ref.id===ownerRef.id)) {
    sourceRefs.push({...ownerRef,role:ownerRef.role||"state_owner"});
  }
  if (definition.sourceSkillId&&!sourceRefs.some(ref=>ref&&ref.type==="skill"&&ref.id===definition.sourceSkillId)) {
    sourceRefs.push({type:"skill",id:definition.sourceSkillId,role:"establishing_action"});
  }
  return {
    sourceRef:sourceRef?cloneBattleRuntimeValue(sourceRef):null,
    ownerRef,
    sourceRefs,
    actionId:definition.actionId||null,
    skillId:definition.sourceSkillId||null,
    itemId:definition.sourceItemId||null,
    actionSequence:Number(runtime.actionSequence)||0,
    createdAt:Date.now()
  };
}

function getBattleConditionEstablishment(condition) {
  if (!condition) return null;
  if (condition.establishment&&typeof condition.establishment==="object") return condition.establishment;
  return {
    sourceRef:condition.sourceRef?cloneBattleRuntimeValue(condition.sourceRef):null,
    ownerRef:condition.ownerRef?cloneBattleRuntimeValue(condition.ownerRef):null,
    sourceRefs:[],actionId:null,skillId:null,itemId:null,
    actionSequence:Number(condition.createdActionSequence)||0,
    createdAt:condition.createdAt||null
  };
}

function getBattleConditionEstablishmentSourceRef(condition) {
  const establishment=getBattleConditionEstablishment(condition);
  return establishment&&establishment.sourceRef?cloneBattleRuntimeValue(establishment.sourceRef):null;
}

function getBattleConditionCausalSourceRefs(condition,extraRefs=[]) {
  const establishment=getBattleConditionEstablishment(condition);
  const refs=establishment&&Array.isArray(establishment.sourceRefs)?cloneBattleRuntimeValue(establishment.sourceRefs):[];
  const combined=[...(Array.isArray(refs)?refs:[]),...(Array.isArray(extraRefs)?extraRefs:[])];
  const seen=new Set();
  return combined.filter(ref=>{
    if (!ref||typeof ref!=="object") return false;
    const key=JSON.stringify([ref.type||null,ref.id||null,ref.side||null,ref.participantId||null,ref.role||null]);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function upsertBattleCondition(definition) {
  if (!definition||!definition.conditionKey||!definition.targetSide||!definition.targetParticipantId) return {condition:null,refreshed:false};
  const runtime=ensureBattleRuntimeState();
  const existing=runtime.conditions.find(condition=>condition&&condition.conditionKey===definition.conditionKey&&condition.targetRef&&condition.targetRef.side===definition.targetSide&&condition.targetRef.participantId===definition.targetParticipantId);
  if (existing&&definition.reapplication==="refresh") {
    const refresh=createBattleConditionEstablishment(definition,runtime);
    existing.compatibleCureItemIds=Array.isArray(definition.compatibleCureItemIds)?[...new Set(definition.compatibleCureItemIds.filter(Boolean))]:existing.compatibleCureItemIds;
    existing.blockedActionClasses=Array.isArray(definition.blockedActionClasses)?[...new Set(definition.blockedActionClasses.filter(Boolean))]:existing.blockedActionClasses;
    existing.blockedActionTraits=Array.isArray(definition.blockedActionTraits)?[...new Set(definition.blockedActionTraits.filter(Boolean))]:existing.blockedActionTraits;
    existing.data={...(existing.data||{}),...(definition.data?cloneBattleRuntimeValue(definition.data):{})};
    if (!Array.isArray(existing.refreshHistory)) existing.refreshHistory=[];
    existing.refreshHistory.push(refresh);
    existing.lastRefresh=refresh;
    existing.lastRefreshActionSequence=runtime.actionSequence;
    existing.refreshedAt=Date.now();
    return {condition:existing,refreshed:true,refresh};
  }
  return {condition:addBattleCondition(definition),refreshed:false};
}

function applyGenericAlphaBattleCondition(conditionKey,definition={}) {
  const authored=getGenericAlphaBattleConditionDefinition(conditionKey);
  if (!authored) return {condition:null,refreshed:false,reason:"generic_condition_missing"};
  return upsertBattleCondition({
    conditionKey:authored.conditionKey,
    conditionType:authored.conditionType,
    compatibleCureItemIds:authored.compatibleCureItemIds,
    sourceSide:definition.sourceSide,
    sourceParticipantId:definition.sourceParticipantId,
    sourceRefs:definition.sourceRefs||[],
    sourceSkillId:definition.sourceSkillId||null,
    sourceItemId:definition.sourceItemId||null,
    actionId:definition.actionId||null,
    targetSide:definition.targetSide,
    targetParticipantId:definition.targetParticipantId,
    ownerRef:definition.ownerRef||null,
    blockedActionClasses:definition.blockedActionClasses||[],
    blockedActionTraits:definition.blockedActionTraits||[],
    reapplication:authored.reapplication,
    data:{
      ...(definition.data||{}),
      tickDamage:authored.tickDamage,
      maximumTicks:authored.maximumTicks,
      remainingTicks:authored.maximumTicks,
      tickPhase:authored.tickPhase,
      bypassStamina:authored.bypassStamina,
      stackMode:authored.stackMode,
      reapplication:authored.reapplication
    }
  });
}

function addBattleCondition(definition) {
  const runtime=ensureBattleRuntimeState();
  if (!definition||!definition.conditionKey||!definition.targetSide||!definition.targetParticipantId) {
    console.log("Battle Condition missing required identity.");
    return null;
  }
  const establishment=createBattleConditionEstablishment(definition,runtime);
  const condition={
    conditionId:createBattleRuntimeRecordId("condition"),
    conditionKey:definition.conditionKey,
    conditionType:typeof definition.conditionType==="string"?definition.conditionType:null,
    compatibleCureItemIds:Array.isArray(definition.compatibleCureItemIds)
      ? [...new Set(definition.compatibleCureItemIds.filter(itemId=>typeof itemId==="string"&&itemId.length>0))]
      : [],
    sourceRef:establishment.sourceRef?cloneBattleRuntimeValue(establishment.sourceRef):null,
    targetRef:createBattleParticipantRef(definition.targetSide,definition.targetParticipantId),
    ownerRef:establishment.ownerRef?cloneBattleRuntimeValue(establishment.ownerRef):null,
    establishment,
    refreshHistory:[],
    lastRefresh:null,
    blockedActionClasses:Array.isArray(definition.blockedActionClasses)
      ? [...new Set(definition.blockedActionClasses.filter(value=>typeof value==="string"&&value.length>0))]
      : [],
    blockedActionTraits:Array.isArray(definition.blockedActionTraits)
      ? [...new Set(definition.blockedActionTraits.filter(value=>typeof value==="string"&&value.length>0))]
      : [],
    data:definition.data?cloneBattleRuntimeValue(definition.data):{},
    createdActionSequence:runtime.actionSequence,
    createdAt:establishment.createdAt
  };
  runtime.conditions.push(condition);
  return condition;
}

function getBattleBlockingConditions(side,participantId,actionClass,actionTraits=[]) {
  const runtime=ensureBattleRuntimeState();
  if (!side||!participantId||!actionClass) return [];
  const traits=Array.isArray(actionTraits)?actionTraits:[];
  return runtime.conditions.filter(condition=>{
    if (!condition.targetRef||condition.targetRef.side!==side||condition.targetRef.participantId!==participantId) return false;
    const universalStun=condition.conditionKey==="stun"||condition.conditionType==="stun";
    const classBlocked=Array.isArray(condition.blockedActionClasses)&&condition.blockedActionClasses.includes(actionClass);
    const traitBlocked=Array.isArray(condition.blockedActionTraits)&&condition.blockedActionTraits.some(blockedTrait=>traits.includes(blockedTrait));
    return universalStun||classBlocked||traitBlocked;
  });
}

function removeBattleCondition(conditionId,context={}) {
  const runtime=ensureBattleRuntimeState();
  const index=runtime.conditions.findIndex(condition=>condition&&condition.conditionId===conditionId);
  if (index<0) return false;
  const condition=runtime.conditions[index];
  const targetRef=condition.targetRef?cloneBattleRuntimeValue(condition.targetRef):null;
  const removerRef=context.removerRef?cloneBattleRuntimeValue(context.removerRef):null;
  const removalSourceRefs=[];
  if (Array.isArray(context.sourceRefs)) removalSourceRefs.push(...context.sourceRefs);
  if (removerRef) removalSourceRefs.push({type:"participant",side:removerRef.side,participantId:removerRef.participantId,role:"removal_actor"});
  if (context.itemId) removalSourceRefs.push({type:"item",id:context.itemId,role:"removal_instrument"});
  if (context.skillId) removalSourceRefs.push({type:"skill",id:context.skillId,role:"removal_action"});
  const sourceRefs=getBattleConditionCausalSourceRefs(condition,removalSourceRefs);
  if (context.recordEvidence!==false) {
    recordBattleEvidence({
      eventType:"condition_removed",
      actionId:context.actionId||null,
      actorRef:removerRef,
      targetRef,
      skillId:context.skillId||null,
      itemId:context.itemId||null,
      sourceRefs,
      conditionRefs:[condition.conditionId],
      data:{
        conditionKey:condition.conditionKey,
        removalReason:context.reason||"runtime_removal",
        cleanupOnly:context.cleanupOnly===true,
        historicalRollback:false,
        establishment:getBattleConditionEstablishment(condition)
      }
    });
  }
  runtime.conditions.splice(index,1);
  return true;
}

function getBattleParticipantConditions(side,participantId) {
  const runtime=ensureBattleRuntimeState();
  return runtime.conditions.filter(condition=>condition.targetRef&&condition.targetRef.side===side&&condition.targetRef.participantId===participantId);
}

// =========================================================
// BRICK 447 — ACTION-OPPORTUNITY TOKEN AUTHORITY
// =========================================================
function getBattleActionOpportunityIndex(side,participantId) {
  const state=ensureBattleRuntimeState().actionOpportunityState;
  if (!state.counters[side]) state.counters[side]={};
  if (!Number.isFinite(Number(state.counters[side][participantId]))) state.counters[side][participantId]=0;
  return Number(state.counters[side][participantId])||0;
}

function getBattleActionOpportunityToken(side,participantId) {
  return `${side}:${participantId}:${getBattleActionOpportunityIndex(side,participantId)}`;
}

function advanceBattleActionOpportunityIndex(side,participantId) {
  const state=ensureBattleRuntimeState().actionOpportunityState;
  const current=getBattleActionOpportunityIndex(side,participantId);
  state.counters[side][participantId]=current+1;
  return state.counters[side][participantId];
}

// =========================================================
// BRICK 450 — CONDITION DAMAGE BYPASSES STAMINA
// BRICK 451 — CONDITION TICK EVIDENCE
// BRICK 568 — PERSISTENT CONDITION SOURCE PROVENANCE
// =========================================================
function resolveBattleConditionTick(condition,phase,actionId=null) {
  if (!condition||!condition.targetRef||!condition.data) return null;
  const expectedPhase=condition.data.tickPhase||null;
  if (expectedPhase!==phase) return null;
  const remaining=Math.max(0,Math.floor(Number(condition.data.remainingTicks)||0));
  const baseTickDamage=Math.max(0,Math.round(Number(condition.data.tickDamage)||0));
  const pendingTickBonus=Math.max(0,Math.round(Number(condition.data.pendingTickBonus)||0));
  const perTickMaximum=Number.isFinite(Number(condition.data.perTickMaximum))?Math.max(0,Math.round(Number(condition.data.perTickMaximum))):null;
  const tickDamage=perTickMaximum===null?baseTickDamage:Math.min(perTickMaximum,baseTickDamage+pendingTickBonus);
  if (pendingTickBonus>0) condition.data.pendingTickBonus=0;
  if (remaining<=0||tickDamage<=0) return null;
  const side=condition.targetRef.side;
  const participantId=condition.targetRef.participantId;
  const beforeCapacity=getBattleDamageBearingCapacity(side,participantId);
  const absorption=absorbBattleDamageBearingCapacity(side,participantId,tickDamage);
  condition.data.remainingTicks=Math.max(0,remaining-1);
  const establishingRef=getBattleConditionEstablishmentSourceRef(condition);
  const evidence=recordBattleEvidence({
    eventType:"condition_tick_resolved",
    actionId,
    actorRef:establishingRef,
    targetRef:createBattleParticipantRef(side,participantId),
    sourceRefs:getBattleConditionCausalSourceRefs(condition,[{type:"condition",id:condition.conditionId,role:"persistent_state"}]),
    conditionRefs:[condition.conditionId],
    data:{
      conditionKey:condition.conditionKey,phase,tickDamage,
      bypassStamina:condition.data.bypassStamina===true,
      remainingTicks:condition.data.remainingTicks,beforeCapacity,absorption,
      establishment:getBattleConditionEstablishment(condition),
      persistentOccurrenceDoesNotReplaceEstablisher:true
    }
  });
  let zeroResult=null;
  if (absorption.totalCapacityAfter<=0) zeroResult=handleBattleParticipantAtZeroPL(side,participantId,null,{actionId});
  const expired=condition.data.remainingTicks<=0;
  if (expired) removeBattleCondition(condition.conditionId,{reason:"duration_exhausted",actionId,sourceRefs:[{type:"condition",id:condition.conditionId,role:"expired_state"}]});
  return {conditionId:condition.conditionId,conditionKey:condition.conditionKey,phase,tickDamage,remainingTicks:condition.data.remainingTicks,absorption,evidence,expired,zeroResult};
}

// =========================================================
// BRICK 448 — BURNING START-OF-OPPORTUNITY TICK
// BRICK 453 — BURN-TREATMENT TIMING BOUNDARY
// =========================================================
function resolveBattleStartOfActionOpportunityEffects(side,participantId,actionId=null) {
  const runtime=ensureBattleRuntimeState();
  const token=getBattleActionOpportunityToken(side,participantId);
  if (runtime.actionOpportunityState.startedTokens[token]) return {token,idempotent:true,ticks:[],amaterasuTicks:[]};
  runtime.actionOpportunityState.startedTokens[token]=true;
  const ticks=[...getBattleParticipantConditions(side,participantId)]
    .filter(condition=>condition.data&&condition.data.tickPhase==="start_of_action_opportunity")
    .map(condition=>resolveBattleConditionTick(condition,"start_of_action_opportunity",actionId))
    .filter(Boolean);
  // BRICK 881 — Amaterasu is NOT generic Burning. Its exact source-scoped
  // persistent Attack PL resolves here with ordinary Stamina mitigation.
  const amaterasuTicks=resolveAlphaAmaterasuStartOpportunityTicks(side,participantId,actionId);
  return {token,idempotent:false,ticks,amaterasuTicks};
}

// =========================================================
// BRICK 449 — POISON END-OF-OPPORTUNITY TICK
// BRICK 452 — ANTIDOTE-BEFORE-END-TICK TIMING BRIDGE
// =========================================================
function resolveBattleEndOfActionOpportunityEffects(side,participantId,actionId=null) {
  const ticks=[...getBattleParticipantConditions(side,participantId)]
    .filter(condition=>condition.data&&condition.data.tickPhase==="end_of_action_opportunity")
    .map(condition=>resolveBattleConditionTick(condition,"end_of_action_opportunity",actionId))
    .filter(Boolean);
  return {ticks};
}

// =========================================================
// BRICK 454 — CONDITION PRESENTATION DESCRIPTOR
// BRICK 559 — CONDITION UI LIFECYCLE PROJECTION
// =========================================================
//
// Presentation derives from the existing Condition runtime.
// It does not decide admissibility, consume Conditions, or
// rewrite Character Stats.
//
// =========================================================

function formatBattleConditionPresentationLabel(
  conditionKey
) {

  if (
    typeof conditionKey !==
      "string" ||
    conditionKey.length ===
      0
  ) {

    return "CONDITION";
  }

  return conditionKey
    .split("_")
    .filter(Boolean)
    .map(
      part =>
        part.charAt(0)
          .toUpperCase() +
        part.slice(1)
    )
    .join(" ");
}


function getBattleConditionPresentationDescriptor(
  condition
) {

  if (
    !condition
  ) {

    return null;
  }

  const data =
    condition.data &&
    typeof condition.data ===
      "object"
      ? condition.data
      : {};

  const phase =
    data.tickPhase ||
    null;

  const expiry =
    data.expiry ||
    null;

  const blockedActionClasses =
    [
      ...(
        Array.isArray(
          condition.blockedActionClasses
        )
          ? condition.blockedActionClasses
          : []
      )
    ];

  const blockedActionTraits =
    [
      ...(
        Array.isArray(
          condition.blockedActionTraits
        )
          ? condition.blockedActionTraits
          : []
      )
    ];

  const remainingTicks =
    Number.isFinite(
      Number(
        data.remainingTicks
      )
    )
      ? Number(
          data.remainingTicks
        )
      : null;

  const conditionKey =
    condition.conditionKey ||
    "condition";

  return {

    conditionId:
      condition.conditionId,

    conditionKey:
      conditionKey,

    displayName:
      formatBattleConditionPresentationLabel(
        conditionKey
      ),

    conditionType:
      condition.conditionType,

    remainingTicks:
      remainingTicks,

    tickDamage:
      Number.isFinite(
        Number(
          data.tickDamage
        )
      )
        ? Number(
            data.tickDamage
          )
        : null,

    timing:
      phase ===
        "start_of_action_opportunity"
          ? "start_of_action"
          : phase ===
              "end_of_action_opportunity"
            ? "end_of_action"
            : null,

    expiry:
      expiry,

    expiresOnNextActionOpportunity:
      expiry ===
        "next_action_opportunity",

    invalidAttemptRetained:
      true,

    bypassStamina:
      data.bypassStamina ===
        true,

    blockedActionClasses:
      blockedActionClasses,

    blockedActionTraits:
      blockedActionTraits,

    blocksActions:
      blockedActionClasses.length >
        0 ||
      blockedActionTraits.length >
        0
  };
}


function getBattleConditionCardSealPresentation(
  condition
) {

  const descriptor =
    getBattleConditionPresentationDescriptor(
      condition
    );

  if (
    !descriptor ||
    descriptor.blocksActions !==
      true
  ) {

    return null;
  }

  if (
    descriptor.conditionKey ===
      "sealed_chakra_flow"
  ) {

    return {
      ...descriptor,
      sealHeadline:
        "CHAKRA FLOW",
      sealState:
        "SEALED"
    };
  }

  return {
    ...descriptor,
    sealHeadline:
      descriptor.displayName
        .toUpperCase(),
    sealState:
      "BLOCKED"
  };
}


function runBattleConditionUIPresentationDiagnostics() {

  const condition = {

    conditionId:
      "condition_ui_diagnostic",

    conditionKey:
      "sealed_chakra_flow",

    conditionType:
      "seal",

    blockedActionClasses: [
      "transformation_activation"
    ],

    blockedActionTraits: [
      "chakra_dependent_positive_self_enhancement"
    ],

    data: {
      expiry:
        "next_action_opportunity"
    }
  };

  const descriptor =
    getBattleConditionPresentationDescriptor(
      condition
    );

  const seal =
    getBattleConditionCardSealPresentation(
      condition
    );

  const result = {

    displayNameDerived:
      !!descriptor &&
      descriptor.displayName ===
        "Sealed Chakra Flow",

    nextRealActionLifecycle:
      !!descriptor &&
      descriptor.expiresOnNextActionOpportunity ===
        true,

    invalidAttemptRetained:
      !!descriptor &&
      descriptor.invalidAttemptRetained ===
        true,

    actionBlockingProjected:
      !!descriptor &&
      descriptor.blocksActions ===
        true,

    blockedClassesPreserved:
      !!descriptor &&
      descriptor.blockedActionClasses
        .includes(
          "transformation_activation"
        ),

    blockedTraitsPreserved:
      !!descriptor &&
      descriptor.blockedActionTraits
        .includes(
          "chakra_dependent_positive_self_enhancement"
        ),

    sealedCardPresentation:
      !!seal &&
      seal.sealHeadline ===
        "CHAKRA FLOW" &&
      seal.sealState ===
        "SEALED"
  };

  result.pass =
    Object.values(
      result
    )
      .every(
        value =>
          value ===
            true
      );

  console.table(
    result
  );

  return result;
}

// =========================================================
// BRICK 455 — CONDITION LIFECYCLE DIAGNOSTIC
// =========================================================
function runGenericConditionDefinitionDiagnostics() {
  const poison=getGenericAlphaBattleConditionDefinition("poisoned");
  const burning=getGenericAlphaBattleConditionDefinition("burning");
  const result={
    poisonPilot:!!poison&&poison.tickDamage===2&&poison.maximumTicks===3&&poison.tickPhase==="end_of_action_opportunity"&&poison.bypassStamina===true,
    burningPilot:!!burning&&burning.tickDamage===2&&burning.maximumTicks===2&&burning.tickPhase==="start_of_action_opportunity"&&burning.bypassStamina===true,
    poisonRefresh:!!poison&&poison.reapplication==="refresh"&&poison.stackMode==="single_stream",
    burningRefresh:!!burning&&burning.reapplication==="refresh"&&burning.stackMode==="single_stream",
    curesAuthored:poison.compatibleCureItemIds.includes("standard_antidote")&&burning.compatibleCureItemIds.includes("burn_treatment")
  };
  result.pass=Object.values(result).every(value=>value===true);
  return result;
}

// =========================================================
// BRICK 405 — ACTION-OPPORTUNITY PACKAGE DURATION
// BRICK 569 — CLEANUP / BARYON LIFECYCLE MIGRATION
// BRICK 634 — SOVEREIGN OVERLOAD OPPORTUNITY COST
// =========================================================

function consumeBattleEffectiveStateActionOpportunity(side, participantId, actionId, reason) {
  const projections=[...getBattleParticipantEffectiveStateProjections(side,participantId)];
  const expired=[];
  projections.forEach(projection => {
    if (projection.remainingActionOpportunities === null || projection.remainingActionOpportunities === undefined) return;
    if (!Number.isFinite(Number(projection.remainingActionOpportunities))) return;
    if (projection.activationActionId && projection.activationActionId===actionId) return;
    projection.remainingActionOpportunities=Math.max(0,Number(projection.remainingActionOpportunities)-1);
    recordBattleEvidence({eventType:"effective_state_duration_advanced",actionId:actionId||null,
      actorRef:createBattleParticipantRef(side,participantId),sourceRefs:[{type:"source",id:projection.sourceId}],
      data:{projectionKey:projection.projectionKey,remainingActionOpportunities:projection.remainingActionOpportunities,reason:reason||null}});
    if (projection.remainingActionOpportunities<=0) {
      expired.push(...removeBattleEffectiveStateProjection(projection.projectionKey,side,participantId,"action_opportunity_duration_expired"));
      if (side==="player" && getBattleDamageBearingCapacity(side,participantId)<=0 && getBattleActiveParticipantId(side)===participantId) {
        handleBattleParticipantAtZeroPL(side,participantId,null,{actionId:actionId||null});
      }
    }
  });
  return expired;
}

function consumeDedicatedRepresentationLifecycleActionOpportunity(side,participantId,actionId) {
  if (side!=="player") return null;
  const participant=getBattleParticipantByIdentity(side,participantId);
  if (!participant||getCharacterRegistryId(participant)!=="baryon_mode") return null;
  const state=findBattleTransientState({stateKey:"baryon_mode_lifecycle",targetSide:side,targetParticipantId:participantId})||ensureDedicatedRepresentationLifecycleState(participant);
  if (!state||!state.data) return {advanced:false,reason:"baryon_lifecycle_state_missing"};
  const before=Math.max(0,Math.floor(Number(state.data.remainingBaryonActionOpportunities)||0));
  if (before<=0) return {advanced:false,reason:"baryon_lifecycle_already_collapsed",stateId:state.stateId};
  const after=Math.max(0,before-1);
  state.data.remainingBaryonActionOpportunities=after;
  recordBattleEvidence({
    eventType:"representation_lifecycle_advanced",actionId,
    actorRef:createBattleParticipantRef(side,participantId),
    sourceRefs:[{type:"character_registry",id:"baryon_mode",role:"embodied_representation"}],
    stateRefs:[state.stateId],
    data:{representationId:"baryon_mode",before,after,maximum:Number(state.data.maximumActionOpportunities)||5,battlePLCost:false,injuryCost:false,selfDamage:false}
  });
  if (after>0) return {advanced:true,collapsed:false,before,after,stateId:state.stateId};
  state.data.collapsed=true;
  state.data.collapsedAtActionId=actionId||null;
  recordBattleEvidence({
    eventType:"representation_lifecycle_collapsed",actionId,
    actorRef:createBattleParticipantRef(side,participantId),
    sourceRefs:[{type:"character_registry",id:"baryon_mode",role:"embodied_representation"}],
    stateRefs:[state.stateId],
    data:{representationId:"baryon_mode",reason:"five_action_opportunities_consumed",representationEnds:true,battlePLDamage:0,selfDamage:false,injury:false}
  });
  removeBattleTransientState(state.stateId);
  if (getBattleActiveParticipantId("player")===participantId&&canWithdrawActiveBattleFighter()) {
    const withdrawal=withdrawActiveBattleFighter({reason:"baryon_lifecycle_collapsed"});
    return {advanced:true,collapsed:true,before,after,stateId:state.stateId,withdrawal};
  }
  return {advanced:true,collapsed:true,before,after,stateId:state.stateId,terminationRequired:true,reason:"no_deployment_successor"};
}

