// =========================================================
function getNarutoV2InstabilityState(actor) {
  if (!actor||getCharacterRegistryId(actor)!=="naruto_v2") return null;
  return findBattleTransientState({stateKey:"naruto_v2_instability",targetSide:"player",targetParticipantId:actor.id})||ensureDedicatedRepresentationLifecycleState(actor);
}
function advanceNarutoV2InstabilityAfterCompletedSkill(actor,skill,envelope,resolution,options={}) {
  if (!actor||!skill||!resolution||resolution.resolved!==true||getCharacterRegistryId(actor)!=="naruto_v2") return null;
  const state=getNarutoV2InstabilityState(actor); if(!state||!state.data)return null;
  const order=["stable","strained","breached"]; const before=order.includes(state.data.instabilityState)?state.data.instabilityState:"stable";
  let shouldAdvance=!!(skill.instability&&skill.instability.advanceOnCompleted===true);
  if(skill.instability&&skill.instability.advanceWhenState===before) shouldAdvance=skill.instability.requiresAuthoredEscalationConfirmation===true?options.confirmInstabilityEscalation===true:true;
  if(!shouldAdvance){if(skill.instability&&skill.instability.advanceWhenState===before)recordBattleEvidence({eventType:"naruto_v2_instability_escalation_available",actionId:envelope.actionId,actorRef:envelope.actorRef,skillId:skill.id,stateRefs:[state.stateId],data:{before,requiresAuthoredEscalationConfirmation:true,hiddenStatCreated:false,automaticBattlePLDamage:0}});return {advanced:false,before,after:before,stateId:state.stateId};}
  const index=Math.max(0,order.indexOf(before)); const after=order[Math.min(order.length-1,index+Math.max(1,Number(skill.instability&&skill.instability.steps)||1))];
  state.data.instabilityState=after;
  recordBattleEvidence({eventType:"naruto_v2_instability_advanced",actionId:envelope.actionId,actorRef:envelope.actorRef,skillId:skill.id,stateRefs:[state.stateId],data:{before,after,categorical:true,hiddenStatCreated:false,battlePLDamage:0,injury:false,staminaLoss:0,forcedTransformation:false}});
  return {advanced:after!==before,before,after,stateId:state.stateId};
}
function recordBaryonContactErosionOccurrence(definition={}) {
  const actorSide=definition.actorSide||"player",actorParticipantId=definition.actorParticipantId||null,targetSide=definition.targetSide||null,targetParticipantId=definition.targetParticipantId||null;
  if(!actorParticipantId||!targetSide||!targetParticipantId)return {success:false,reason:"baryon_participant_refs_missing"};
  const actor=getBattleParticipantByIdentity(actorSide,actorParticipantId); if(!actor||getCharacterRegistryId(actor)!=="baryon_mode")return {success:false,reason:"actor_not_baryon_representation"};
  if(definition.qualifyingContactConfirmed!==true)return {success:false,reason:"qualifying_baryon_contact_not_confirmed"};
  const opportunityIndex=getBattleActionOpportunityIndex(actorSide,actorParticipantId),runtime=ensureBattleRuntimeState();
  const duplicate=runtime.evidence.find(record=>record&&record.eventType==="baryon_contact_erosion"&&record.actorRef&&record.actorRef.side===actorSide&&record.actorRef.participantId===actorParticipantId&&record.targetRef&&record.targetRef.side===targetSide&&record.targetRef.participantId===targetParticipantId&&record.data&&Number(record.data.actorOpportunityIndex)===Number(opportunityIndex));
  if(duplicate)return {success:true,idempotent:true,evidence:duplicate};
  const evidence=recordBattleEvidence({eventType:"baryon_contact_erosion",actionId:definition.actionId||null,actorRef:createBattleParticipantRef(actorSide,actorParticipantId),targetRef:createBattleParticipantRef(targetSide,targetParticipantId),skillId:definition.skillId||null,sourceRefs:[{type:"character_registry",id:"baryon_mode",role:"active_representation"},...(definition.skillId?[{type:"skill",id:definition.skillId,role:"qualifying_contact_action"}]:[])],data:{actorOpportunityIndex:opportunityIndex,qualifyingContactConfirmed:true,attackPLContribution:0,battlePLDamage:0,poison:false,burning:false,injury:false,lifespanStatCreated:false,permanentStatReduction:false,causalConsequenceEvidenceOnly:true}});
  return evidence?{success:true,evidence}:{success:false,reason:"baryon_contact_erosion_evidence_commit_failed"};
}

// =========================================================
// BRICK 634 — KURAMA SOVEREIGN OVERLOAD OPPORTUNITY COST
// =========================================================
function applyKuramaSovereignOverloadOpportunityCost(side,participantId,actionId) {
  if (side!=="player") return null;
  const actor=getBattleParticipantByIdentity(side,participantId);
  if (!actor||getCharacterRegistryId(actor)!=="kurama_sovereign") return null;
  const overload=getKuramaSovereignOverload(actor);
  if (overload>=4) {
    const backlash=absorbBattleDamageBearingCapacity("player",participantId,12);
    const crown=findBattleTransientState({stateKey:"crown_of_the_usurper",targetSide:"player",targetParticipantId:participantId});
    if (crown) removeBattleTransientState(crown.stateId);
    setKuramaSovereignOverload(actor,2,{actionId,sourceRefs:[{type:"character_registry",id:"kurama_sovereign",role:"overload_authority"}]});
    recordBattleEvidence({eventType:"sovereign_overload_backlash",actionId,actorRef:createBattleParticipantRef("player",participantId),sourceRefs:[{type:"character_registry",id:"kurama_sovereign",role:"overload_authority"}],data:{overloadBefore:overload,staminaBypassed:true,backlashBattlePL:12,absorbedPL:backlash.absorbedPL,crownTerminated:!!crown,overloadResetTo:2,selfDamageStatInvented:false}});
    let zeroResult=null;
    if (backlash.totalCapacityAfter<=0) zeroResult=handleBattleParticipantAtZeroPL("player",participantId,actor,{actionId});
    return {overloadBefore:overload,backlash:12,overloadAfter:2,zeroResult};
  }
  if (overload===3) {
    const before=getBattleRemainingPL("player",participantId);
    const after=Math.max(0,before-5);
    setBattleRemainingPL("player",participantId,after);
    recordBattleEvidence({eventType:"sovereign_overload_underlying_battle_pl_deterioration",actionId,actorRef:createBattleParticipantRef("player",participantId),sourceRefs:[{type:"character_registry",id:"kurama_sovereign",role:"overload_authority"}],data:{overload,underlyingBattlePLBefore:before,underlyingBattlePLAfter:after,underlyingBattlePLLoss:before-after,staminaBypassed:true,temporaryCapacityUnaffected:true}});
    let zeroResult=null;
    if (after<=0&&getBattleTemporaryCapacity("player",participantId)<=0) zeroResult=handleBattleParticipantAtZeroPL("player",participantId,actor,{actionId});
    return {overloadBefore:overload,underlyingLoss:before-after,overloadAfter:overload,zeroResult};
  }
  return {overloadBefore:overload,noDeterioration:true,overloadAfter:overload};
}

function consumeBattleActionOpportunity(
  side,
  participantId,
  actionId,
  reason = "valid_action_completed"
) {
  // End-of-opportunity authored effects resolve after the action's own
  // mechanics. This permits a successfully used Antidote to remove Poison
  // before its pending end tick. Burning already resolved at opportunity start.
  const endEffects=resolveBattleEndOfActionOpportunityEffects(side,participantId,actionId);
  const threeTailRegeneration=applyThreeTailEndOpportunityRegeneration(side,participantId,actionId);
  const blackGoldDeterioration=applyBlackGoldSaturationOpportunityDeterioration(side,participantId,actionId);

  const durationConditions=getBattleParticipantConditions(side,participantId)
    .filter(condition=>condition.data&&Number.isFinite(Number(condition.data.remainingActionOpportunities)));
  durationConditions.forEach(condition=>{
    condition.data.remainingActionOpportunities=Math.max(0,Number(condition.data.remainingActionOpportunities)-1);
    recordBattleEvidence({eventType:"condition_duration_advanced",actionId,actorRef:createBattleParticipantRef(side,participantId),conditionRefs:[condition.conditionId],sourceRefs:getBattleConditionCausalSourceRefs(condition),data:{conditionKey:condition.conditionKey,remainingActionOpportunities:condition.data.remainingActionOpportunities}});
    if (condition.data.remainingActionOpportunities<=0) removeBattleCondition(condition.conditionId,{reason:"action_opportunity_duration_expired",actionId,targetRef:createBattleParticipantRef(side,participantId)});
  });

  const expiringConditions=getBattleParticipantConditions(side,participantId)
    .filter(condition=>condition.data&&condition.data.expiry==="next_action_opportunity");
  const removedConditionIds=[];
  expiringConditions.forEach(condition=>{
    if (removeBattleCondition(condition.conditionId,{reason:"next_action_opportunity_expired",actionId,targetRef:createBattleParticipantRef(side,participantId)})) {
      removedConditionIds.push(condition.conditionId);
    }
  });

  consumeBattleEffectiveStateActionOpportunity(side,participantId,actionId,reason);
  advanceBattleTransientStateActionOpportunity(side,participantId,actionId,reason);
  advanceBattleActionOpportunityIndex(side,participantId);
  const sovereignOverload=applyKuramaSovereignOverloadOpportunityCost(side,participantId,actionId);
  const representationLifecycle=consumeDedicatedRepresentationLifecycleActionOpportunity(side,participantId,actionId);
  return {removedConditionIds,endEffects,threeTailRegeneration,blackGoldDeterioration,sovereignOverload,representationLifecycle};
}

function cleanupBattleParticipantRuntimeState(
  side,
  participantId,
  reason = "participant_left_battle"
) {


  const runtime =
    ensureBattleRuntimeState();

  // BRICK 883 — committed Planetary Devastation Stage 1 remains history even
  // when Deva becomes invalid before the forced Stage 2 opportunity.
  const pendingPlanetary=runtime.transientStates.find(state=>state&&state.stateKey==="planetary_core_formation"&&state.sourceRef&&state.sourceRef.side===side&&state.sourceRef.participantId===participantId);
  if (pendingPlanetary) recordBattleEvidence({eventType:"planetary_devastation_pending_invalidated",committedOccurrence:true,actorRef:createBattleParticipantRef(side,participantId),skillId:"akatsuki_deva_planetary_devastation",stateRefs:[pendingPlanetary.stateId],data:{reason,phantomCollapse:false,stage1HistoryPreserved:true}});


  const removedStateIds =
    [];


  const removedConditionIds =
    [];


  runtime.transientStates =
    runtime.transientStates.filter(
      state => {


        const targetsParticipant =
          state.targetRef &&
          state.targetRef.side ===
            side &&
          state.targetRef.participantId ===
            participantId;


        if (
          targetsParticipant
        ) {

          removedStateIds.push(
            state.stateId
          );

          return false;
        }


        return true;
      }
    );

  const cleanupConditionIds=runtime.conditions
    .filter(condition=>condition&&condition.targetRef&&condition.targetRef.side===side&&condition.targetRef.participantId===participantId)
    .map(condition=>condition.conditionId);

  cleanupConditionIds.forEach(conditionId=>{
    if (removeBattleCondition(conditionId,{reason,cleanupOnly:true,removerRef:createBattleParticipantRef(side,participantId)})) {
      removedConditionIds.push(conditionId);
    }
  });


  const removedProjections = getBattleParticipantEffectiveStateProjections(side, participantId);
  removedProjections.forEach(projection => {
    removeBattleEffectiveStateProjection(projection.projectionKey, side, participantId, reason);
  });

  if (runtime.temporaryCapacity[side]) delete runtime.temporaryCapacity[side][participantId];
  if (runtime.attachedSummons[side]) delete runtime.attachedSummons[side][participantId];
  if (runtime.actionOpportunityState&&runtime.actionOpportunityState.counters&&runtime.actionOpportunityState.counters[side]) delete runtime.actionOpportunityState.counters[side][participantId];

  if (
    removedStateIds.length > 0 ||
    removedConditionIds.length > 0 ||
    removedProjections.length > 0
  ) {


    recordBattleEvidence({

      eventType:
        "participant_runtime_cleanup",

      actorRef:
        createBattleParticipantRef(
          side,
          participantId
        ),

      stateRefs:
        removedStateIds,

      conditionRefs:
        removedConditionIds,

      data: {

        reason:
          reason

      }

    });
  }


  return {

    removedStateIds:
      removedStateIds,

    removedConditionIds:
      removedConditionIds,

    removedProjectionKeys:
      removedProjections.map(projection => projection.projectionKey)

  };
}

// =========================================================
// BRICK 304 — SHARED BATTLE ACTION ENVELOPE
// BRICK 344 — ITEM IDENTITY THROUGH SHARED ACTION EVIDENCE
// BRICK 624 — ACTION ENVELOPE PRESERVES TYPED SOURCE ROLES
// =========================================================
//
// Both manual input and future Smart AI should create the
// same semantic action request.
//
// This layer validates the request.
//
// It does NOT calculate final damage.
//
// =========================================================

function createBattleActionEnvelope(
  definition
) {


  const runtime =
    ensureBattleRuntimeState();


  if (
    !definition
  ) {

    return null;
  }


  runtime.actionSequence +=
    1;


  return {

    actionId:
      createBattleRuntimeRecordId(
        "action"
      ),


    battleId:
      currentBattle.battleId,


    sequence:
      runtime.actionSequence,


    actorRef:
      createBattleParticipantRef(
        definition.actorSide,
        definition.actorParticipantId
      ),


    targetRef:
      createBattleParticipantRef(
        definition.targetSide,
        definition.targetParticipantId
      ),


    actionClass:
      definition.actionClass ||
      null,


    skillId:
      definition.skillId ||
      null,


    itemId:
      definition.itemId ||
      null,


    sourceRefs:
      Array.isArray(
        definition.sourceRefs
      )

        ? definition.sourceRefs
            .filter(
              ref =>
                ref &&
                ref.type &&
                (ref.id || (ref.side && ref.participantId))
            )
            .map(
              ref =>
                cloneBattleRuntimeValue(ref)
            )
            .filter(Boolean)

        : [],


    data:
      definition.data
        ? cloneBattleRuntimeValue(
            definition.data
          )
        : {},


    createdAt:
      Date.now()

  };
}


function getBattleActiveParticipantId(
  side
) {


  const slot =
    getBattleDeploymentSlot(
      side,
      1
    );


  return (
    slot &&
    slot.participantId

      ? slot.participantId

      : null
  );
}


function validateBattleActionEnvelope(
  envelope
) {


  if (
    !envelope
  ) {


    return {

      valid:
        false,

      reason:
        "missing_action"

    };
  }


  if (
    !currentBattle.active
  ) {


    return {

      valid:
        false,

      reason:
        "battle_not_active"

    };
  }


  if (
    currentBattle.battleOver
  ) {


    return {

      valid:
        false,

      reason:
        "battle_complete"

    };
  }


  if (
    !envelope.actorRef ||
    !envelope.actorRef.side ||
    !envelope.actorRef
      .participantId
  ) {


    return {

      valid:
        false,

      reason:
        "missing_actor"

    };
  }


  if (
    !envelope.actionClass
  ) {


    return {

      valid:
        false,

      reason:
        "missing_action_class"

    };
  }


  const activeParticipantId =
    getBattleActiveParticipantId(
      envelope.actorRef.side
    );


  if (
    !activeParticipantId ||
    activeParticipantId !==
      envelope.actorRef
        .participantId
  ) {


    return {

      valid:
        false,

      reason:
        "actor_not_active"

    };
  }


  const blockingConditions =
    getBattleBlockingConditions(
      envelope.actorRef.side,
      envelope.actorRef
        .participantId,
      envelope.actionClass,
      envelope.data &&
      Array.isArray(
        envelope.data.traits
      )
        ? envelope.data.traits
        : []
    );


  if (
    blockingConditions.length >
      0
  ) {


    return {

      valid:
        false,

      reason:
        "blocked_by_condition",

      blockingConditionIds:
        blockingConditions.map(
          condition =>
            condition.conditionId
        )

    };
  }


  return {

    valid:
      true,

    reason:
      null,

    blockingConditionIds:
      []

  };
}


// =========================================================
// BRICK 304 — STRUCTURED BATTLE EVIDENCE
// BRICK 570 — TYPED CAUSAL SOURCE / OBSERVER-EVIDENCE BOUNDARY
// BRICK 642 — ACTIVE KONOHA EVIDENCE SCOPE ADDRESSABILITY
// =========================================================
//
// Runtime resolution records what participated.
// Downstream persistent authorities decide what that evidence means afterward.
// actorRef is not automatically an observer, and resolver truth does not
// automatically manufacture observer Knowledge.
//
// =========================================================

function normalizeBattleEvidenceSourceRef(ref) {
  if (!ref||typeof ref!=="object") return null;
  const clone=cloneBattleRuntimeValue(ref);
  if (!clone) return null;
  if (typeof clone.role!=="string"||clone.role.length===0) clone.role="participating_source";
  return clone;
}

function normalizeBattleEvidenceSourceRefs(sourceRefs=[]) {
  const refs=Array.isArray(sourceRefs)?sourceRefs:[];
  const seen=new Set();
  return refs.map(normalizeBattleEvidenceSourceRef).filter(ref=>{
    if (!ref) return false;
    const key=JSON.stringify([ref.type||null,ref.id||null,ref.side||null,ref.participantId||null,ref.role||null]);
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function normalizeBattleEvidenceObserverRefs(observerRefs=[]) {
  const refs=Array.isArray(observerRefs)?observerRefs:[];
  const seen=new Set();
  return refs.filter(ref=>ref&&ref.side&&ref.participantId).map(ref=>createBattleParticipantRef(ref.side,ref.participantId)).filter(ref=>{
    if (!ref) return false;
    const key=`${ref.side}::${ref.participantId}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function battleEvidenceIsAvailableToObserver(evidence,observerRef) {
  if (!evidence||!observerRef||!observerRef.side||!observerRef.participantId) return false;
  if (!Array.isArray(evidence.observerRefs)||evidence.observerRefs.length===0) return false;
  return evidence.observerRefs.some(ref=>ref&&ref.side===observerRef.side&&ref.participantId===observerRef.participantId);
}

function recordBattleEvidence(definition) {
  const runtime=ensureBattleRuntimeState();
  if (!definition||!definition.eventType) return null;
  const record={
    evidenceId:createBattleRuntimeRecordId("evidence"),
    battleId:currentBattle.battleId,
    actionId:definition.actionId||null,
    eventType:definition.eventType,
    historyScope:definition.historyScope&&HISTORY_SCOPE_KINDS.includes(definition.historyScope.kind)
      ? cloneBattleRuntimeValue(definition.historyScope)
      : getCurrentChronicleOccurrenceHistoryScope("battle_evidence"),
    actorRef:definition.actorRef?cloneBattleRuntimeValue(definition.actorRef):null,
    targetRef:definition.targetRef?cloneBattleRuntimeValue(definition.targetRef):null,
    skillId:definition.skillId||null,
    itemId:definition.itemId||null,
    sourceRefs:normalizeBattleEvidenceSourceRefs(definition.sourceRefs),
    stateRefs:Array.isArray(definition.stateRefs)?[...definition.stateRefs]:[],
    conditionRefs:Array.isArray(definition.conditionRefs)?[...definition.conditionRefs]:[],
    observerRefs:normalizeBattleEvidenceObserverRefs(definition.observerRefs),
    // Machine-visible Battle evidence is not automatically finalized Chronicle history.
    committedOccurrence:definition.committedOccurrence===true,
    data:definition.data?cloneBattleRuntimeValue(definition.data):{},
    createdAt:Date.now()
  };
  runtime.evidence.push(record);
  return record;
}

function beginBattleActionResolution(envelope) {
  let startEffects=null;
  if (envelope&&currentBattle.active&&!currentBattle.battleOver&&envelope.actorRef&&envelope.actorRef.side&&envelope.actorRef.participantId&&getBattleActiveParticipantId(envelope.actorRef.side)===envelope.actorRef.participantId) {
    startEffects=resolveBattleStartOfActionOpportunityEffects(envelope.actorRef.side,envelope.actorRef.participantId,envelope.actionId||null);
  }
  // BRICKS 883/885 — pre-commit authority may force an already committed
  // continuation or consume exact authored interference. Rejected requests do
  // not consume a new action opportunity or fabricate an action occurrence.
  const preCommit=resolveAlphaPreCommitBattleActionAuthority(envelope);
  if (preCommit&&preCommit.allowed===false) {
    return {accepted:false,validation:{valid:false,reason:preCommit.reason,blockingConditionIds:[],preCommitAuthority:true},evidence:null,startEffects,preCommit};
  }
  const validation=validateBattleActionEnvelope(envelope);
  if (!validation.valid) return {accepted:false,validation,evidence:null,startEffects};
  const evidence=recordBattleEvidence({
    eventType:"action_attempted",actionId:envelope.actionId,actorRef:envelope.actorRef,targetRef:envelope.targetRef,
    skillId:envelope.skillId,itemId:envelope.itemId,sourceRefs:envelope.sourceRefs,
    data:{actionClass:envelope.actionClass,resolverTruthIsObserverKnowledge:false}
  });
  return {accepted:true,validation,evidence,startEffects,preCommit};
}

const JOINT_TECHNIQUE_PROVENANCE_AUTHORITY = {
  kage_menma_eclipse_beast_cannon:{
    skillId:"kage_menma_eclipse_beast_cannon",
    actorRegistryId:"kage_menma",
    assistingEntityId:"menma_kurama",
    authoredAttackPL:90,
    outputOwner:"technique",
    mergeRegistryIdentities:false,
    transferEntityPL:false,
    transferEntityStats:false,
    collapseHistoricalAuthorshipToConsumer:false
  }
};

function getJointTechniqueProvenanceAuthority(skillId) {
  return skillId&&JOINT_TECHNIQUE_PROVENANCE_AUTHORITY[skillId]||null;
}

function createJointTechniqueSourceRefs(skillId,actorSide,actorParticipantId) {
  const authority=getJointTechniqueProvenanceAuthority(skillId);
  if (!authority) return [];
  return [
    {type:"participant",side:actorSide,participantId:actorParticipantId,role:"initiating_actor"},
    {type:"character_registry",id:authority.actorRegistryId,role:"access_and_commitment_source"},
    {type:"entity",id:authority.assistingEntityId,role:"assisting_source"},
    {type:"skill",id:skillId,role:"authored_joint_output_owner"}
  ];
}

function recordBaryonLifespanErosionOccurrence(definition={}) {
  const actorSide=definition.actorSide||"player";
  const actorParticipantId=definition.actorParticipantId||null;
  const targetSide=definition.targetSide||null;
  const targetParticipantId=definition.targetParticipantId||null;
  if (!actorParticipantId||!targetSide||!targetParticipantId) return {success:false,reason:"baryon_participant_refs_missing"};
  const actor=getBattleParticipantByIdentity(actorSide,actorParticipantId);
  if (!actor||getCharacterRegistryId(actor)!=="baryon_mode") return {success:false,reason:"actor_not_baryon_representation"};
  if (definition.directContactSucceeded!==true) return {success:false,reason:"qualifying_direct_contact_not_confirmed"};
  const opportunityIndex=getBattleActionOpportunityIndex(actorSide,actorParticipantId);
  const runtime=ensureBattleRuntimeState();
  const duplicate=runtime.evidence.some(record=>
    record&&record.eventType==="baryon_lifespan_erosion"&&record.actorRef&&record.actorRef.side===actorSide&&record.actorRef.participantId===actorParticipantId&&
    record.targetRef&&record.targetRef.side===targetSide&&record.targetRef.participantId===targetParticipantId&&
    record.data&&Number(record.data.actorOpportunityIndex)===Number(opportunityIndex)
  );
  if (duplicate) return {success:false,reason:"baryon_erosion_already_recorded_for_target_this_opportunity",idempotent:true};
  const evidence=recordBattleEvidence({
    eventType:"baryon_lifespan_erosion",
    actionId:definition.actionId||null,
    actorRef:createBattleParticipantRef(actorSide,actorParticipantId),
    targetRef:createBattleParticipantRef(targetSide,targetParticipantId),
    skillId:definition.skillId||null,
    sourceRefs:[
      {type:"character_registry",id:"baryon_mode",role:"active_representation"},
      ...(definition.skillId?[{type:"skill",id:definition.skillId,role:"qualifying_direct_contact_action"}]:[])
    ],
    data:{
      actorOpportunityIndex:opportunityIndex,
      directContactSucceeded:true,
      attackPLContribution:0,
      battlePLCost:0,
      injuryMutation:false,
      selfDamage:false,
      universalLifespanStatCreated:false,
      maximumOccurrencesPerTargetPerActorOpportunity:1
    }
  });
  return evidence?{success:true,evidence}:{success:false,reason:"baryon_erosion_evidence_commit_failed"};
}


// =========================================================
// BRICK 304 — RUNTIME FOUNDATION DIAGNOSTIC
// =========================================================
//
// Safe developer diagnostic.
//
// Creates temporary test state, validates it, then removes
// everything it created.
//
// No damage is dealt.
//
// =========================================================

function runBattleRuntimeFoundationDiagnostics() {


  if (
    !currentBattle.active ||
    currentBattle.battleOver
  ) {


    return {

      pass:
        false,

      reason:
        "Start an active Battle first."

    };
  }


  const runtime =
    ensureBattleRuntimeState();


  const startingSequence =
    runtime.actionSequence;


  const actor =
    getBattleDeploymentParticipant(
      "player",
      1
    );


  const target =
    getBattleDeploymentParticipant(
      "enemy",
      1
    );


  const unrelatedPlayer =
    getBattleDeploymentParticipant(
      "player",
      2
    );


  if (
    !actor ||
    !target
  ) {


    return {

      pass:
        false,

      reason:
        "Active participants missing."

    };
  }


  const transientState =
    addBattleTransientState({

      stateKey:
        "diagnostic_opening",

      sourceSide:
        "player",

      sourceParticipantId:
        actor.id,

      targetSide:
        "enemy",

      targetParticipantId:
        target.id

    });


  const sourceCanConsume =
    canBattleParticipantConsumeTransientState(
      transientState,
      "player",
      actor.id
    );


  const unrelatedCanConsume =
    unrelatedPlayer

      ? canBattleParticipantConsumeTransientState(
          transientState,
          "player",
          unrelatedPlayer.id
        )

      : false;


  const consumedState =
    consumeBattleTransientState(
      transientState.stateId,
      "player",
      actor.id
    );


  const condition =
    addBattleCondition({

      conditionKey:
        "diagnostic_action_lock",

      sourceSide:
        "enemy",

      sourceParticipantId:
        target.id,

      targetSide:
        "player",

      targetParticipantId:
        actor.id,

      blockedActionClasses: [
        "diagnostic_action"
      ]

    });


  const blockedEnvelope =
    createBattleActionEnvelope({

      actorSide:
        "player",

      actorParticipantId:
        actor.id,

      targetSide:
        "enemy",

      targetParticipantId:
        target.id,

      actionClass:
        "diagnostic_action"

    });


  const blockedValidation =
    validateBattleActionEnvelope(
      blockedEnvelope
    );


  removeBattleCondition(
    condition.conditionId
  );


  const clearEnvelope =
    createBattleActionEnvelope({

      actorSide:
        "player",

      actorParticipantId:
        actor.id,

      targetSide:
        "enemy",

      targetParticipantId:
        target.id,

      actionClass:
        "diagnostic_action"

    });


  const clearValidation =
    validateBattleActionEnvelope(
      clearEnvelope
    );


  const diagnosticEvidence =
    recordBattleEvidence({

      eventType:
        "diagnostic_evidence",

      actorRef:
        clearEnvelope.actorRef,

      targetRef:
        clearEnvelope.targetRef,

      data: {
        diagnostic:
          true
      }

    });


  runtime.evidence =
    runtime.evidence.filter(
      entry =>
        entry.evidenceId !==
          diagnosticEvidence.evidenceId
    );


  runtime.actionSequence =
    startingSequence;


  const result = {

    transientStateCreated:
      !!transientState,


    sourceScopedConsumerAllowed:
      sourceCanConsume ===
      true,


    unrelatedConsumerRejected:
      unrelatedCanConsume ===
      false,


    transientStateConsumed:
      !!consumedState,


    conditionBlockedAction:
      blockedValidation.valid ===
        false &&
      blockedValidation.reason ===
        "blocked_by_condition",


    actionAllowedAfterConditionRemoval:
      clearValidation.valid ===
      true,


    structuredEvidenceCreated:
      !!diagnosticEvidence

  };


  result.pass =
    Object.values(
      result
    ).every(
      value =>
        value ===
        true
    );


  console.table(
    result
  );


  return result;
}


