// BRICK 637 — KURAMA SOVEREIGN STATIC CONTRACT DIAGNOSTIC
// BRICK 638 — SOVEREIGN NO-STACK / RESERVOIR BOUNDARY DIAGNOSTIC
// =========================================================
function runKuramaSovereignImplementationDiagnostics() {
  const owner=(id)=>getClosureWaveBattleSkillDefinition(id,"kurama_sovereign");
  const record=getCharacterRegistryEntry("kurama_sovereign");
  const special=SPECIAL_REPRESENTATION_PREPARED_SKILL_PALETTES.kurama_sovereign||[];
  const result={
    registryPL:!!record&&Number(record.basePL)===132,
    dedicatedEmbodiment:!!record&&record.embodiedPackageId==="coercive_kurama_sovereign",
    noOrdinaryPaletteInference:!Object.prototype.hasOwnProperty.call(PRODUCTION_PREPARED_SKILL_PALETTES,"kurama_sovereign"),
    exactFiveSpecialCards:special.length===5&&special[1]==="kurama_sovereign_atomic_core",
    annihilationNotSixthDefault:!special.includes("kurama_sovereign_atomic_annihilation")&&!!owner("kurama_sovereign_atomic_annihilation"),
    exactSkillIds:[
      "kurama_sovereign_chains_of_the_sovereign","kurama_sovereign_atomic_core","kurama_sovereign_ninefold_array",
      "kurama_sovereign_black_sun_dominion","kurama_sovereign_usurpers_execution","kurama_sovereign_atomic_annihilation",
      "kurama_sovereign_imperial_mantle"
    ].every(id=>!!owner(id)),
    atomicExcess80:owner("kurama_sovereign_atomic_annihilation")&&owner("kurama_sovereign_atomic_annihilation").excess.capRatio===0.80,
    explicitModeAuthority:["kurama_sovereign_ninefold_array","kurama_sovereign_black_sun_dominion","kurama_sovereign_usurpers_execution"].every(id=>owner(id)&&owner(id).requiresExplicitModeSelection===true),
    reservoirCap:KURAMA_SOVEREIGN_RESERVOIR_CAP===30,
    distinctReservoirs:KURAMA_SOVEREIGN_ATOMIC_RESERVE_KEY!==KURAMA_SOVEREIGN_BLACK_SUN_RESERVE_KEY,
    noBlindSecondSovereignProjection:!DEFAULT_ATTACHED_SUMMON_ENHANCEMENT_PACKAGES.kurama_sovereign,
    sourceRolePreservation:createBattleActionEnvelope.toString().includes("cloneBattleRuntimeValue(ref)"),
    overloadOpportunityHook:consumeBattleActionOpportunity.toString().includes("applyKuramaSovereignOverloadOpportunityCost")
  };
  result.pass=Object.values(result).every(value=>value===true);
  console.table(result);
  return result;
}


// BRICK 308 — SKILL AVAILABILITY
// BRICK 316 — PERSISTENT THROWING-WEAPON AVAILABILITY
// =========================================================

function getBattleAvailablePersistentThrowingWeaponContext(
  character,
  allowedWeaponClasses = []
) {


  if (
    !character ||
    !playerData ||
    !Array.isArray(
      playerData.inventory
    )
  ) {

    return null;
  }


  const allowed =
    Array.isArray(
      allowedWeaponClasses
    )
      ? allowedWeaponClasses
      : [];


  const candidates =
    playerData.inventory.filter(
      item => {


        if (
          !item ||
          !item.instanceId ||
          item.type !==
            "weapon"
        ) {

          return false;
        }


        if (
          item.equippedBy &&
          item.equippedBy !==
            character.id
        ) {

          return false;
        }


        const definition =
          getItemDefinition(
            item.id
          );


        if (
          !definition ||
          definition.type !==
            "weapon" ||
          definition
            .persistentThrowingWeapon !==
            true
        ) {

          return false;
        }


        if (
          allowed.length >
            0 &&
          !allowed.includes(
            definition.weaponClass
          )
        ) {

          return false;
        }


        return true;
      }
    );


  const selected =
    candidates[
      0
    ] ||
    null;


  if (
    !selected
  ) {

    return null;
  }


  const definition =
    getItemDefinition(
      selected.id
    );


  return {

    instanceId:
      selected.instanceId,

    itemId:
      selected.id,

    weaponClass:
      definition.weaponClass ||
      null,

    persistentThrowingWeapon:
      true,

    persistentWeaponSet:
      definition
        .persistentWeaponSet ===
        true,

    equipped:
      selected.equippedBy ===
        character.id,

    definition:
      definition,

    inventoryItem:
      selected

  };
}


function evaluateAcademyBattleSkillAvailability(
  skill,
  actor,
  target
) {


  if (
    !skill ||
    !actor
  ) {

    return {

      available:
        false,

      reason:
        "Missing Skill or actor."

    };
  }


  if (
    !currentBattle.active ||
    currentBattle.battleOver
  ) {

    return {

      available:
        false,

      reason:
        "Battle is not active."

    };
  }


  if (
    skill.ownerId !==
      actor.id
  ) {

    return {

      available:
        false,

      reason:
        "Wrong Skill owner."

    };
  }


  if (
    !getPreparedAcademyBattleSkillIds(
      actor.id
    ).includes(
      skill.id
    )
  ) {

    return {

      available:
        false,

      reason:
        "Skill is not prepared."

    };
  }


  if (
    skill.targetMode ===
      "current_enemy" &&
    !target
  ) {

    return {

      available:
        false,

      reason:
        "No current enemy."

    };
  }


  const blockingConditions =
    getBattleBlockingConditions(
      "player",
      actor.id,
      skill.actionClass,
      Array.isArray(
        skill.traits
      )
        ? skill.traits
        : []
    );


  if (
    blockingConditions.length >
      0
  ) {

    return {

      available:
        false,

      reason:
        "Blocked by current Condition.",

      blockingConditionIds:
        blockingConditions.map(
          condition =>
            condition.conditionId
        )

    };
  }


  let weaponContext =
    getBattleEquippedWeaponExecutionContext(
      actor
    );


  const toolContexts =
    [];


  const hostedAccessRecords =
    [];


  const attachedSummonAccessRecords =
    [];


  for (
    const requirement of
    skill.requirements ||
    []
  ) {


    if (
      !requirement ||
      !requirement.kind
    ) {

      continue;
    }


    // =====================================================
    // WEAPON CLASS
    // =====================================================

    if (
      requirement.kind ===
        "weapon_class"
    ) {


      if (
        !weaponContext ||
        !Array.isArray(
          requirement.allowedWeaponClasses
        ) ||
        !requirement
          .allowedWeaponClasses
          .includes(
            weaponContext.weaponClass
          )
      ) {

        return {

          available:
            false,

          reason:
            requirement.label ||
            "Compatible weapon required."

        };
      }
    }


    // =====================================================
    // REUSABLE THROWING WEAPON
    // =====================================================

    if (
      requirement.kind ===
        "persistent_throwing_weapon"
    ) {


      const throwingWeaponContext =
        getBattleAvailablePersistentThrowingWeaponContext(
          actor,
          requirement.allowedWeaponClasses ||
          []
        );


      if (
        !throwingWeaponContext
      ) {

        return {

          available:
            false,

          reason:
            requirement.label ||
            "Persistent throwing weapon required."

        };
      }


      weaponContext =
        throwingWeaponContext;
    }


    // =====================================================
    // PERSISTENT TOOL
    // =====================================================

    if (
      requirement.kind ===
        "tool_item"
    ) {


      const toolContext =
        getBattleInventoryToolContext(
          requirement.itemId
        );


      if (
        !toolContext
      ) {

        return {

          available:
            false,

          reason:
            requirement.label ||
            "Required tool unavailable."

        };
      }


      toolContexts.push(
        toolContext
      );
    }


    // =====================================================
    // ATTACHED SUMMON ACCESS
    // =====================================================

    if (
      requirement.kind ===
        "attached_summon_access"
    ) {

      const access =
        evaluateAttachedSummonAccess(
          actor.id,
          requirement.entityId,
          {
            requireCooperative: requirement.requireCooperative === true,
            expressionId: requirement.expressionId || null,
            cooperativeCapabilityId: requirement.cooperativeCapabilityId || null
          }
        );

      if (!access.available) {
        return { available:false, reason:requirement.label || access.reason, attachedSummonAccess:access };
      }

      attachedSummonAccessRecords.push(access);
    }


    // =====================================================
    // HOSTED / BOUND ENTITY ACCESS
    // =====================================================

    if (
      requirement.kind ===
        "hosted_entity_access"
    ) {


      const access =
        evaluateHostedEntityAccess(
          actor.id,
          requirement.entityId,
          {

            requireCooperative:
              requirement
                .requireCooperative ===
                true,

            expressionId:
              requirement.expressionId ||
              null,

            cooperativeCapabilityId:
              requirement
                .cooperativeCapabilityId ||
              null

          }
        );


      if (
        !access.available
      ) {

        return {

          available:
            false,

          reason:
            requirement.label ||
            access.reason,

          hostedAccess:
            access

        };
      }


      hostedAccessRecords.push(
        access
      );
    }
  }


  return {

    available:
      true,

    reason:
      null,

    weaponContext:
      weaponContext,

    toolContexts:
      toolContexts,

    hostedAccessRecords:
      hostedAccessRecords,

    attachedSummonAccessRecords:
      attachedSummonAccessRecords

  };
}



// =========================================================
// BRICK 309 — TEMPORARY DEVELOPER SKILL CARDS
// BRICK 560 — CONDITION-AWARE SKILL / PANEL PRESENTATION
// =========================================================
//
// Skill admissibility remains authoritative in
// evaluateAcademyBattleSkillAvailability().
//
// This Brick only presents that result:
// - blocked Skill cards receive a Condition seal;
// - the active actor receives a compact Condition marker;
// - the right-side panel explains the current Condition;
// - no Skill ID is hard-coded as blocked.
//
// =========================================================

function getAcademyBattleSkillCompactStatus(
  skill,
  availability
) {

  if (
    !availability.available
  ) {

    return availability.reason;
  }

  if (
    skill.resolutionKind ===
      "transient_state" &&
    skill.state
  ) {

    return (
      `Creates ${skill.state.stateKey}`
    );
  }

  if (
    skill.traits.includes(
      "multi_hit_presentation"
    )
  ) {

    return (
      `${skill.visualImpactCount} visuals • 1 packet`
    );
  }

  if (
    skill.conditional &&
    skill.conditional.stateKey
  ) {

    return (
      `Uses ${skill.conditional.stateKey}`
    );
  }

  if (
    skill.staminaMitigation ===
      true &&
    skill.damageProfile
  ) {

    return (
      `${skill.damageProfile.coefficient}× ${skill.primaryDiscipline} • 1 packet`
    );
  }

  return "Ready";
}


function isBattleSkillConditionBlocked(
  availability
) {

  return !!(
    availability &&
    availability.available !==
      true &&
    availability.reason ===
      "Blocked by current Condition." &&
    Array.isArray(
      availability.blockingConditionIds
    ) &&
    availability.blockingConditionIds.length >
      0
  );
}


function getBattleConditionByPresentationId(
  conditionId
) {

  if (
    !conditionId
  ) {

    return null;
  }

  const runtime =
    ensureBattleRuntimeState();

  return runtime.conditions
    .find(
      condition =>
        condition &&
        condition.conditionId ===
          conditionId
    ) ||
    null;
}


function getBattleSkillBlockingConditionPresentation(
  availability
) {

  if (
    !isBattleSkillConditionBlocked(
      availability
    )
  ) {

    return null;
  }

  for (
    const conditionId of
    availability.blockingConditionIds
  ) {

    const condition =
      getBattleConditionByPresentationId(
        conditionId
      );

    const presentation =
      getBattleConditionCardSealPresentation(
        condition
      );

    if (
      presentation
    ) {

      return presentation;
    }
  }

  return {
    conditionId:
      availability
        .blockingConditionIds[0] ||
      null,
    conditionKey:
      null,
    displayName:
      "Current Condition",
    sealHeadline:
      "CONDITION",
    sealState:
      "BLOCKED"
  };
}


function getBattlePrimaryConditionPresentation(
  actor
) {

  if (
    !actor
  ) {

    return null;
  }

  const conditions =
    getBattleParticipantConditions(
      "player",
      actor.id
    );

  if (
    conditions.length ===
      0
  ) {

    return null;
  }

  const entries =
    conditions
      .map(
        condition => ({
          condition,
          presentation:
            getBattleConditionPresentationDescriptor(
              condition
            )
        })
      )
      .filter(
        entry =>
          !!entry.presentation
      );

  if (
    entries.length ===
      0
  ) {

    return null;
  }

  const blockingEntry =
    entries.find(
      entry =>
        entry.presentation
          .blocksActions ===
          true
    );

  return (
    blockingEntry ||
    entries[0]
  ).presentation;
}


function renderBattleConditionPanel(
  actor
) {

  const condition =
    getBattlePrimaryConditionPresentation(
      actor
    );

  if (
    !condition
  ) {

    return "";
  }

  const displayName =
    condition.displayName
      .toUpperCase();

  const isNextRealAction =
    condition.expiresOnNextActionOpportunity ===
      true;

  const lifecyclePrimary =
    isNextRealAction
      ? "NEXT REAL ACTION"
      : Number.isFinite(
          Number(
            condition.remainingTicks
          )
        )
        ? `${condition.remainingTicks} TICK${condition.remainingTicks === 1 ? "" : "S"} REMAINING`
        : "ACTIVE CONDITION";

  const lifecycleDetail =
    isNextRealAction
      ? "Invalid choices do not consume condition."
      : condition.timing ===
          "start_of_action"
        ? "Authored effect resolves at action start."
        : condition.timing ===
            "end_of_action"
          ? "Authored effect resolves at action end."
          : "Runtime condition remains under its authored lifecycle.";

  const expiryMarkup =
    isNextRealAction
      ? `
          <div class="battle-live-condition-row">
            <span class="battle-live-condition-row-icon" aria-hidden="true">
              ◷
            </span>

            <span class="battle-live-condition-row-copy">
              <strong>THEN EXPIRES</strong>
              <small>Condition ends after that consumed action opportunity.</small>
            </span>
          </div>
        `
      : "";

  return `
    <div
      class="battle-live-condition-roster-marker"
      aria-label="${displayName}"
      data-condition-key="${condition.conditionKey || "condition"}"
    >
      <span aria-hidden="true">◉</span>
      <small>${displayName}</small>
    </div>

    <aside
      class="battle-live-condition-panel"
      aria-label="Active Battle Condition"
      aria-live="polite"
      data-condition-key="${condition.conditionKey || "condition"}"
    >
      <div class="battle-live-condition-panel-title">
        <span aria-hidden="true">◉</span>
        <strong>CONDITION APPLIED</strong>
      </div>

      <div class="battle-live-condition-name">
        ${displayName}
      </div>

      <div class="battle-live-condition-row">
        <span class="battle-live-condition-row-icon" aria-hidden="true">
          ▶
        </span>

        <span class="battle-live-condition-row-copy">
          <strong>${lifecyclePrimary}</strong>
          <small>${lifecycleDetail}</small>
        </span>
      </div>

      ${expiryMarkup}

      <div class="battle-live-condition-footer">
        INVALID ATTEMPT • RETAINED
      </div>
    </aside>
  `;
}


function getBattlePreparedSkillDefinition(actor,skillId) {
  if (!actor||!skillId) return null;
  return getClosureWaveBattleSkillDefinition(skillId,actor) || getAcademyBattleSkillDefinition(skillId);
}

function evaluateBattlePreparedSkillAvailability(skill,actor,target) {
  if (!skill) return {available:false,reason:"skill_missing"};
  if (Object.values(CLOSURE_WAVE_1_BATTLE_SKILL_DATABASE).includes(skill)) {
    const result=evaluateClosureWaveSkillAvailability(skill,actor,target);
    if (result.available&&skill.resolutionKind==="branch_damage"&&skill.requiresExplicitModeSelection===true) return {available:false,reason:"branch_selection_required",branchSelectionRequired:true};
    if (result.available&&skill.categorical&&skill.categorical.reactiveOnly===true) return {available:false,reason:"reactive_window_required",reactiveOnly:true};
    return result;
  }
  return evaluateAcademyBattleSkillAvailability(skill,actor,target);
}

function attemptBattlePreparedSkill(skillId,targetParticipantId=null,options={}) {
  const actor=getBattleDeploymentParticipant("player",1);
  if (!actor) return {success:false,reason:"actor_missing"};
  const closure=getClosureWaveBattleSkillDefinition(skillId,actor);
  if (closure) return attemptClosureWaveBattleSkill(skillId,targetParticipantId,options);
  return attemptAcademyBattleSkill(skillId);
}

// =========================================================
// BRICK 721 — RUNTIME MODE PROJECTION FOR COMMITTED SPECIAL TECHNIQUES
// =========================================================
function getBattlePreparedSkillAvailableModes(skill,actor) {
  if (!skill) return [];
  if (skill.dynamicRuntimeModes===true && skill.id==="kurama_dominion_extinction_core") {
    const state=getKuramaDominionExtinctionCoreState(actor);
    if (!state) return [];
    const stage=Math.max(1,Math.floor(Number(state.data&&state.data.stage)||1));
    if (stage===1||stage===2) return ["release","continue"];
    return [];
  }
  return skill.requiresExplicitModeSelection===true
    ? (Array.isArray(skill.availableModes)?[...skill.availableModes]:Object.keys(skill.modes||{}))
    : [];
}

function battleSkillRequiresCurrentModeSelection(skill,actor) {
  return getBattlePreparedSkillAvailableModes(skill,actor).length>0;
}

function getBattlePreparedSkillPresentationDescription(skill) {
  if (!skill) return "No Skill selected.";
  const kind=String(skill.resolutionKind||skill.actionClass||"authored_action").replaceAll("_"," ");
  const discipline=skill.primaryDiscipline?` • ${skill.primaryDiscipline}`:"";
  return `${kind.toUpperCase()}${discipline}`;
}

function renderBattleSelectedSkillDetails(actor,target) {
  const state=syncBattleActionRegionState();
  if (state.mode!=="skills") return "";
  const skill=actor&&state.selectedSkillId?getBattlePreparedSkillDefinition(actor,state.selectedSkillId):null;
  if (!skill) {
    return `
      <aside class="battle-live-skill-details" aria-label="Skill Details">
        <div class="battle-live-skill-details-title">SKILL DETAILS</div>
        <div class="battle-live-skill-details-empty">Select a Skill.</div>
      </aside>
    `;
  }

  const selectedTarget=state.selectedTargetRef
    ? getBattleParticipantByIdentity(state.selectedTargetRef.side,state.selectedTargetRef.participantId)
    : null;
  const branchModes=getBattlePreparedSkillAvailableModes(skill,actor);
  const selectedMode=state.selectedSkillOptions&&state.selectedSkillOptions.mode||null;
  const modeMarkup=branchModes.length>0
    ? `<div class="battle-live-skill-mode-list">${branchModes.map(mode=>`
        <button type="button" class="battle-live-skill-mode ${selectedMode===mode?"is-selected":""}" onclick="setSelectedBattleSkillMode('${mode}')">${String(mode).replaceAll("_"," ").toUpperCase()}</button>
      `).join("")}</div>`
    : "";
  const canConfirm=branchModes.length===0||!!selectedMode;

  return `
    <aside class="battle-live-skill-details" aria-label="Skill Details">
      <div class="battle-live-skill-details-title">SKILL DETAILS</div>
      <strong class="battle-live-skill-details-name">${skill.displayName||getFactorySkillDisplayName(skill.id)}</strong>
      <span class="battle-live-skill-details-type">${getBattlePreparedSkillPresentationDescription(skill)}</span>
      <span class="battle-live-skill-details-target">TARGET: ${selectedTarget?(selectedTarget.name||selectedTarget.id):"—"}</span>
      ${modeMarkup}
      <div class="battle-live-skill-details-actions">
        <button type="button" class="battle-live-use-skill" onclick="confirmSelectedBattleSkill()" ${canConfirm?"":"disabled"}>USE SKILL</button>
        <button type="button" class="battle-live-cancel-skill" onclick="cancelSelectedBattleSkill()">CANCEL</button>
      </div>
    </aside>
  `;
}

function renderTemporaryBattleSkillDeck(actor,target) {
  const presentation=actor?getBattleUISkillPalettePresentation(actor):{skillIds:[],source:"none"};
  const skillIds=Array.isArray(presentation.skillIds)?presentation.skillIds:[];
  const state=syncBattleActionRegionState();
  const cards=[];
  for (let index=0;index<5;index+=1) {
    const skillId=skillIds[index]||null;
    const skill=skillId?getBattlePreparedSkillDefinition(actor,skillId):null;
    if (!skill) {
      cards.push(`<div class="battle-dev-skill-card is-empty"><span>${index===0&&skillIds.length===0?"NO AUTHORED SKILLS":"EMPTY"}</span></div>`);
      continue;
    }
    const skillDefaultTarget=getBattlePreparedSkillDefaultTarget(actor,skill);
    const availability=evaluateBattlePreparedSkillAvailability(skill,actor,skillDefaultTarget.participant);
    const selectable=availability.available===true||availability.reason==="branch_selection_required";
    const selected=state.selectedSkillId===skill.id;
    const conditionBlocked=isBattleSkillConditionBlocked(availability);
    const blockingCondition=conditionBlocked?getBattleSkillBlockingConditionPresentation(availability):null;
    const status=selected?"SELECTED":availability.available?"READY":availability.reason==="branch_selection_required"?"READY":String(availability.reason||"UNAVAILABLE").replaceAll("_"," ").toUpperCase();
    const conditionSealMarkup=blockingCondition?`<span class="battle-skill-condition-seal" aria-hidden="true"><span class="battle-skill-condition-seal-symbol">◉</span><span class="battle-skill-condition-seal-headline">${blockingCondition.sealHeadline}</span><strong class="battle-skill-condition-seal-state">${blockingCondition.sealState}</strong></span>`:"";
    cards.push(`<button type="button" class="battle-dev-skill-card ${selectable?"is-ready":"is-disabled"} ${selected?"is-selected":""} ${conditionBlocked?"is-condition-blocked":""}" onclick="selectBattlePreparedSkill('${skill.id}')" ${selectable?"":"disabled"} ${blockingCondition?`data-blocking-condition-id="${blockingCondition.conditionId||""}"`:""} aria-pressed="${selected?"true":"false"}" title="${status}"><span class="battle-dev-skill-discipline">${skill.primaryDiscipline||"AUTHORED"}</span><strong>${skill.displayName||getFactorySkillDisplayName(skill.id)}</strong><span class="battle-dev-skill-type">${skill.actionClass||skill.type||"Technique"}</span><small>${status}</small>${conditionSealMarkup}</button>`);
  }
  return `<div class="battle-live-skill-deck" aria-label="Prepared Battle Skills" data-palette-source="${presentation.source||"unknown"}">${cards.join("")}</div>`;
}

// BRICK 310 — TRANSIENT STATE UPSERT
// BRICK 690 — SOURCE/TARGET LIFECYCLE METADATA PRESERVATION
// =========================================================

function upsertAcademyBattleSkillState(
  skill,
  actor,
  target
) {


  if (
    !skill ||
    !skill.state ||
    !actor ||
    !target
  ) {

    return null;
  }


  const targetSide =
    skill.targetMode ===
      "self"

      ? "player"

      : "enemy";


  const existing =
    findBattleTransientState({

      stateKey:
        skill.state.stateKey,

      sourceSide:
        "player",

      sourceParticipantId:
        actor.id,

      targetSide:
        targetSide,

      targetParticipantId:
        target.id

    });


  if (
    existing
  ) {


    existing.createdActionSequence =
      ensureBattleRuntimeState()
        .actionSequence;


    existing.createdAt =
      Date.now();


    existing.ownerRef =
      skill.stateOwnerRef
        ? cloneBattleRuntimeValue(
            skill.stateOwnerRef
          )
        : existing.ownerRef;


    existing.data = {

      ...(
        existing.data ||
        {}
      ),

      skillId:
        skill.id,

      reapplication:
        skill.state.reapplication ||
        "refresh_replace",

      consumeOn:
        skill.state.consumeOn ||
        null,

      compatibleConsumerTrait:
        skill.state
          .compatibleConsumerTrait ||
        null,

      expiry:
        skill.state.expiry ||
        null,

      remainingCharges:
        Number.isFinite(Number(skill.state.remainingCharges))
          ? Math.max(0, Number(skill.state.remainingCharges))
          : (existing.data && Number.isFinite(Number(existing.data.remainingCharges))
              ? Number(existing.data.remainingCharges)
              : null),

      remainingActionOpportunities:
        Number.isFinite(Number(skill.state.remainingActionOpportunities))
          ? Math.max(0, Number(skill.state.remainingActionOpportunities))
          : (existing.data && Number.isFinite(Number(existing.data.remainingActionOpportunities))
              ? Number(existing.data.remainingActionOpportunities)
              : null),

      remainingSourceActionOpportunities:
        Number.isFinite(Number(skill.state.remainingSourceActionOpportunities))
          ? Math.max(0, Number(skill.state.remainingSourceActionOpportunities))
          : (existing.data && Number.isFinite(Number(existing.data.remainingSourceActionOpportunities))
              ? Number(existing.data.remainingSourceActionOpportunities)
              : null)

    };


    return {

      state:
        existing,

      refreshed:
        true

    };
  }


  const state =
    addBattleTransientState({

      stateKey:
        skill.state.stateKey,

      sourceSide:
        "player",

      sourceParticipantId:
        actor.id,

      targetSide:
        targetSide,

      targetParticipantId:
        target.id,

      ownerRef:
        skill.stateOwnerRef ||
        null,

      data: {

        skillId:
          skill.id,

        reapplication:
          skill.state.reapplication ||
          "refresh_replace",

        consumeOn:
          skill.state.consumeOn ||
          null,

        compatibleConsumerTrait:
          skill.state
            .compatibleConsumerTrait ||
          null,

        expiry:
          skill.state.expiry ||
          null,

        remainingCharges:
          Number.isFinite(Number(skill.state.remainingCharges))
            ? Math.max(0, Number(skill.state.remainingCharges))
            : null,

        remainingActionOpportunities:
          Number.isFinite(Number(skill.state.remainingActionOpportunities))
            ? Math.max(0, Number(skill.state.remainingActionOpportunities))
            : null,

        remainingSourceActionOpportunities:
          Number.isFinite(Number(skill.state.remainingSourceActionOpportunities))
            ? Math.max(0, Number(skill.state.remainingSourceActionOpportunities))
            : null

      }

    });


  return state

    ? {

        state:
          state,

        refreshed:
          false

      }

    : null;
}


// =========================================================
// BRICK 310 — SOURCE PARTICIPATION EVIDENCE
// =========================================================

function getAcademyBattleSkillSourceRefs(
  availability
) {


  const refs =
    [];


  if (
    availability &&
    availability.weaponContext &&
    availability.weaponContext.instanceId
  ) {


    refs.push({

      type:
        "weapon_instance",

      id:
        availability
          .weaponContext
          .instanceId

    });
  }


  if (
    availability &&
    Array.isArray(
      availability.toolContexts
    )
  ) {


    availability.toolContexts.forEach(
      context => {


        if (
          context &&
          context.instanceId
        ) {


          refs.push({

            type:
              "tool_instance",

            id:
              context.instanceId

          });
        }
      }
    );
  }


  if (
    availability &&
    Array.isArray(
      availability.hostedAccessRecords
    )
  ) {


    availability
      .hostedAccessRecords
      .forEach(
        access => {


          if (
            access &&
            access.entity &&
            access.entity.id
          ) {


            refs.push({

              type:
                "hosted_entity",

              id:
                access.entity.id

            });
          }


          if (
            access &&
            access.binding &&
            access.binding.id
          ) {


            refs.push({

              type:
                "hosted_binding",

              id:
                access.binding.id

            });
          }
        }
      );
  }


  if (
    availability &&
    Array.isArray(availability.attachedSummonAccessRecords)
  ) {
    availability.attachedSummonAccessRecords.forEach(access => {
      if (access && access.entity && access.entity.id) refs.push({type:"attached_summon",id:access.entity.id});
      if (access && access.access && access.access.id) refs.push({type:"summon_access",id:access.access.id});
    });
  }


  const unique =
    [];


  const seen =
    new Set();


  refs.forEach(
    ref => {


      const key =
        `${ref.type}:${ref.id}`;


      if (
        seen.has(
          key
        )
      ) {

        return;
      }


      seen.add(
        key
      );


      unique.push(
        ref
      );
    }
  );


  return unique;
}


// BRICK 310 — SHARED SKILL SEMANTIC RESOLVER
// BRICK 608 — SLOT-AWARE ZERO-PL + CAPPED NONRECURSIVE EXCESS
// BRICK 609 — PARTICIPANT-GENERIC STAMINA / PRE-DEFENCE LOOKUP
// BRICK 613 — GENERIC SOURCE-OWNED FLAT PRE-STAMINA GUARDS
// BRICK 317 — COMPATIBLE SELF-STATE CONSUMPTION
// BRICK 323 — EFFECTIVE PRIMARY DISCIPLINE OUTPUT
// BRICK 324 — AUTHORED BRANCH MULTIPLIERS
// BRICK 325 — PRE-STAMINA DEFENSIVE INTERACTIONS
// BRICK 326 — STAMINA MITIGATION v1
// BRICK 327 — DAMAGE RESOLUTION EVIDENCE
// BRICK 328 — REMAINING BATTLE PL MUTATION
// BRICK 330 — VICTORY BOUNDARY
// BRICK 333 — SEAL STRIKE CONDITION APPLICATION
// BRICK 573 — PERCENTAGE GUARD / SOURCE DETAIL MIGRATION
// BRICK 633 — IMPERIAL MANTLE OVERLOAD ON ACTUAL CONSUMPTION
// BRICK 578 — LIVE EFFECTIVE DISCIPLINE RESOLVER AUTHORITY
// =========================================================

const BATTLE_STAMINA_PIVOT_V1 =
  100;


const BATTLE_PRIMARY_DISCIPLINE_STAT_KEYS = {

  Ninjutsu:
    "nin",

  Taijutsu:
    "tai",

  Genjutsu:
    "gen",

  Bukijutsu:
    "buki",

  "Fūinjutsu":
    "fuin",

  Fuinjutsu:
    "fuin",

  Kinjutsu:
    "kin",

  Stamina:
    "stamina"

};

function getBattleParticipantLiveEffectiveDiscipline(side,participantId,discipline) {
  const statKey=getBattlePrimaryDisciplineStatKey(discipline);
  const participant=getBattleParticipantByIdentity(side,participantId);
  if (!statKey||!participant) return {available:false,side,participantId,discipline,statKey,value:0,source:"missing"};
  let stats=null;
  let source="base_or_runtime_stats";
  if (side==="player") {
    stats=getDevelopedEffectiveCharacterStats(participant);
    source="legitimate_live_effective_state";
  } else {
    stats=participant.stats||participant.baseStats||{};
  }
  const value=Math.max(0,Number(stats&&stats[statKey])||0);
  return {available:true,side,participantId,discipline,statKey,value,source,liveAtResolution:true};
}

function resolveAuthoredDynamicControlStrength(definition={}) {
  const discipline=definition.discipline||null;
  const live=getBattleParticipantLiveEffectiveDiscipline(definition.sourceSide,definition.sourceParticipantId,discipline);
  if (!live.available) return {success:false,reason:"live_effective_discipline_unavailable",...live};
  return {
    success:true,
    strength:live.value,
    discipline,
    statKey:live.statKey,
    source:live.source,
    liveAtResolution:true,
    hiddenControlStatCreated:false
  };
}



function getBattlePrimaryDisciplineStatKey(
  primaryDiscipline
) {


  return (
    BATTLE_PRIMARY_DISCIPLINE_STAT_KEYS[
      primaryDiscipline
    ] ||
    null
  );
}


function getBattleEffectiveStatsForParticipant(
  side,
  participantId
) {
  const participant=getBattleParticipantByIdentity(side,participantId);
  if (!participant) return null;
  if (side==="player") return getDevelopedEffectiveCharacterStats(participant);
  if (side==="enemy") return {...(participant.stats||participant.baseStats||{})};
  return null;
}

function getBattleEffectiveStamina(
  side,
  participantId
) {


  const stats =
    getBattleEffectiveStatsForParticipant(
      side,
      participantId
    );


  return Math.max(
    0,
    Number(
      stats &&
      stats.stamina
    ) || 0
  );
}


function getAcademySkillDamageProfile(
  skill
) {


  if (
    !skill ||
    skill.resolutionKind !==
      "direct_damage" ||
    !skill.damageProfile
  ) {

    return null;
  }


  return skill.damageProfile;
}


function getWeaponExecutionContextForSkill(skill, actor) {
  const requirements=skill && Array.isArray(skill.requirements) ? skill.requirements : [];
  const throwing=requirements.find(requirement=>requirement&&requirement.kind==="persistent_throwing_weapon");
  if (throwing) return getBattleAvailablePersistentThrowingWeaponContext(actor,throwing.allowedWeaponClasses||[]);
  const weaponRequired=requirements.some(requirement=>requirement&&requirement.kind==="weapon_class");
  return weaponRequired ? getBattleEquippedWeaponExecutionContext(actor) : null;
}

function calculateAcademySkillAttackOutput(skill, actor, branch = "normal") {
  const profile=getAcademySkillDamageProfile(skill);
  if (!profile || !actor) return null;
  const statKey=getBattlePrimaryDisciplineStatKey(skill.primaryDiscipline);
  if (!statKey) return null;
  const effectiveStats=getDevelopedEffectiveCharacterStats(actor);
  const effectivePrimaryDiscipline=Math.max(0,Number(effectiveStats[statKey])||0);
  const coefficient=Math.max(0,Number(profile.coefficient)||0);
  const branchMultipliers=profile.branchMultipliers&&typeof profile.branchMultipliers==="object"?profile.branchMultipliers:{};
  const branchMultiplier=branch!=="normal"&&branchMultipliers[branch]!==undefined ? Number(branchMultipliers[branch])||1 : 1;
  const authoredMagnitude=effectivePrimaryDiscipline*coefficient*branchMultiplier;
  const weaponContext=getWeaponExecutionContextForSkill(skill,actor);
  const execution=weaponContext ? getWeaponActionExecutionMultiplier(actor,weaponContext) : {multiplier:1,state:null,severity:null};
  const preDefenseAttackMagnitude=authoredMagnitude*execution.multiplier;
  const attackPL=Math.max(1,Math.round(preDefenseAttackMagnitude));
  return {
    primaryDiscipline:skill.primaryDiscipline, statKey, effectivePrimaryDiscipline, coefficient, branch, branchMultiplier,
    authoredPreExecutionMagnitude:authoredMagnitude,
    weaponExecutionMultiplier:execution.multiplier,
    weaponAcclimationState:execution.state,
    weaponAcclimationSeverity:execution.severity,
    preDefenseAttackMagnitude, attackPL
  };
}

function calculateBattleStaminaMitigationV1(
  resolvedAttackPL,
  effectiveStamina,
  pivot = BATTLE_STAMINA_PIVOT_V1
) {


  const attackPL =
    Math.max(
      0,
      Math.round(
        Number(
          resolvedAttackPL
        ) || 0
      )
    );


  const stamina =
    Math.max(
      0,
      Number(
        effectiveStamina
      ) || 0
    );


  const staminaPivot =
    Math.max(
      1,
      Number(
        pivot
      ) || 100
    );


  if (
    attackPL <= 0
  ) {


    return {

      resolvedAttackPL:
        0,

      effectiveStamina:
        stamina,

      pivot:
        staminaPivot,

      mitigationAmount:
        0,

      finalDamage:
        0

    };
  }


  const calculatedDamage =
    Math.floor(
      attackPL *
      staminaPivot /
      (
        staminaPivot +
        stamina
      )
    );


  const finalDamage =
    Math.max(
      1,
      calculatedDamage
    );


  return {

    resolvedAttackPL:
      attackPL,

    effectiveStamina:
      stamina,

    pivot:
      staminaPivot,

    mitigationAmount:
      Math.max(
        0,
        attackPL -
        finalDamage
      ),

    finalDamage:
      finalDamage

  };
}


function resolveBattlePreStaminaDefense(definition) {
  const incomingAttackPL=Math.max(0,Math.round(Number(definition&&definition.attackPL)||0));
  const result={
    incomingAttackPL,resolvedAttackPL:incomingAttackPL,
    guardingStep:{participated:false,stateId:null,attemptedReduction:0,actualReduction:0},
    enmaGuard:{participated:false,stateId:null,attemptedReduction:0,actualReduction:0,sourceId:null},
    flatGuards:[],
    ratioGuards:[],
    consumedStateIds:[]
  };
  if (!definition||definition.mitigable!==true||!definition.targetSide||!definition.targetParticipantId||incomingAttackPL<=0) return result;

  const rashomon=tryTripleRashomonInterceptIncoming({
    targetSide:definition.targetSide,
    targetParticipantId:definition.targetParticipantId,
    primaryDiscipline:definition.primaryDiscipline||null,
    actionId:definition.actionId||null,
    incomingSkillId:definition.skillId||null,
    sourceSide:definition.sourceSide||null,
    sourceParticipantId:definition.sourceParticipantId||null,
    incomingAuthoredMagnitude:incomingAttackPL,
    mitigable:definition.mitigable===true
  });
  if (rashomon&&rashomon.intercepted===true) {
    result.resolvedAttackPL=0;
    result.rashomonGate={participated:true,...rashomon};
    if (rashomon.stateId) result.consumedStateIds.push(rashomon.stateId);
    return result;
  }

  if (definition.targetSide==="player") {
    const guardingStep=findBattleTransientState({stateKey:"guarding_step",targetSide:"player",targetParticipantId:definition.targetParticipantId});
    if (guardingStep) {
      result.guardingStep.participated=true;
      result.guardingStep.stateId=guardingStep.stateId;
      const attempted=incomingAttackPL>1?Math.max(1,Math.round(incomingAttackPL*0.25)):0;
      const reduced=Math.max(1,result.resolvedAttackPL-attempted);
      result.guardingStep.attemptedReduction=attempted;
      result.guardingStep.actualReduction=Math.max(0,result.resolvedAttackPL-reduced);
      result.resolvedAttackPL=reduced;
      const consumed=consumeBattleTransientState(guardingStep.stateId,"player",definition.targetParticipantId);
      if (consumed) result.consumedStateIds.push(consumed.stateId);
    }

    const enmaGuard=findBattleTransientState({stateKey:"enma_adamantine_guard",targetSide:"player",targetParticipantId:definition.targetParticipantId});
    const enmaFlatReduction=enmaGuard&&enmaGuard.data&&Number.isFinite(Number(enmaGuard.data.guardReduction))?Math.max(0,Number(enmaGuard.data.guardReduction)):0;
    if (enmaGuard&&enmaFlatReduction>0&&result.resolvedAttackPL>0) {
      const authoredReduction=enmaFlatReduction;
      const actual=Math.min(result.resolvedAttackPL,authoredReduction);
      if (actual>0) {
        result.enmaGuard.participated=true;
        result.enmaGuard.stateId=enmaGuard.stateId;
        result.enmaGuard.attemptedReduction=authoredReduction;
        result.enmaGuard.actualReduction=actual;
        result.enmaGuard.sourceId=enmaGuard.ownerRef&&enmaGuard.ownerRef.id?enmaGuard.ownerRef.id:"mk_enma";
        result.resolvedAttackPL=Math.max(0,result.resolvedAttackPL-actual);
        const consumed=consumeBattleTransientState(enmaGuard.stateId,"player",definition.targetParticipantId);
        if (consumed) result.consumedStateIds.push(consumed.stateId);
      }
    }
  }

  const flatGuardStates=ensureBattleRuntimeState().transientStates.filter(state=>
    state&&state.targetRef&&state.targetRef.side===definition.targetSide&&state.targetRef.participantId===definition.targetParticipantId&&
    state.data&&Number.isFinite(Number(state.data.flatPrevention))&&Number(state.data.flatPrevention)>0
  );
  flatGuardStates.forEach(state=>{
    if (result.resolvedAttackPL<=0) return;
    // Legacy Enma flat guards are already processed above when they use guardReduction.
    if (state.stateKey==="enma_adamantine_guard"&&Number.isFinite(Number(state.data.guardReduction))) return;
    const before=result.resolvedAttackPL;
    const authoredReduction=Math.max(0,Math.round(Number(state.data.flatPrevention)||0));
    const actual=Math.min(before,authoredReduction);
    if (actual<=0) return;
    const after=Math.max(0,before-actual);
    result.resolvedAttackPL=after;
    result.flatGuards.push({
      stateId:state.stateId,stateKey:state.stateKey,sourceSkillId:state.data.sourceSkillId||null,
      ownerRef:state.ownerRef?cloneBattleRuntimeValue(state.ownerRef):null,
      sourceRef:state.sourceRef?cloneBattleRuntimeValue(state.sourceRef):null,
      authoredReduction,actualReduction:actual,before,after,participated:true
    });
    if (state.data.oneUse===true) {
      const consumed=consumeBattleTransientState(state.stateId,definition.targetSide,definition.targetParticipantId);
      if (consumed) result.consumedStateIds.push(consumed.stateId);
    }
  });

  const ratioGuardStates=ensureBattleRuntimeState().transientStates.filter(state=>
    state&&state.targetRef&&state.targetRef.side===definition.targetSide&&state.targetRef.participantId===definition.targetParticipantId&&
    state.data&&Number.isFinite(Number(state.data.attackMultiplier))&&Number(state.data.attackMultiplier)>0&&Number(state.data.attackMultiplier)<1
  );
  ratioGuardStates.forEach(state=>{
    if (result.resolvedAttackPL<=0) return;
    const before=result.resolvedAttackPL;
    const after=Math.max(1,Math.round(before*Number(state.data.attackMultiplier)));
    const participated=after<before;
    result.resolvedAttackPL=after;
    const detail={stateId:state.stateId,stateKey:state.stateKey,sourceSkillId:state.data.sourceSkillId||null,ownerRef:state.ownerRef?cloneBattleRuntimeValue(state.ownerRef):null,sourceRef:state.sourceRef?cloneBattleRuntimeValue(state.sourceRef):null,multiplier:Number(state.data.attackMultiplier),preventionRatio:Number.isFinite(Number(state.data.preventionRatio))?Number(state.data.preventionRatio):Math.max(0,1-Number(state.data.attackMultiplier)),participated,before,after,actualReduction:Math.max(0,before-after)};
    result.ratioGuards.push(detail);
    if (participated&&state.data.oneUse===true) {
      const consumed=consumeBattleTransientState(state.stateId,definition.targetSide,definition.targetParticipantId);
      if (consumed) {
        result.consumedStateIds.push(consumed.stateId);
        if (definition.targetSide==="player"&&state.data&&Number(state.data.sovereignOverloadOnConsume)>0) {
          const sovereignActor=getBattleParticipantByIdentity("player",definition.targetParticipantId);
          addKuramaSovereignOverload(sovereignActor,Number(state.data.sovereignOverloadOnConsume),{sourceRefs:[{type:"skill",id:state.data.sourceSkillId||state.stateKey,role:"consumed_defensive_source"}]});
        }
        if (state.data&&state.data.onConsumeCreatesSelfState&&definition.targetSide&&definition.targetParticipantId) {
          const contract=state.data.onConsumeCreatesSelfState;
          const created=addBattleTransientState({
            stateKey:contract.stateKey,
            sourceSide:definition.targetSide,sourceParticipantId:definition.targetParticipantId,
            targetSide:definition.targetSide,targetParticipantId:definition.targetParticipantId,
            ownerRef:{type:"consumed_defensive_source",id:state.data.sourceSkillId||state.stateKey},
            data:{
              remainingActionOpportunities:Math.max(1,Number(contract.remainingActionOpportunities)||1),
              activationActionId:null,
              sourceSkillId:state.data.sourceSkillId||state.stateKey
            }
          });
          if (created) result.consumedStateIds.push(created.stateId);
        }
      }
    }
  });

  return result;
}

// =========================================================
// BRICK 659 — VICTORY COMMITS EXPLICIT OUTCOME
// BRICK 662 — REAL DEFEAT LIFECYCLE
// BRICK 663 — BOSS SUCCESSION PRECEDES VICTORY
// =========================================================
function completeBattleVictoryFromDamage(
  finishingShinobi,
  envelope = null,
  defeatedParticipantId = null
) {
  if (currentBattle.battleOver===true) return currentBattle.rewards;
  const rewardSource=getBattleEncounterEnemy()||currentBattle.enemy||selectedEnemy||null;
  currentBattle.battleOver=true;
  currentBattle.active=false;
  currentBattle.completedAt=Date.now();
  currentBattle.outcome={
    type:"victory",
    committed:true,
    completedAt:currentBattle.completedAt,
    finishingShinobiId:finishingShinobi?finishingShinobi.id:null,
    defeatedParticipantId:defeatedParticipantId||null,
    rewardAuthorityEnemyId:rewardSource?rewardSource.id:null
  };
  currentBattle.defeat=null;
  const rewards=generateBattleRewards(rewardSource,finishingShinobi);
  const mvp=calculateBattleMVP();
  if (rewards&&mvp) rewards.mvp=mvp;
  recordBattleEvidence({
    eventType:"battle_victory",
    actionId:envelope?envelope.actionId:null,
    actorRef:finishingShinobi?createBattleParticipantRef("player",finishingShinobi.id):null,
    targetRef:defeatedParticipantId?createBattleParticipantRef("enemy",defeatedParticipantId):null,
    data:{enemyRemainingBattlePL:0,finishingShinobiId:finishingShinobi?finishingShinobi.id:null,enemyDeploymentExhausted:true,rewardAuthorityEnemyId:rewardSource?rewardSource.id:null,outcomeCommitted:true}
  });
  // Victory presentation still expects an enemy compatibility object.
  currentBattle.enemy=rewardSource;
  saveTestState();
  openOverlay("victory");
  return rewards;
}

function completeBattleDefeat(defeatedParticipantId=null,envelope=null,reason="player_deployment_exhausted") {
  if (currentBattle.battleOver===true) return currentBattle.outcome;
  const completedAt=Date.now();
  currentBattle.battleOver=true;
  currentBattle.active=false;
  currentBattle.completedAt=completedAt;
  currentBattle.claimedAt=null;
  currentBattle.completionRecorded=false;
  currentBattle.outcome={
    type:"defeat",
    committed:true,
    completedAt,
    reason,
    defeatedParticipantId:defeatedParticipantId||null,
    rewardsGenerated:false,
    rewardClaimAvailable:false,
    historyPreserved:true
  };
  currentBattle.defeat=cloneBattleRuntimeValue(currentBattle.outcome);

  if (Array.isArray(currentBattle.battleLog)) {
    currentBattle.battleLog.push("All deployed shinobi have reached 0 Battle PL. DEFEAT.");
  }

  recordBattleEvidence({
    eventType:"battle_defeat",
    actionId:envelope&&envelope.actionId?envelope.actionId:null,
    targetRef:defeatedParticipantId?createBattleParticipantRef("player",defeatedParticipantId):null,
    data:{
      reason,
      playerDeploymentExhausted:true,
      outcomeCommitted:true,
      rewardsGenerated:false,
      rewardClaimAvailable:false,
      historyRollback:false
    }
  });

  saveTestState();

  // BRICK 740 — Story-owned defeat resumes the same authored caller rather
  // than silently falling into a generic Battle catalogue. Ordinary Battles
  // keep their existing behaviour because they have no story returnContext.
  if (currentBattle.returnContext && currentBattle.returnContext.type === "story_scene") {
    resumeBattleCallerAfterCompletion("defeat");
  }

  return currentBattle.outcome;
}

function handleBattleParticipantAtZeroPL(
  side,
  participantId,
  actor,
  envelope
) {
  if (!side||!participantId) return null;
  const slotNumber=getBattleDeploymentParticipantSlotNumber(side,participantId);
  if (!slotNumber) return null;

  if (side==="enemy") {
    const bossTransition=tryAdvanceAuthoritativeBossStage(participantId,envelope||null);
    if (bossTransition&&bossTransition.success===true) return bossTransition;

    const transition=advanceBattleParticipantAtZeroPL(side,participantId);
    if (hasBattleDeploymentParticipants("enemy")) return transition;
    return completeBattleVictoryFromDamage(actor,envelope,participantId);
  }

  if (side==="player") {
    const transition=advanceBattleParticipantAtZeroPL(side,participantId);
    if (hasBattleDeploymentParticipants("player")) return transition;
    completeBattleDefeat(participantId,envelope||null,"player_deployment_exhausted");
    return transition||currentBattle.outcome;
  }

  return advanceBattleParticipantAtZeroPL(side,participantId);
}

function resolveSingleBattleDamageSegment(definition, segmentIndex = 0) {
  if (!definition || !definition.actorSide || !definition.actorParticipantId || !definition.targetSide || !definition.targetParticipantId || !definition.output) return null;
  const targetRecord=getBattleRemainingPLRecord(definition.targetSide,definition.targetParticipantId);
  if (!targetRecord) return null;
  const preDefense=resolveBattlePreStaminaDefense({attackPL:definition.output.attackPL,mitigable:definition.mitigable===true,targetSide:definition.targetSide,targetParticipantId:definition.targetParticipantId,primaryDiscipline:definition.output.primaryDiscipline||null,skillId:definition.skill&&definition.skill.id||null,actionId:definition.envelope&&definition.envelope.actionId||null,sourceSide:definition.actorSide||null,sourceParticipantId:definition.actorParticipantId||null});
  const effectiveStamina=getBattleEffectiveStamina(definition.targetSide,definition.targetParticipantId);
  const staminaResolution=calculateBattleStaminaMitigationV1(preDefense.resolvedAttackPL,effectiveStamina);
  const absorption=absorbBattleDamageBearingCapacity(definition.targetSide,definition.targetParticipantId,staminaResolution.finalDamage);
  const stateRefs=[...(Array.isArray(definition.stateRefs)?definition.stateRefs:[]),...preDefense.consumedStateIds];
  const evidence=recordBattleEvidence({
    eventType:"damage_resolved",actionId:definition.envelope?definition.envelope.actionId:null,
    actorRef:createBattleParticipantRef(definition.actorSide,definition.actorParticipantId),
    targetRef:createBattleParticipantRef(definition.targetSide,definition.targetParticipantId),
    skillId:definition.skill?definition.skill.id:null,
    sourceRefs:definition.envelope&&Array.isArray(definition.envelope.sourceRefs)?definition.envelope.sourceRefs:[],stateRefs,
    data:{
      excessDamageSegmentIndex:segmentIndex,
      continuationSegment:segmentIndex>0,
      primaryDiscipline:definition.output.primaryDiscipline,
      primaryDisciplineStatKey:definition.output.statKey,
      effectivePrimaryDiscipline:definition.output.effectivePrimaryDiscipline,
      authoredCoefficient:segmentIndex===0?definition.output.coefficient:null,
      branch:segmentIndex===0?definition.output.branch:"excess_damage_continuation",
      branchMultiplier:segmentIndex===0?definition.output.branchMultiplier:null,
      authoredPreExecutionMagnitude:segmentIndex===0?definition.output.authoredPreExecutionMagnitude:null,
      weaponExecutionMultiplier:segmentIndex===0?definition.output.weaponExecutionMultiplier:null,
      preDefenseAttackMagnitude:definition.output.preDefenseAttackMagnitude,
      preDefenseAttackPL:definition.output.attackPL,
      guardingStepParticipated:preDefense.guardingStep.participated,
      guardingStepActualReduction:preDefense.guardingStep.actualReduction,
      enmaGuardParticipated:preDefense.enmaGuard.participated,
      enmaGuardActualReduction:preDefense.enmaGuard.actualReduction,
      flatGuards:Array.isArray(preDefense.flatGuards)?cloneBattleRuntimeValue(preDefense.flatGuards):[],
      ratioGuards:Array.isArray(preDefense.ratioGuards)?cloneBattleRuntimeValue(preDefense.ratioGuards):[],
      resolvedAttackPL:preDefense.resolvedAttackPL,
      effectiveStamina:staminaResolution.effectiveStamina,
      staminaPivot:staminaResolution.pivot,
      staminaMitigationAmount:staminaResolution.mitigationAmount,
      finalDamage:staminaResolution.finalDamage,
      temporaryCapacityBefore:absorption.temporaryCapacityBefore,
      temporaryCapacityAbsorbed:absorption.temporaryCapacityAbsorbed,
      temporaryCapacityAfter:absorption.temporaryCapacityAfter,
      remainingBattlePLBefore:absorption.underlyingBattlePLBefore,
      remainingBattlePLAfter:absorption.underlyingBattlePLAfter,
      absorbedPL:absorption.absorbedPL,
      residualAttackPL:absorption.residualAttackPL,
      mechanicalPacketCount:definition.skill&&definition.skill.mechanicalPacketCount?definition.skill.mechanicalPacketCount:1
    }
  });
  const actor=getBattleParticipantByIdentity(definition.actorSide,definition.actorParticipantId);
  if (definition.actorSide==="player"&&definition.targetSide==="enemy"&&actor) recordBattleContribution(actor,absorption.absorbedPL,definition.output.statKey);
  currentBattle.lastDamage=absorption.absorbedPL;
  if (Array.isArray(currentBattle.battleLog)) {
    const g=preDefense.guardingStep.participated?` Guard blocked ${preDefense.guardingStep.actualReduction}.`:"";
    const e=preDefense.enmaGuard.participated?` Enma blocked ${preDefense.enmaGuard.actualReduction}.`:"";
    const f=Array.isArray(preDefense.flatGuards)&&preDefense.flatGuards.some(guard=>guard.participated)?` Flat guard prevented ${preDefense.flatGuards.reduce((sum,guard)=>sum+(Number(guard.actualReduction)||0),0)}.`:"";
    const r=Array.isArray(preDefense.ratioGuards)&&preDefense.ratioGuards.some(guard=>guard.participated)?` Ratio guard reduced to ${preDefense.resolvedAttackPL}.`:"";
    const t=absorption.temporaryCapacityAbsorbed>0?` Temporary capacity absorbed ${absorption.temporaryCapacityAbsorbed}.`:"";
    currentBattle.battleLog.push(`Attack ${definition.output.attackPL}.${g}${e}${f}${r} Stamina blocked ${staminaResolution.mitigationAmount}.${t} ${absorption.absorbedPL} capacity lost.`);
  }
  let zeroResult=null;
  if (absorption.totalCapacityAfter<=0) zeroResult=handleBattleParticipantAtZeroPL(definition.targetSide,definition.targetParticipantId,actor,definition.envelope||null);
  return {evidence,output:definition.output,preDefense,stamina:staminaResolution,absorption,
    finalDamage:staminaResolution.finalDamage,absorbedPL:absorption.absorbedPL,residualAttackPL:absorption.residualAttackPL,
    remainingBattlePLBefore:absorption.underlyingBattlePLBefore,remainingBattlePLAfter:absorption.underlyingBattlePLAfter,zeroResult};
}

function resolveBattleDamagePacket(definition) {
  if (!definition||!definition.output) return null;

  const primary=resolveSingleBattleDamageSegment(definition,0);
  if (!primary) return null;

  const segments=[primary];
  const excessContract=definition.excess||(definition.skill&&definition.skill.excess)||null;
  const excessEligible=!!(excessContract&&excessContract.eligible===true);
  let excessResolution=null;

  if (excessEligible) {
    const capRatio=Math.max(0,Math.min(1,Number(excessContract.capRatio)||0));
    const authoredPrimaryAttackPL=Math.max(0,Math.round(Number(definition.output.attackPL)||0));
    const rawExcess=Math.max(0,Math.round(Number(primary.residualAttackPL)||0));
    const ratioCapAmount=Math.max(0,Math.floor(authoredPrimaryAttackPL*capRatio));
    const absoluteCap=Number.isFinite(Number(excessContract.absoluteCap))?Math.max(0,Math.floor(Number(excessContract.absoluteCap))):null;
    const capAmount=absoluteCap===null?ratioCapAmount:Math.min(ratioCapAmount,absoluteCap);
    let cappedExcess=Math.min(rawExcess,capAmount);
    const transition=primary.zeroResult&&primary.zeroResult.type==="withdrawal_queue_advance"?primary.zeroResult:null;
    const continuationTargetId=transition&&transition.replacementParticipantId?transition.replacementParticipantId:null;

    excessResolution={
      eligible:true,
      capRatio,
      ratioCapAmount,
      absoluteCap,
      capAmount,
      rawExcess,
      cappedExcess,
      primaryTargetParticipantId:definition.targetParticipantId,
      continuationTargetParticipantId:continuationTargetId,
      continued:false,
      nonRecursive:true
    };

    if (cappedExcess>0&&continuationTargetId&&!currentBattle.battleOver) {
      const continuationOutput={
        ...definition.output,
        attackPL:cappedExcess,
        preDefenseAttackMagnitude:cappedExcess,
        coefficient:null,
        branch:"capped_excess_continuation",
        branchMultiplier:null,
        authoredPreExecutionMagnitude:null,
        weaponExecutionMultiplier:null
      };
      const continuation=resolveSingleBattleDamageSegment({...definition,targetParticipantId:continuationTargetId,output:continuationOutput,excess:null},1);
      if (continuation) {
        segments.push(continuation);
        excessResolution.continued=true;
        excessResolution.continuationAbsorbedPL=continuation.absorbedPL;
        excessResolution.continuationFinalDamage=continuation.finalDamage;
      }
    }

    recordBattleEvidence({
      eventType:"capped_excess_damage_resolved",
      actionId:definition.envelope?definition.envelope.actionId:null,
      actorRef:createBattleParticipantRef(definition.actorSide,definition.actorParticipantId),
      targetRef:createBattleParticipantRef(definition.targetSide,definition.targetParticipantId),
      skillId:definition.skill?definition.skill.id:null,
      sourceRefs:definition.envelope&&Array.isArray(definition.envelope.sourceRefs)?definition.envelope.sourceRefs:[],
      data:{...excessResolution,crossTargetPooling:false,reappliedTechniqueCoefficient:false,reappliedSourceCost:false,recursiveContinuation:false}
    });
  }

  const last=segments[segments.length-1];
  return {
    ...primary,
    segments,
    excessResolution,
    remainingBattlePLAfter:last.remainingBattlePLAfter,
    residualAttackPL:last.residualAttackPL
  };
}

