function attemptClosureWaveBattleSkill(skillId,targetParticipantId=null,options={}) {
  const actor=getBattleDeploymentParticipant("player",1);
  const skill=actor?getClosureWaveBattleSkillDefinition(skillId,actor):null;
  const enemy=getBattleDeploymentParticipant("enemy",1);
  if (!actor||!skill) return {success:false,reason:"skill_or_actor_missing"};
  let target=null,targetSide="player";
  if (["current_enemy","branch_selected"].includes(skill.targetMode)) { target=enemy; targetSide="enemy"; }
  else if (skill.targetMode==="active_enemies") { target=enemy; targetSide="enemy"; }
  else if (skill.targetMode==="selected_ally") { target=targetParticipantId?getBattleParticipantByIdentity("player",targetParticipantId):actor; targetSide="player"; }
  else { target=actor; targetSide="player"; }
  const availability=evaluateClosureWaveSkillAvailability(skill,actor,target);
  if (!availability.available) return {success:false,reason:availability.reason,availability};
  if (skill.requiresExplicitModeSelection===true) {
    const availableModes=Array.isArray(skill.availableModes)?skill.availableModes:Object.keys(skill.modes||{});
    if (!(options&&options.mode&&availableModes.includes(options.mode))) return {success:false,reason:"branch_selection_required",availableModes:[...availableModes]};
  }
  if (skill.categorical&&skill.categorical.reactiveOnly===true) return {success:false,reason:"reactive_window_required"};
  const sourceRefs=getFactorySkillSourceRefs(skill,actor);
  const envelope=createBattleActionEnvelope({actorSide:"player",actorParticipantId:actor.id,targetSide,targetParticipantId:target?target.id:null,actionClass:skill.actionClass,skillId:skill.id,sourceRefs,data:{primaryDiscipline:skill.primaryDiscipline,traits:[...(skill.traits||[])],representationCategoryNotOntology:true}});
  const entry=beginBattleActionResolution(envelope);
  if (!entry.accepted) return {success:false,reason:entry.validation.reason,entry};
  const mirror=resolveAlphaBlackMirrorInterferenceIfApplicable(skill,envelope,actor,target);
  const resolution=mirror&&mirror.interfered===true?mirror.resolution:resolveClosureWaveSkillSemantics(skill,envelope,actor,target,options||{});
  const secondarySemantics=resolveAlphaCharacterSkillSecondaryConsumers(skill,envelope,actor,target,resolution,options||{});
  const narutoV2Instability=advanceNarutoV2InstabilityAfterCompletedSkill(actor,skill,envelope,resolution,options||{});
  let baryonContactErosion=null;
  if(resolution&&resolution.resolved===true&&skill.contactErosion&&skill.contactErosion.eligible===true&&options&&options.qualifyingContact===true&&target&&targetSide==="enemy") baryonContactErosion=recordBaryonContactErosionOccurrence({actorSide:"player",actorParticipantId:actor.id,targetSide:"enemy",targetParticipantId:target.id,actionId:envelope.actionId,skillId:skill.id,qualifyingContactConfirmed:true});
  recordBattleEvidence({eventType:"skill_action_completed",committedOccurrence:true,actionId:envelope.actionId,actorRef:envelope.actorRef,targetRef:envelope.targetRef,skillId:skill.id,sourceRefs:envelope.sourceRefs,stateRefs:[...(resolution.stateRefs||[]),...((secondarySemantics&&secondarySemantics.stateRefs)||[])],conditionRefs:[...(resolution.conditionRefs||[]),...((secondarySemantics&&secondarySemantics.conditionRefs)||[])],data:{resolved:resolution.resolved===true,branch:resolution.branch||null,damageApplied:resolution.damageApplied===true,finalDamage:Number(resolution.finalDamage)||0,sourceIdentityMerge:false,entityPLTransfer:false,secondarySemanticsApplied:secondarySemantics&&secondarySemantics.appliedIds||[],blackMirrorInterference:!!(mirror&&mirror.interfered===true)}});
  if (resolution.resolved===true) consumeBattleActionOpportunity("player",actor.id,envelope.actionId,"valid_action_completed");
  const catastrophicDisruption=resolveKamatariCatastrophicDisruptionFromCommittedAction({envelope,resolution,actionTraits:skill.traits||[]});
  saveTestState();
  if (!currentBattle.battleOver) openOverlay("combat");
  return {success:resolution.resolved===true,envelope,resolution,secondarySemantics,mirror,narutoV2Instability,baryonContactErosion,catastrophicDisruption};
}

// =========================================================
// BRICK 876 — MENMA ORIGIN COMBAT READS
// =========================================================
const MENMA_ORIGIN_TUTORIAL_ENCOUNTER_ID="origin_academy_menma_prologue:altered_shinobi";

function isMenmaOriginTutorialBattle() {
  return currentBattle&&currentBattle.encounterId===MENMA_ORIGIN_TUTORIAL_ENCOUNTER_ID&&currentBattle.encounterEnemy&&currentBattle.encounterEnemy.id==="test_subject_altered_shinobi";
}

function getMenmaOriginBattleEvidence(records=null) {
  const evidence=Array.isArray(records)?records:((currentBattle.runtime&&Array.isArray(currentBattle.runtime.evidence))?currentBattle.runtime.evidence:[]);
  return evidence.filter(record=>record&&record.battleId===currentBattle.battleId);
}

function getMenmaOriginActionDefinition(skillId) {
  if (!skillId) return null;
  return getClosureWaveBattleSkillDefinition(skillId,"academy_menma")||getAcademyBattleSkillDefinition(skillId)||null;
}

function isMenmaOriginKinjutsuObservationQualifyingSkill(skill) {
  if (!skill) return false;
  if (skill.primaryDiscipline==="Kinjutsu") return true;
  return Array.isArray(skill.traits)&&skill.traits.includes("kinjutsu_observation_qualifying");
}

function resolveMenmaOriginKinjutsuObservationRead(records=null) {
  const evidence=getMenmaOriginBattleEvidence(records);
  if (!isMenmaOriginTutorialBattle()) return {observed:false,occurrenceIds:[],reason:"not_menma_origin_tutorial"};
  if (getBattleContextFact("menma_origin_anko_observation_blocked")===true) return {observed:false,occurrenceIds:[],reason:"observation_blocked"};
  const qualifying=evidence.filter(record=>
    record&&record.eventType==="skill_action_completed"&&record.committedOccurrence===true&&
    record.actorRef&&record.actorRef.side==="player"&&record.actorRef.participantId==="academy_menma"&&
    isMenmaOriginKinjutsuObservationQualifyingSkill(getMenmaOriginActionDefinition(record.skillId))
  );
  return {
    observed:qualifying.length>0,
    occurrenceIds:qualifying.map(record=>record.evidenceId),
    observerScope:"anko_peripheral_clearing",
    legitimateObserverAccess:true,
    perceptible:true,
    ownershipAloneNeverQualifies:true
  };
}

function resolveMenmaOriginTutorialPerformance(records=null,outcomeOverride=null) {
  const evidence=getMenmaOriginBattleEvidence(records);
  const startMaximum=Math.max(1,Number(getBattleMaximumPL("player","academy_menma"))||0);
  const damageRecords=evidence.filter(record=>record&&record.eventType==="damage_resolved"&&record.targetRef&&record.targetRef.side==="player"&&record.targetRef.participantId==="academy_menma");
  const grossFinalPLDamageReceived=damageRecords.reduce((sum,record)=>sum+Math.max(0,Number(record.data&&record.data.finalDamage)||0),0);
  const pressureRatio=grossFinalPLDamageReceived/startMaximum;
  const criticalThreshold=startMaximum*0.25;
  const criticalExposure=damageRecords.some(record=>Number(record.data&&record.data.remainingBattlePLAfter)<=criticalThreshold);

  const playerCompletionRecords=evidence.filter(record=>record&&record.actionId&&record.actorRef&&record.actorRef.side==="player"&&record.actorRef.participantId==="academy_menma"&&["skill_action_completed","item_action_completed","summon_skill_resolved_and_returned"].includes(record.eventType));
  const actionIds=[...new Set(playerCompletionRecords.map(record=>record.actionId))];
  let meaningful=0;
  actionIds.forEach(actionId=>{
    const recordsForAction=playerCompletionRecords.filter(record=>record.actionId===actionId);
    const completion=recordsForAction.find(record=>record.eventType==="skill_action_completed")||recordsForAction.find(record=>record.eventType==="summon_skill_resolved_and_returned")||recordsForAction.find(record=>record.eventType==="item_action_completed")||null;
    if (!completion) return;
    if (completion.eventType==="item_action_completed") { if (completion.data&&completion.data.resolved===true) meaningful+=1; return; }
    const data=completion.data||{};
    if (data.damageApplied===true) { if (Number(data.finalDamage)>0) meaningful+=1; return; }
    if ((completion.stateRefs&&completion.stateRefs.length>0)||(completion.conditionRefs&&completion.conditionRefs.length>0)) { meaningful+=1; return; }
    if (data.resolved===true) meaningful+=1;
  });
  const committedMenmaActionOpportunities=actionIds.length;
  const actionExecutionRatio=committedMenmaActionOpportunities>0?meaningful/committedMenmaActionOpportunities:0;
  const outcome=outcomeOverride||(currentBattle.outcome&&currentBattle.outcome.type)||null;
  const opponentStopped=outcome==="victory"&&getBattleRemainingPL("enemy","test_subject_altered_shinobi")<=0;
  const tutorialResult=opponentStopped?"completed":"not_completed";
  let performanceBucket=null;
  if (tutorialResult==="completed") {
    if (pressureRatio<=0.30&&criticalExposure!==true&&actionExecutionRatio>=0.75) performanceBucket="high";
    else if (pressureRatio>0.65||criticalExposure===true||actionExecutionRatio<0.50) performanceBucket="low";
    else performanceBucket="middle";
  }
  const supportingOccurrenceIds=[...new Set([
    ...damageRecords.map(record=>record.evidenceId),
    ...playerCompletionRecords.filter(record=>record.committedOccurrence===true||record.eventType==="item_action_completed").map(record=>record.evidenceId)
  ].filter(Boolean))];
  return {
    startingUnderlyingBattlePLMaximum:startMaximum,
    grossFinalPLDamageReceived,
    pressureRatio,
    criticalExposure,
    committedMenmaActionOpportunities,
    meaningfullyResolvedMenmaActions:meaningful,
    actionExecutionRatio,
    tutorialResult,
    performanceBucket,
    supportingOccurrenceIds,
    healingDoesNotRewriteHistoricalDamage:true
  };
}

function createMenmaOriginTutorialResultProjection({outcome,getEvidence}={}) {
  const performance=resolveMenmaOriginTutorialPerformance(typeof getEvidence==="function"?getEvidence():null,outcome&&outcome.type||null);
  const kinjutsu=resolveMenmaOriginKinjutsuObservationRead(typeof getEvidence==="function"?getEvidence():null);
  return {...performance,observedKinjutsu:kinjutsu.observed===true,kinjutsuObservationOccurrenceIds:[...(kinjutsu.occurrenceIds||[])]};
}

function recordMenmaOriginPostBattleReads() {
  if (!isMenmaOriginTutorialBattle()) return {success:false,reason:"not_menma_origin_tutorial"};
  const performance=resolveMenmaOriginTutorialPerformance();
  const kinjutsu=resolveMenmaOriginKinjutsuObservationRead();
  const existing=(currentBattle.runtime&&Array.isArray(currentBattle.runtime.evidence)?currentBattle.runtime.evidence:[]).find(record=>record&&record.eventType==="menma_origin_tutorial_read_resolved"&&record.battleId===currentBattle.battleId);
  if (existing) return {success:true,idempotent:true,evidence:existing,performance,kinjutsu};
  const evidence=recordBattleEvidence({
    eventType:"menma_origin_tutorial_read_resolved",committedOccurrence:false,
    actorRef:createBattleParticipantRef("player","academy_menma"),
    sourceRefs:[{type:"story_scene",id:"origin_academy_menma_prologue",role:"authored_tutorial_context"}],
    data:{performanceBucket:performance.performanceBucket,tutorialResult:performance.tutorialResult,pressureRatio:performance.pressureRatio,criticalExposure:performance.criticalExposure,actionExecutionRatio:performance.actionExecutionRatio,observedKinjutsu:kinjutsu.observed===true,supportingOccurrenceIds:performance.supportingOccurrenceIds,kinjutsuObservationOccurrenceIds:kinjutsu.occurrenceIds||[]}
  });
  return {success:!!evidence,evidence,performance,kinjutsu};
}

// =========================================================
// BRICK 686 — COMBAT ALPHA GENERIC ENEMY ACTION AUTHORITY
// BRICK 687 — ALPHA BOSS ACTION PACKAGE INGESTION
// BRICK 688 — RANDOMNESS ONLY AFTER SEMANTIC ELIGIBILITY
// =========================================================
// Coding owns scheduling. Combat owns concrete action authority.
// Enemy power/Rank/Stamina never derive an un-authored Attack PL.

function makeEnemyFixedDamageAction(id,authoredAttackPL,options={}) {
  return {
    id,skillId:id,actionClass:options.actionClass||"enemy_authored_action",
    traits:[...(options.traits||[])],
    evaluateAvailability:typeof options.evaluateAvailability==="function"?options.evaluateAvailability:null,
    resolve({enemy,target,envelope}) {
      const attackPL=Math.max(0,Math.round(Number(authoredAttackPL)||0));
      if (!enemy||!target||attackPL<=0) return {resolved:false,reason:"enemy_fixed_damage_contract_missing"};
      const skill={id,excess:options.excess||null,mechanicalPacketCount:1};
      const output={primaryDiscipline:options.primaryDiscipline||null,statKey:getBattlePrimaryDisciplineStatKey(options.primaryDiscipline),effectivePrimaryDiscipline:null,coefficient:null,branch:"fixed_authored_enemy_output",branchMultiplier:1,authoredPreExecutionMagnitude:attackPL,weaponExecutionMultiplier:1,preDefenseAttackMagnitude:attackPL,attackPL,fixedCalibration:true};
      const damage=resolveBattleDamagePacket({envelope,skill,actorSide:"enemy",actorParticipantId:enemy.id,targetSide:"player",targetParticipantId:target.id,output,mitigable:options.staminaMitigation!==false,excess:options.excess||null,stateRefs:[]});
      if (!damage) return {resolved:false,reason:"enemy_damage_resolution_failed"};
      if (options.dynamicControlRider&&damage.remainingBattlePLAfter>0) {
        if (options.dynamicControlRider.requiresExplicitQualification===true) {
          recordBattleEvidence({eventType:"enemy_control_rider_available_not_automatic",actionId:actionIdOrNull(envelope),actorRef:createBattleParticipantRef("enemy",enemy.id),targetRef:createBattleParticipantRef("player",target.id),skillId:id,data:{semanticClass:options.dynamicControlRider.semanticClass||null,damageSuccessDoesNotGuaranteeControl:true,requiresExplicitQualification:true}});
        } else {
          establishEnemyDynamicControlState(enemy,target,envelope,id,options.dynamicControlRider);
        }
      }
      return {resolved:true,branch:"fixed_enemy_damage",damageApplied:true,damage,finalDamage:damage.finalDamage,excessResolution:damage.excessResolution||null};
    }
  };
}

function makeEnemyAreaDamageAction(id,authoredAttackPLPerTarget,maxTargets=3,options={}) {
  return {
    id,skillId:id,actionClass:options.actionClass||"enemy_authored_action",
    traits:[...(options.traits||[]),"one_authored_area_action"],
    evaluateAvailability:typeof options.evaluateAvailability==="function"?options.evaluateAvailability:null,
    resolve({enemy,envelope}) {
      if (!enemy) return {resolved:false,reason:"enemy_area_actor_missing"};
      const targetIds=getFactoryActiveTargetIds("player",maxTargets);
      const results=[];
      targetIds.forEach(targetId=>{
        const attackPL=Math.max(0,Math.round(Number(authoredAttackPLPerTarget)||0));
        const output={primaryDiscipline:options.primaryDiscipline||null,statKey:getBattlePrimaryDisciplineStatKey(options.primaryDiscipline),effectivePrimaryDiscipline:null,coefficient:null,branch:"fixed_authored_enemy_area_output",branchMultiplier:1,authoredPreExecutionMagnitude:attackPL,weaponExecutionMultiplier:1,preDefenseAttackMagnitude:attackPL,attackPL,fixedCalibration:true,perTarget:true};
        const perTargetExcess=options.excess?{...options.excess,absoluteCap:Number.isFinite(Number(options.excess.absoluteCapPerTarget))?Number(options.excess.absoluteCapPerTarget):options.excess.absoluteCap}:null;
        const damage=resolveBattleDamagePacket({envelope,skill:{id,excess:perTargetExcess,mechanicalPacketCount:1},actorSide:"enemy",actorParticipantId:enemy.id,targetSide:"player",targetParticipantId:targetId,output,mitigable:options.staminaMitigation!==false,excess:perTargetExcess,stateRefs:[]});
        if (damage) results.push({targetParticipantId:targetId,damage});
      });
      return {resolved:results.length>0,branch:"enemy_area_damage",damageApplied:results.length>0,areaResults:results,crossTargetPooling:false};
    }
  };
}

function makeEnemyRatioGuardAction(id,preventionRatio,options={}) {
  const ratio=Math.max(0,Math.min(1,Number(preventionRatio)||0));
  return {
    id,skillId:id,actionClass:"enemy_defensive_technique",traits:[...(options.traits||[])],
    evaluateAvailability:typeof options.evaluateAvailability==="function"?options.evaluateAvailability:null,
    resolve({enemy,envelope}) {
      if (!enemy) return {resolved:false,reason:"enemy_guard_actor_missing"};
      const existing=findBattleTransientState({stateKey:options.stateKey||id,targetSide:"enemy",targetParticipantId:enemy.id});
      if (existing) removeBattleTransientState(existing.stateId);
      const state=addBattleTransientState({
        stateKey:options.stateKey||id,
        sourceSide:"enemy",sourceParticipantId:enemy.id,
        targetSide:"enemy",targetParticipantId:enemy.id,
        ownerRef:{type:"skill",id},
        data:{
          sourceSkillId:id,attackMultiplier:1-ratio,preventionRatio:ratio,oneUse:true,
          activationActionId:envelope?actionIdOrNull(envelope):null,
          onConsumeCreatesSelfState:options.onConsumeCreatesSelfState||null
        }
      });
      return {resolved:!!state,branch:"enemy_ratio_guard",damageApplied:false,stateRefs:state?[state.stateId]:[]};
    }
  };
}

function actionIdOrNull(envelope) {
  return envelope&&envelope.actionId?envelope.actionId:null;
}

function establishEnemyDynamicControlState(enemy,target,envelope,skillId,contract={}) {
  if (!enemy||!target||!contract.discipline) return null;
  const gateInterception=tryTripleRashomonInterceptIncoming({targetSide:"player",targetParticipantId:target.id,primaryDiscipline:contract.discipline,actionId:envelope?actionIdOrNull(envelope):null,incomingSkillId:skillId});
  if (gateInterception&&gateInterception.intercepted===true) return {stateId:gateInterception.stateId||null,intercepted:true,semanticClass:contract.semanticClass||"authored_control"};
  const live=resolveAuthoredDynamicControlStrength({sourceSide:"enemy",sourceParticipantId:enemy.id,discipline:contract.discipline});
  if (!live.success) return null;
  const multiplier=Number.isFinite(Number(contract.multiplier))?Number(contract.multiplier):1;
  const strength=Math.max(0,Math.round(live.strength*multiplier));
  const state=addBattleTransientState({
    stateKey:contract.stateKey||contract.semanticClass||skillId,
    sourceSide:"enemy",sourceParticipantId:enemy.id,
    targetSide:"player",targetParticipantId:target.id,
    ownerRef:{type:"skill",id:skillId},
    data:{
      resolverDiscipline:contract.discipline,resolverStrength:strength,liveAtResolution:true,
      semanticClass:contract.semanticClass||"authored_control",blanketStun:false,
      remainingActionOpportunities:Number.isFinite(Number(contract.durationActionOpportunities))?Math.max(1,Number(contract.durationActionOpportunities)):undefined,
      activationActionId:envelope?actionIdOrNull(envelope):null
    }
  });
  recordBattleEvidence({eventType:"enemy_dynamic_control_resolved",actionId:actionIdOrNull(envelope),actorRef:createBattleParticipantRef("enemy",enemy.id),targetRef:createBattleParticipantRef("player",target.id),skillId, stateRefs:state?[state.stateId]:[],data:{resolverDiscipline:contract.discipline,resolverStrength:strength,semanticClass:contract.semanticClass||"authored_control",blanketStun:false}});
  return state;
}

function makeEnemyDynamicControlAction(id,discipline,options={}) {
  return {
    id,skillId:id,actionClass:"enemy_control_technique",traits:[...(options.traits||[])],
    evaluateAvailability:typeof options.evaluateAvailability==="function"?options.evaluateAvailability:null,
    resolve({enemy,target,envelope}) {
      const targets=(Number(options.maxTargets)||1)>1
        ? getFactoryActiveTargetIds("player",options.maxTargets).map(targetId=>getBattleParticipantByIdentity("player",targetId)).filter(Boolean)
        : [target].filter(Boolean);
      const states=targets.map(item=>establishEnemyDynamicControlState(enemy,item,envelope,id,{discipline,multiplier:options.multiplier,semanticClass:options.semanticClass,stateKey:options.stateKey,durationActionOpportunities:options.durationActionOpportunities})).filter(Boolean);
      return {resolved:states.length>0,branch:"enemy_dynamic_control",damageApplied:false,stateRefs:states.map(state=>state.stateId)};
    }
  };
}

function makeEnemyCategoricalAction(id,options={}) {
  return {
    id,skillId:id,actionClass:options.actionClass||"enemy_context_technique",traits:[...(options.traits||[])],
    evaluateAvailability:typeof options.evaluateAvailability==="function"?options.evaluateAvailability:null,
    resolve({enemy,target,envelope}) {
      recordBattleEvidence({eventType:"enemy_categorical_action_resolved",actionId:actionIdOrNull(envelope),actorRef:enemy?createBattleParticipantRef("enemy",enemy.id):null,targetRef:target?createBattleParticipantRef("player",target.id):null,skillId:id,data:{informationBoundary:options.informationBoundary||null,automaticAttackPL:0,genericSpeedModifier:false,genericAccuracyModifier:false,independentParticipantCreated:false}});
      return {resolved:true,branch:"enemy_categorical",damageApplied:false,stateRefs:[]};
    }
  };
}

function makeEnemyRestorationAction(id,amount,options={}) {
  return {
    id,skillId:id,actionClass:"enemy_restorative_technique",traits:[...(options.traits||[])],
    evaluateAvailability:typeof options.evaluateAvailability==="function"?options.evaluateAvailability:null,
    resolve({enemy,envelope}) {
      const restoration=enemy?restoreUnderlyingBattlePLFromSkill("enemy",enemy.id,amount):null;
      if (!restoration||!restoration.success) return {resolved:false,reason:restoration&&restoration.reason||"enemy_restoration_failed"};
      recordBattleEvidence({eventType:"enemy_battle_pl_restored",actionId:actionIdOrNull(envelope),actorRef:createBattleParticipantRef("enemy",enemy.id),skillId:id,data:{requested:amount,restored:restoration.restored,underlyingOnly:true,historyRollback:false}});
      return {resolved:true,branch:"enemy_restoration",damageApplied:false,restoration};
    }
  };
}

function makeEnemyTwoStageAreaAction(id,collapseAttackPL,maxTargets,options={}) {
  const stateKey=options.stateKey||`${id}_committed`;
  return {
    id,skillId:id,actionClass:"enemy_committed_technique",traits:["committed_two_stage_action",...(options.traits||[])],
    resolve({enemy,envelope}) {
      const existing=findBattleTransientState({stateKey,targetSide:"enemy",targetParticipantId:enemy.id});
      if (!existing) {
        const state=addBattleTransientState({stateKey,sourceSide:"enemy",sourceParticipantId:enemy.id,targetSide:"enemy",targetParticipantId:enemy.id,ownerRef:{type:"skill",id},data:{committedTechnique:true,stage:1,activationActionId:actionIdOrNull(envelope)}});
        recordBattleEvidence({eventType:"enemy_committed_technique_stage1",actionId:actionIdOrNull(envelope),actorRef:createBattleParticipantRef("enemy",enemy.id),skillId:id,stateRefs:state?[state.stateId]:[],data:{automaticAttackPL:0,stage:1,commitmentPersists:true}});
        return {resolved:!!state,branch:"formation_stage",damageApplied:false,stateRefs:state?[state.stateId]:[],stage2Pending:true};
      }
      removeBattleTransientState(existing.stateId);
      const area=makeEnemyAreaDamageAction(id,collapseAttackPL,maxTargets,{excess:options.excess||null,traits:["committed_collapse"]});
      const result=area.resolve({enemy,envelope});
      recordBattleEvidence({eventType:"enemy_committed_technique_stage2",actionId:actionIdOrNull(envelope),actorRef:createBattleParticipantRef("enemy",enemy.id),skillId:id,data:{stage:2,collapseCommitted:true}});
      return {...result,branch:"collapse_stage",stage2Pending:false};
    }
  };
}

